# ==================== 物理 F 键监视 ====================
# opener_blocked_by() 靠 task._f_last_press 区分"玩家按 F 重开了一局"和"战斗判定
# 抖了一下"(抖动不会有人按 F): 按过就直接放行, 不用干等 OPENER_MIN_GAP。
#
# 【为什么写在角色文件里】: 这个时间戳原来由 src/ 下的代码写, v3.5.32 的更新用
# git 检出把 src/ 整个盖回官方版, 写入方一行都没剩。configs/custom_teams/ 不受
# 更新影响, 也是唯一能跟着"导出队伍"一起走的地方。
#
# 【为什么要单开一个线程】: 玩家按 F 是在【战斗开始之前】, 那一刻角色代码一行都
# 没在跑。也不能用 GetAsyncKeyState 的低位("上次调用之后按过没有") ——
# get_switch_priority 会被框架对每个候选反复调用, 标志位会被前一次调用吃掉。
#
# 【为什么读得到玩家、读不到宏】: GetAsyncKeyState 读硬件键盘状态; 框架和宏发的键
# 走 PostMessage 直接投递给窗口, 不经过硬件层。
F_VK = 0x46
F_POLL_INTERVAL = 0.05
F_LOG_DEBOUNCE = 1.0
F_TASK_NAME = 'FStartCombatTask'


# 监视线程: 椰果版用主程序 src/combat/AxisWatch.py 那份; 原版 OKWW 没有这个模块, 导入失败就用下面自带的同一份
# (逻辑和 AxisWatch.py 一致, 写到 task 上的标记也一样, 线程按标记只起一次)
try:
    from src.combat.AxisWatch import f_settings, start_enable_watch, start_f_watch
except ImportError:
    def f_settings(task):
        executor = getattr(task, 'executor', None)
        for group in ('trigger_tasks', 'onetime_tasks'):
            for other in getattr(executor, group, None) or ():
                if type(other).__name__ == 'FStartCombatTask':
                    try:
                        return bool(other.enabled), float(getattr(other, 'f_start_delay', 0) or 0)
                    except Exception:
                        return True, 0.0
        return True, 0.0

    def start_enable_watch(task, logger=None):
        if getattr(task, '_ww_enable_watch_started', False):
            return
        task._ww_enable_watch_started = True
        if not hasattr(task, '_ww_task_restarted_at'):
            task._ww_task_restarted_at = -1

        def watch():
            was_on = None
            while True:
                try:
                    now_on = bool(getattr(task, 'enabled', False))
                    if was_on is False and now_on:
                        task._ww_task_restarted_at = time.time()
                        if logger:
                            logger.info('auto combat re-enabled -> opener re-armed')
                    was_on = now_on
                    time.sleep(0.2)
                except Exception:
                    return

        threading.Thread(target=watch, name='ok_ww_enable_watch', daemon=True).start()

    def start_f_watch(task, logger=None):
        if getattr(task, '_f_watch_started', False):
            return
        task._f_watch_started = True
        if not hasattr(task, '_f_last_press'):
            task._f_last_press = -1

        def watch():
            try:
                user32 = ctypes.windll.user32
                user32.GetAsyncKeyState.restype = ctypes.c_short
            except Exception as e:
                task._f_watch_started = False
                if logger:
                    logger.error(f'f watch: GetAsyncKeyState unavailable ({e}), '
                                 f'the "press F to re-arm the opener" shortcut stays off')
                return
            last_log = 0
            was_down = False
            while True:
                try:
                    # 只读高位: 低位读一次就清而且整个进程共享
                    down = bool(user32.GetAsyncKeyState(0x46) & 0x8000)
                    if down and not was_down and f_settings(task)[0]:
                        now = time.time()
                        if getattr(task, '_three_fire_macro_busy', False) or getattr(task, '_ww_macro_busy', False):
                            if logger and now - last_log >= 1.0:
                                last_log = now
                                logger.info('physical F pressed while the macro is running '
                                            '(manual execution) - opener NOT re-armed')
                            was_down = down
                            time.sleep(0.05)
                            continue
                        task._f_last_press = now
                        task._f_pressed_at = now
                        if logger and now - last_log >= 1.0:
                            last_log = now
                            logger.info('physical F pressed, opener re-armed')
                    was_down = down
                    time.sleep(0.05)
                except Exception:
                    return

        threading.Thread(target=watch, name='ok_ww_f_watch', daemon=True).start()


# ==================== 自动战斗开关监视 ====================
# 【玩家手动开关自动战斗, 必须从启动轴重跑】(用户 2026-10-13: "这个轴是我们早前做的,
# 没有加自动战斗的开关一次就重启流程的代码")。
# 手动停任务不走 combat_end(), opener_armed 会跨局留在 False; 角色对象常被粘性复用,
# reset_state() 也不跑。do_perform 只在任务启用时才被调到, 站在里面看不到"刚才关过",
# 只有独立线程能观察到 enabled 的 True->False->True。
ENABLE_POLL_INTERVAL = 0.2


class Phrolova(MacroKit, NativePhrolova):
    """弗坎卜队(弗洛洛/坎特蕾拉/卜灵)里的弗洛洛, 兼【整条轴的持宏者】。

    非本队时一行不改, 整套走原版。

    由弗坎莫(Cantarella__Mornye__Phrolova)派生(用户 2026-09-16): 弗洛洛、坎特蕾拉两段原样继承那边的定稿,
    莫宁换成卜灵, 卜灵那一段照搬露丽卜(Douling__Lucy__Rebecca)启动轴卜灵的定稿。

    ================= 这条轴长什么样 =================
    启动轴(入口是弗洛洛, 由她自己的 do_perform 调进来):
        弗洛洛段 -> 切卜灵 -> 卜灵段 -> 变奏坎特蕾拉 -> 坎段 -> 变奏弗洛洛(进循环)

    循环轴(入口是弗洛洛, 上一圈结尾把她变奏出来):
        弗洛洛段(同弗坎莫 v1.1.1, 2026-10-13 同步): 第一轮 A3 -> 闪避 -> 强化A -> 普通E -> 强化A,
                  之后每轮 A1A2 -> A3 -> 闪避 -> 强化A, 【Q 在强化A 出手之后才按】;
                  回路条右边鼠标指示亮(6 音符 AND 谱曲 25 秒游戏时间冷却, 白 + 黄都要亮) -> 强化重击 -> R
                  -> 演出完补几下顶满协奏 -> 变奏坎特蕾拉
        坎(过门): 变奏入场【只为吃弗洛洛的延奏】, 到场马上切卜灵, 一下都不出手
        卜灵段:   跳 -> A(空中攻击下落) -> 落地连点 -> E -> A4(卦象栏冒出震就停)
                  -> 两段强化重击: 按卦象栏走(卦象被吃掉两个就松, 缺阴/阳补艮/补震), 读不到退回看外圈
                  -> Q -> R -> 打满协奏 -> 变奏坎特蕾拉
        坎段:     变奏 -> E -> R 大招打断 -> 【全队唯一的处决就在这里】:
                  大招演完连发 F, 处决演出一开始才按住左键预输入重击, 演完重击出手
                  -> 无缝进 8 秒强化状态 -> 普通E / 强化E(洋红环连 2 帧亮才按, 放 Q 前还亮就补按)
                  -> 声骸Q -> 协奏没满先闪避取消变身补满 -> 变奏弗洛洛
        坎特蕾拉一圈吃两次延奏(弗洛洛的、卜灵的)。
    开关一次自动战斗(或按 F 开新一局)都从启动轴第一格重跑, 见 start_enable_watch / start_f_watch。

    ================= 三条总纲 =================
    1) 【窗口锚在派生帧, 不是动作结束帧】。官方帧表(《鸣潮动作数据汇总》"角色-女")
       每个动作有"发生帧/派生帧/动作结束帧"三个数, 能接下一个动作的时刻是【派生帧】,
       动作结束帧是演完。下面所有 *_DERIVE / *_TO_* 常量都是派生帧 /60 得来的,
       旁边注了原始帧数和表里的行号, 改之前先回去查表。
    2) 【能读屏的状态一律读屏, 读不到的才计时】——【但要先量一量它到底读不读得到】。
       ok-ww 【不是每个角色都做了回路条检测】: find_mouse_forte 是【全队共用的
       一个模板】(assets 里 mouse_forte 只有一个标注), 它对某个角色亮不亮、
       亮多久, 完全取决于游戏给不给那个角色画那个提示。
       2026-08-31 把这两个模板在参考录像的【每一段在场时间】上都跑了一遍
       (脚本 forte_audit.py), 命中率如下 —— 这张表是这条轴上"哪里能读屏"的唯一依据:

         角色    段          mouse_forte 命中/采样      最高分
         弗洛洛  循环段x4     4~8 / ~200               0.68~0.73   -> 【能用】
         坎      变奏段       27~34 / ~30 (几乎全程)    0.70        -> 亮得太久, 当不了触发
         坎      大招后       110~142 / ~190           0.72        -> 同上
         莫宁    变奏+R x5    0 / ~30                  0.41~0.53   -> 【读不到】
         莫宁    大招后 x5    1~2 / ~100               0.65~0.69   -> 【一段只亮 0.05 秒】
         e_forte 三个人全部    0                        <=0.53      -> 【全队都没有】

       所以:
         弗洛洛的"六个乐声满"【是真判据】(录像 + 实机都验过), 当硬条件用;
         坎特蕾拉的强化E 用【E 图标上的 CD 读数消失】(get_cd), 不用 mouse_forte ——
           她那个提示整段都亮着, 分不出任何事件;
         【卜灵不走 mouse_forte】: 露丽卜实测她身上完全读不到, 判据是重击图标外圈的颜色(bl_ring)。
    3) 【演出期间的按键是被丢掉的、不排队】。所以永远是"连发盖住一段", 不是
       "算准某一帧发一次"; 而连发多个键必须分段, 混着发前一个键会被后一个的演出吃掉。

    ================= 改这个文件之前先读的几条 =================
    - **【启动轴和循环轴必须分开处理】**。seg_phrolova 两条轴【是共用的】, 但两边的
      入场方式不一样: 启动轴是【手动切人】(连段从 A1 起、没有输入锁), 循环轴是
      【变奏入场】(QTE 复用 A2、有 77 帧输入锁)。所以那一段的参数拆成了
      _OPENER / _LOOP 两档, 用 opener 参数分流。改之前先问自己: 用户说的是哪一条轴。
    - 【交棒不能落在大招演出里】: 大招演出期间 has_target() 读不到目标, 控制权一还
      回去就判 target lost -> 3 秒后脱战 -> 重进战斗 -> 启动轴又跑一遍, 循环轴
      永远轮不到。所以每一发大招后面都必须接一个"等演出结束"的循环。
    - 【click_resonance() 返回三元组】(clicked, duration, animated), 不是 bool。
    - 【自定义 __init__ 里跟内置版取值不同的字段会被打回内置值】: CharFactory 换类时
      先 desired_cls(...) 建新实例, 紧接着 replacement.__dict__.update(char.__dict__)
      把内置实例的同名字段全盖回去。新加的字段不受影响, 要改内置字段就在 reset_state()
      里重申一遍。
    - 【f_break() 会撞掉切人】: 击破动画带全局时停 + 队伍 HUD 消失, 切人循环读到
      not in_team 直接判脱战。所以全程 check_f_on_switch = False, 处决自己按。
    - 【本队里坎特蕾拉和卜灵都不能算奶妈】: CharFactory 把两个人都登记成
      CharType.HEALER, 而 AutoCombatTask.run() 每一轮的第一件事是 switch_healer()。
      这条轴的循环入口是弗洛洛(主C), 不关掉的话每一圈开头都要白花两次切人。
      关法见 Cantarella.py / Douling.py 里的 is_healer。

    ================= 【参考录像是 0 链弗洛洛, 用户的是 2 链】 =================
    (用户 2026-08-31 指出) 2 链及以上【进场自带 2 个乐声】, 0 链是 0 个。
    所以录像上那条"攒六个乐声"的路线在这边【会提前两层结束】——
    照抄录像的话长按重击放得太早, 协奏圈还没涨够, 大招演完不满,
    坎特蕾拉就拿不到变奏入场, 那一次延奏就白丢了。

    【所以长按重击的闸门是两个, 不是一个】: 六个乐声(长按提示亮) **且** 协奏 >= 45。
    协奏账: 强化重击 协奏回收40 + 大招 协奏回收20 = 60, 从 45 起跳 -> 105 -> 演完必满。
    音符满了继续 A 是安全的(帧表: 到上限后再获得只会顶掉最早的一层, 不会掉层),
    所以"等协奏"这段就直接拿普攻填。

    ================= 【分享到工坊之前先看这一节】 =================
    export_custom_team() 只打包三个 {角色名}.py + 一份 manifest ——
    同目录的 *.py.tool(那几个离线探测脚本)和 team.json 都不会跟着走, 所以导出是干净的。
    但下面这几处是【跟这个号/这台机器绑的】, 别人拿去要自己校:

    1. 【命座】: 这条轴是按【2 链弗洛洛】写的(进场自带 2 个乐声)。
       0 链的人要把 L_PHRO_INTRO_TO_E 调回 2.90 左右 —— 她要先 A3 + 强化A 攒够
       两个乐声才轮到 E, 见那个常量上面的推导。
    2. 【读颜色的两个判据】: CAN_EE_BRIGHT(强化E 图标亮度)和 RING_H0/H1/S/V
       (大招充能环的粉色范围)是从录像上标的, 换画质设置/HDR/滤镜可能要重标。
       重标办法: 队伍目录里的 e_bright.py.tool / ring_probe.py.tool。
    3. 【所有"多久"的数】都是拿这个号的伤害、声骸、武器跑出来的。别人的输出更高
       (回能更快)或更低, 那些 cap 和固定间隔都要跟着动 —— 好在这条轴上真正吃时间的
       几格都是【判据驱动】的(六乐声/协奏45/回路打空/强化E亮/充能50%),
       判据成立就走, 不受输出高低影响; 要调的主要是那些 *_CAP 上限。
    4. 【分辨率不用改】: 圆心、半径、各种框都是从框架的 box_* 推出来的, 跟着换算走。

    ================= 【人工闪避: 哪几格躲得起, 哪几格躲不起】 =================
    (用户 2026-08-31: "实机中我有时候会手动闪避怪物攻击, 主要是弗洛洛和坎特雷拉,
     莫宁主要在空中一般不会被攻击到")
    宏识别不了什么时候该闪避, 所以这件事由人做是对的。为此这条轴上凡是能读屏的地方
    都改成了判据驱动 —— 被打断只是多打几下, 判据照样会成立。
    还剩下这几格是【固定时长】的, 在这里闪避最容易打歪(按危害排序):

      弗洛洛 变奏后到按 E 的 1.40 秒、强化E 的 0.55 秒窗口: 闪避会把连段推后,
          但后面"六乐声 + 协奏45"是判据, 会自己等回来。
      坎特蕾拉 E->R 的 0.25 秒、重击->E 的 0.45 秒: 同上, 后面都有判据兜。

    【最安全的闪避时机】: 三个人变奏入场的那一秒多(poll_wait 那几格 —— 宏这时候
    一个键都不发, 游戏也不响应输入)、以及任何大招/处决演出期间。

    ================= 时间数字的出处 =================
    参考录像: 2026-08-30 21:22 的实机(2560x1296 @ 120fps, OBS 直录)。
    【录像本身就是墙钟】—— 画面左下角的系统时间戳跟视频时间 1:1 对得上, 没有变速。
    【但游戏倒计时不是】: 大招演出和处决带全局时停, 副本倒计时在那几段是停的
    (实测三发大招 + 一次处决合计冻掉约 13 秒), 所以量间隔一律用视频时间。
    """

    # ==================== 引擎参数 ====================

    A_INTERVAL = 0.12            # 连点普攻的间隔。再密下去只是白发, 游戏不吃
    A_INTERVAL_FAST = 0.06       # 要抢"能出招的第一帧"时用
    F_BURST = 0.20               # 单独发处决键的窗口(不点击)。
                                 # 【只发键, 不调 f_break()】—— 那个是阻塞的:
                                 # 0.5 秒起步、最长 5 秒, 期间还一直发左键
    F_BURST_INTERVAL = 0.07
    F_ANIM_TIME_OUT = 5.0        # 处决动画的等待上限(角色不同, 0.5~5 秒都有)
    F_ANIM_TAIL = 0.20           # 处决演完之后再补这么点连点。
                                 # 【别设太小】: 演完那一刻还在收招, 紧接着的键会被吞
    USE_F_BREAK = True           # 【一键关掉处决】: 处决动画带全局时停, 真要是
                                 # 怎么都对不齐, 把这个改成 False 就整条轴不打处决
    KEY_INTERVAL = 0.10          # 连发技能键的间隔

    SWITCH_TIME_OUT = 2.5        # 超过这个还没切过去就是撞在动画里了, 记一笔往下走
    SWITCH_KEY_DOWN_TIME = 0.02  # 按住更久没用而且更慢(send_key 会阻塞整个按住时长)
    SWITCH_KEY_INTERVAL = 0.0    # 每轮都重发数字键: 游戏在动作期间会拒绝切人,
                                 # 只有一直按着才能在它放行的第一帧生效
    SWITCH_SETTLE = 0.0
    UNTRUSTED_CONFIRM = 3        # in_team() 的 count 不达标时, 同一个 index 连读到
                                 # 这么多次也认 —— 一票否决会在特效盖住槽位时假失败
    TRACE_SWITCH = False         # 排查"键发了却不换人"时打开
    SWITCH_CD = 0.88             # 换人 CD(自己记账, 不读头像上那个 OCR 数字)

    LIB_FIRE_WINDOW = 0.6        # 按 R 的重试窗口。【给短】: 判据失灵时这里会一直按 R,
                                 # 把后面轮到的那一发大招白按掉
    LIB_KEY_INTERVAL = 0.05
    LIB_READ_EVERY = 3           # 每发这么多次 R 才读一次屏(读屏 0.04s, 挂一起等于把
                                 # 重试周期翻倍, 而 R 被接受只跟按键落下的时刻有关)
    LIB_ANIM_TIME_OUT = 9.0
    LIB_ANIM_TAIL = 0.15         # HUD 回来那一刻角色多半还在收招里, 那几下照样被吞
    HUD_NO_ANIM_GRACE = 0.8      # 连着这么久都读到在场 = 这一次压根没有演出

    CON_ENOUGH = 0.99            # 协奏读到这个就算满(会在 0.99 上卡一下再跳满)
    CON_POLL_INTERVAL = 0.03
    CON_WAIT_TIME_OUT = 2.5
    CON_STALL_GIVE_UP = 0.8      # 读数一动不动就别等满超时了
    CON_SAMPLE_MAX = 40
    CON_RISE_THRESHOLD = 0.15    # "协奏涨了"的判据。【别设太小】: 协奏读数是能量环的
                                 # 连通域分析, 本身每帧抖几个千分点

    OPENER_MIN_GAP = 60.0        # 防重入: 战斗判定抖一下不该让启动轴重跑

    A_LEAD = 0.20                # 最后一段只要【递出去】就行, 它的动画会在切人之后
                                 # 继续演(合轴), 所以不给它留时长, 只留这一点点保证
                                 # 有一下落在能出招的第一帧

    # ==================== 官方帧数据(60fps, 帧/60=秒) ====================
    # 出处:《鸣潮动作数据汇总》sheet"角色-女"。
    #   弗洛洛 r2332-r2449、坎特蕾拉 r346-r443。
    # 【取的都是"派生帧"】—— 那才是能接下一个动作的时刻。

    # ---- 弗洛洛(乐声上限 6 层; A3/强化A/E/强化E 每个给 1 层) ----
    PHRO_INTRO_LOCK = 1.30       # QTE 第77F前不响应输入(第71F前不能切人)。
                                 # 【地面出场技复用 A2】: 所以变奏入场之后第一下 A
                                 # 出的是 A3(给第一个乐声), 不用再走 A1/A2
    PHRO_A1_DERIVE = 0.67        # A1-2 派生40F
    PHRO_A2_DERIVE = 0.60        # A2 派生36F
    PHRO_A3_DERIVE = 0.53        # A3 派生32F
    PHRO_EA_DERIVE = 1.33        # 强化A-C6幻象 派生80F: 强化A 整串递完
    PHRO_E_DERIVE = 0.53         # E-本体 派生32F
    PHRO_EE_DERIVE = 1.17        # 强化E-3 派生70F
    PHRO_HEAVY_TO_LIB_FRAME = 2.32   # 强化重击-前置 备注: 第139F解锁大招并获得定音
    PHRO_LIB_ANIM = 3.30         # 大招-隐藏HUD 持续198F。只当兜底, 真判据是 HUD 回没回来
    PHRO_LIB_CON = 20            # 大招-前置 协奏回收20 —— 所以演出完协奏基本是满的

    # ---- 坎特蕾拉 ----
    CAN_INTRO_LOCK = 1.10        # QTE 第76F前不响应输入(第80F前不能切人)
    CAN_E1_DERIVE = 0.62         # E1-翩跹2 派生37F
    CAN_HEAVY_DERIVE = 0.67      # 重击·浮潜幻海-2 派生40F。
                                 # 【第22F 获得 8 秒强化状态】—— 这就是"预输入重击"要的东西
    # 【她这一发 R 要给长窗口 + 重试】(用户 2026-08-31 实机: "循环轴 坎的R没有放")。
    # 用通用的 LIB_FIRE_WINDOW(0.6 秒)会漏: R 是拿来【打断 E 的收招】的, 而 E1-翩跹2
    # 派生37F(0.62s) 之前发的 R 全被动画丢掉 —— 0.6 秒的窗口从 +0.25 开始, 真正能被
    # 接受的只有最后 0.2 秒左右, E 稍微晚一点出手整发 R 就没了。
    # 【长窗口不会"多放一发"】: 大招放出去 fire_lib 立刻返回(判据是队伍 HUD 掉下去),
    # 剩下的窗口根本不会跑。窗口长只在【放不出来】时才花时间, 而那时候多按几下正是我们要的
    CAN_LIB_WINDOW = 1.20        # 按 R 的窗口(期间照常连点)
    CAN_LIB_TRIES = 3            # 没放出去就边打边等能量, 再试
    # 【坎的大招能量是能读的, 而且很干净】(用户 2026-08-31 问"你能否检测坎R的能量值")。
    # 量的是 box_liberation 里的纯白像素占比(框架 current_liberation() 的算法),
    # 录像实测:
    #     能量满 / 可放     0.146 ~ 0.192
    #     大招刚放完在充能   0.019 ~ 0.057
    # 四五倍的分离, 门槛放 0.09 很稳。
    # 【但框架自带的 liberation_available() 在她身上没用】: 它走 box_highlighted,
    # 判据是"框里有没有【任何一个】纯白像素"(>0 就算可放) —— 充能中也有 2%~6%,
    # 所以那个函数对她【恒为 True】, 分不出"能量不够"和"键被动画吞了"。
    # 要判能量必须读【占比】, 不能用那个布尔。
    CAN_LIB_READY_PCT = 0.09     # 大招能量到这个占比才算可放
    CAN_LIB_CONFIRM = 2          # 连着读到这么多次才认 —— HUD 淡入那一帧会冲到 0.46
    CAN_LIB_RETRY_A = 0.60       # 每次重试之间边打边等能量的时长
    CAN_FALLBACK_HOLD = 0.50     # R 彻底没放出来时, 手动长按一次出重击·浮潜幻海 ——
                                 # 【8 秒强化状态是重击给的, 不是大招给的】(帧表 ID=6
                                 # 第22F), 所以丢了大招也不能连强化状态一起丢
    CAN_LIB_ANIM = 3.50          # 大招-隐藏HUD 持续210F(第214F前不能切人)
    CAN_EA1_DERIVE = 0.67        # 强化A1-3 派生40F
    CAN_EA2_DERIVE = 0.57        # 强化A2-2 派生34F
    CAN_EA3_DERIVE = 1.27        # 强化A3 派生76F

    # ---- 弗洛洛段 ----
    # 【E 要打断的是第一下 A 的后摇, 不是等一整轮】(用户 2026-08-31 连提两次"E放的还是慢了")。
    # 我先后错了两次, 都是同一个来源:
    #   第一版 3.80 —— 照录像抄的, 那是【人手节奏】, 宏贴着派生帧点根本不需要那么久;
    #   第二版 2.90 —— 按 0 链的音符账推的(要先 A3 + 强化A 攒够两个才轮到 E)。
    # 2 链进场自带两个乐声, 那条路线整个不成立: 第一下 A(A3) 一命中就该 E。
    #
    # 按帧表推(弗洛洛 r2332-r2449):
    #   QTE 第77F(1.28s)输入解锁 -> 第一下 A 出 A3(出场技复用 A2, 不用走 A1/A2)
    #   -> A3 发生30F(0.50s)出伤、拿到乐声 -> 【这一刻起后面全是后摇】
    #   => E 的锚点 = 1.28 + 0.50 = 1.80 秒
    # 1.80 -> 1.40 (用户 2026-08-31 实机: "循环轴弗洛洛的E可以快0.4s按")。
    # 【只动循环轴这一档】: 启动轴那边是手动切人进来的, 起点不一样, 见 O_PHRO_ENTER_TO_E
    L_PHRO_INTRO_TO_E = 1.40
    # 启动轴是手动切人进来的: 没有那 1.28 秒输入锁, 但第一下 A 是【出场技(复用 A2)】,
    # 要多走 A2 派生36F(0.60) 才轮到 A3。0.15(切人稳定)+0.60+0.50 = 1.25
    # 【两条轴的数各调各的】
    O_PHRO_ENTER_TO_E = 1.35
    # 【早按不亏】: 这个秒数只是"什么时候开始发", 真正决定它哪一帧出去的是
    # press_e_until_fired —— 早发的那几下落在动画里被丢掉、不花钱。
    # 【而且这条轴的瓶颈是协奏不是乐声】: E(强化E) 协奏回收7、还给一个乐声,
    # 早放等于早涨协奏, 对下面那个"协奏到 45"的闸门是纯赚
    PHRO_E_CAP = 1.20            # E 重发到真的进 CD 的上限, 见 press_e_until_fired
    # 【E 是两发, 不是一发】(用户 2026-08-31: "Q释放的早了应该在第二个E后面释放")。
    # 手写文字轴那句"e打断后摇并且继续a/e打出两个音符"里的两个音符 = E本体 + 强化E:
    #   E本体(ID=9)  第1F解锁 强化A / 强化E, 核心回收1 = +1, 12 秒 CD
    #   强化E(ID=10) 吃掉那次解锁, 核心回收1 = +1, 【不吃 E 的冷却】
    # 所以第二发 E 按下去时图标上明明有 CD 读数, 照样能放出来。
    # 0.85 -> 0.55 (用户 2026-08-31 实机: "按下第二个E过了1.1s才按Q")。
    # 【窗口不必盖满 0.53 秒】: press_e_until_fired 是等【CD 读数出现】才返回的,
    # 那一步本身就滞后了 0.1~0.3 秒(next_frame + OCR, 有时要两轮) ——
    # 也就是进这个窗口时 E本体 的派生帧已经走掉一半了。窗口给满 0.85 等于纯延迟
    # 【强化E 亮起之后等 0.7 秒再按】(用户 2026-09-01: "能不能尝试在弗洛洛第一发
    # 强化E亮起后0.7s后按")。
    # 【"亮起"这里是算出来的, 不是读出来的】: 坎特蕾拉那个粉环是我在录像里量出来的,
    # 弗洛洛这一段录像里大半时间 HUD 被演出盖着, 没找到干净的亮起帧 ——
    # 所以拿帧表的派生帧当亮起时刻(E-本体 派生32F = 0.53 秒)。
    # 【起点是"E本体 确认出手"】, 也就是 press_e_until_fired 返回的那一刻。
    # 那一刻是【读到 CD 跳上去】, 比真正出手晚一点(OCR + 一帧的延迟, 大概 0.1~0.2 秒),
    # 所以实际落点会比"亮起后 0.7 秒"稍微早一点点 —— 要往后挪就加 PHRO_EE_DELAY
    # 【连拍开关】(用户 2026-09-01: "OKWW自带截图 你自己截几张呗")。
    # 打开之后, 弗洛洛的 E本体 之后会连拍几张 —— 拿来【标定强化E 高亮的颜色和门槛】,
    # 就像坎特蕾拉那圈粉环是从录像里量出来的一样。
