    PHRO_SHOT_EE = False         # 拍不拍
    # 【标定她的回路满指示】(用户 2026-09-01: "弗的强化重击只能从回路条右边的指示看,
    # 那个鼠标的指示亮了就说明回路条满了")。
    # 【为什么要标】: 框架的 find_mouse_forte 是【模板匹配】, 在她身上 200 次采样
    # 只中 4~8 次 —— 日志里 重击闸门(乐声?,...,10.02s) 每次都跑满 cap,
    # 白花 6~7 秒。框架里本来就有按角色定制的 forte 模板
    # (suisui_forte2/3、forte_cartethyia_*、hiyuki_lib_forte), 说明这个指示
    # 【各角色长得不一样】, 她多半也得自己一套判据。
    # 【这一档连拍不打断连点】: 它挂在 wait_heavy_ready 自己的循环里跟着走,
