    PHRO_SHOT_FORTE_EVERY = 0.80  # 每隔这么久拍一张
    PHRO_SHOT_FORTE_MAX = 12     # 最多拍几张
    PHRO_SHOT_N = 8              # 拍几张
    PHRO_SHOT_INTERVAL = 0.14    # 每张间隔(8 x 0.14 = 覆盖 E 之后 1.1 秒)
    # 【弗洛洛的强化E 改成读屏, 用的是跟坎特蕾拉【同一圈粉环】】
    # (用户 2026-09-01: "不能识别一下强化E技能吗" + "OKWW自带截图 你自己截几张呗")。
    # 实机连拍标定(screenshots/phro_ee_*): 未亮 0.0000 / 0.0000,
    # 亮起那一下 0.1911, 之后稳定平台 0.0642~0.0725 —— 【跟坎的数几乎一样】
    # (她那边平台 0.049~0.086、亮起冲 0.26), 所以 CAN_EE_RING_* 那一组直接共用。
    # 【环是 0.32 秒亮的, 不是帧表算的 0.53 秒】—— 这就是为什么要读屏不要猜
    # 【她这一发 Q 要发到真出手为止】(用户 2026-09-01: "循环轴弗洛洛的Q似乎没有放")。
    # 【为什么会被吞】: 日志里 Q弗声骸 紧跟在 弗强化E判(出) 后面只隔 0.36 秒 ——
    # 正压在强化E 的动画里。fire_echo 是【发一次就走、不读屏】的,
    # 那一发被丢掉了也没人知道, 日志上只看得到"键发过了"。
    # 【顺利时不花额外时间】: 先发再读, 一发就中的话跟 fire_echo 一样快
    # ==== 回路满(强化重击可放)的判据: 回路条右边那个鼠标指示 ====
    # (用户 2026-09-01: "弗的强化重击只能从回路条右边的指示看, 那个鼠标的指示
    # 亮了就说明回路条满了, 也就是乐符满了就可以释放重击了")
    # 【为什么不能只靠框架的 find_mouse_forte】: 它是模板匹配, 在她身上【会漏】——
    # 实机连拍抓到铁证: 同一轮里指示【一直亮着】, 模板前两帧却判暗
    # (phro_forte_00/01 标着"暗", 而图上鼠标是亮白+左键亮黄, 跟后三帧一模一样)。
    # 漏一次这一段就跑满 10 秒 cap, 白花 6~7 秒。
    # 【标定】(实机 2 轮 x 5 帧, 见 screenshots/phro_forte_*):
    #   亮: 纯白占比 0.229~0.237, 亮黄 0.058
    #   暗: 两个都是 0.000
    # 【背景干扰排除过】: 旁边一块纯背景的对照框最高才 0.052, 而指示暗的那一轮
    # 图标框读数是【正正好好 0.000】—— 量到的是图标, 不是地面亮不亮。
    # 门槛取最差亮平台的 1/3: 0.229/3 ≈ 0.076 -> 0.08
    PHRO_FORTE_BOX = (2278, 1952, 2326, 2018)   # 3840x2160 口径, 罩住鼠标图标本体
    PHRO_FORTE_WHITE = {'r': (200, 255), 'g': (200, 255), 'b': (200, 255)}
    PHRO_FORTE_FILL = 0.08       # 纯白占比过这个数就算"回路满了"
    # 【循环轴的闸门还要看左键那块亮黄】(用户 2026-09-16: "感觉你循环轴弗洛洛操作有问题")。
    # 实机 04:02~04:06 循环轴 5 圈: 第 2 轮(2.6~5.7s)就判"色亮"开闸, 重击出了但第一发 R 全 NOFIRE
    # (多数 icon lit=False, 04:03:30 那次 True 也没放出来), 要再来一轮 重击+R 才救回来。
    # 同一段代码启动轴 6 次都是 4 轮 ~9.5s 才开闸、R 一发就出; 弗坎莫 09-11 循环轴也是 4~5 轮、R 一发就出。
    # 【只有循环轴坏, 只有换了卜灵之后坏】: 循环轴的弗洛洛是在卜灵放完 R(开阵 24 秒)之后上场的,
    # 启动轴在她之前 —— 最可能是卜灵的 buff 图标/特效把白色像素带进了这个小框, 纯白判据误报。
    # 09-01 标定真亮起: 纯白 0.229~0.237 + 左键亮黄 0.058 / 暗: 两个都是 0.000。
    # 外来的白色东西不会刚好在左键位置带一块黄 -> 循环轴两个都要亮。黄的门槛取亮平台 1/3
    PHRO_FORTE_YELLOW = {'r': (190, 255), 'g': (150, 225), 'b': (0, 120)}
    PHRO_FORTE_YELLOW_FILL = 0.02
    L_PHRO_FORTE_NEED_YELLOW = True  # 循环轴闸门: 白 + 黄都要亮(启动轴不变, 只看白)
    # 【启动轴也要白 + 黄】(用户 2026-10-13: "怎么弗洛洛启动打的那么差")。本队启动轴不等协奏(O_PHRO_GATE_NEED_CON=False)、
    # 又开着预输入, 白色误报一来就直接按住: 01:20 / 01:22 两局开局 0.61s / 1.94s 就"音符满"(白0.09 黄0.000, 亮地面透进来),
    # 按出普通重击、R 连按 42 次不出, 要重来两三轮。设 False 回到启动轴只看白
    O_PHRO_FORTE_NEED_YELLOW = True
    # 【排查截图】: 循环轴读到"白亮、黄不亮"时存一张全屏到 screenshots/(每段最多 1 张, 一次运行最多 3 张),
    # 看清到底是什么白色东西落进了框。【确认之后必须关】(定稿不留截图)
    PHRO_SHOT_GATE = False       # 09-16 实机已确认(白0.33黄0.000 被挡住、真亮 白0.25黄0.059), 关掉
    PHRO_SHOT_GATE_MAX = 3
    # 【启动轴: 强化重击一好就放, 不再等协奏】(用户 2026-09-16: "启动轴弗洛洛强化重击一旦好了马上强化重击,
    # 不再固定继续打了, 因为弗洛洛2链直接开局多给两个音符, 可以少打两个")。
    # 实机今天启动轴 6 次开闸都是 协奏0.45~0.46/0.45 —— 卡住的一直是协奏那一条, 音符早就满了。
    # 原来要协奏 45 是为了大招演完协奏满、下一个人拿到变奏; 这一队启动轴下一个是卜灵,
    # 她走跳A, 带变奏进来反而跳不起来(见 BL_INTRO_JUMP_AT), 这一条对本队启动轴没有用处。
    # 【闸门只看音符满, 启动轴也开预输入重击】(之前启动轴不开预输入, 就是怕等协奏那段空放普通重击)。
    # 设回 True 恢复"音符满 AND 协奏够"(连 0 链保底降档那套), 预输入也跟着回到只有循环轴开
    O_PHRO_GATE_NEED_CON = False
    PHRO_Q_CAP = 1.20            # 声骸重发到确认出手的上限
    PHRO_EE_WAIT = 1.50          # 等粉环亮起的上限
    PHRO_EE_GONE = 2             # 连着读到这么多次"环没了"才算按掉了
    PHRO_EE_LIT_AT = 0.53        # 强化E 亮起(= E本体 派生帧), 相对"E本体 确认出手"
    # 0.70 -> 0.10 -> -0.20 -> 0.30
    # (用户 2026-09-01: "在弗洛洛强化E亮起后0.3s就按")
    # 【这一版的 0.3 秒才是真的从"亮起"起算的】: 前面几档是拿帧表猜的亮起时刻
    # (算出来 0.53 秒, 实机连拍打脸 —— 环是 0.32 秒亮的)。现在 wait_ee_ring
    # 读到粉环才返回, 这个数挂在【那一刻】后面, 所以负数不再有意义, 只在 >0 时才等
    # 【两条轴各一个】(用户 2026-09-01: "启动轴弗的强化E按的好像没问题, 但是循环轴的
    # 强化E按的还是慢了, 需要给循环轴重新标一下, 单独再快0.4s")。
    # 【循环轴 0.30-0.40 撞到地板了】: 这个数挂在"读到环亮"之后, 最快只能是 0
    # (一亮就按)。剩下那 0.1 秒不在这个数里 —— 在 E本体 那一格,
    # 见 press_e_until_fired 里"环灭"那条出口
    # 【她这一段有好几发强化E】(用户 2026-09-01: "启动轴的第一个强化E没有在0.3s后按,
    # 第二个做到了, 第三个又没做到")。原来只按一发、也只给那一发挂了延迟 ——
    # 所以有的"做到了"有的没有。现在【每一发都走同样的流程】: 等环亮 -> 等 delay
    # -> 按到环灭, 反复到没环了或者预算用完。
    # 【进门就亮着也照样等 delay】: 那种情况下"亮起"发生在过去, 但用户要的是
    # 【每一发前面都有那段间隔】, 一致比精确更要紧
    # ==== 强化普攻循环(用户 2026-09-01 重新给的流程) ====
    # 【一轮长这样】: [强化普攻亮] --0.3s--> 闪避 -> A -> E -> Q -> AAAAA(等下一次亮)
    # 【循环轴第一轮不一样】: 变奏进场时强化普攻【已经挂着】, 所以那一轮是
    # 连点把它打出去(等指示灭) -> 马上接 E -> Q -> AAAAA, 中间没有闪避那一下。
    # 【出口是音符收集满】; 启动轴还要协奏够(见 PHRO_CON_BEFORE_HEAVY)。
    # 【判据借用同一格粉环】: 那圈粉环就是用户口里的"强化普攻" ——
    # 之前叫它强化E 是我起错了名字, 读的一直是同一格(实机标定 亮 0.06~0.20 / 暗 0.000)
    # 0.30 -> 0.0 -> 0.10 (用户 2026-09-01: "改为强化普攻亮起0.1S后闪避")
    # 【读到亮起本身已经晚了约 0.18 秒】(PHRO_EA_READ_INTERVAL x PHRO_EA_CONFIRM),
    # 所以实际落点大概是真正亮起之后 0.28 秒
    PHRO_EA_DELAY = 0.10         # 强化普攻亮起 -> 闪避, 中间等多久(0 = 立刻闪)
    PHRO_EA_LIT_CAP = 4.00       # 等强化普攻亮起的上限(期间一直连点)
    PHRO_EA_DARK_CAP = 3.00      # 循环轴第一轮: 等它被打灭的上限
    PHRO_EA_TAIL = 1.20          # E->Q 之后那串 AAAAA 至少打这么久再开始找下一次亮
    PHRO_EA_TOTAL = 14.0         # 整段预算, 到点就走(卡死比少几发强化普攻糟)
    PHRO_EA_ROUNDS = 6           # 最多转几轮
    PHRO_EA_E_CAP = 0.60         # 那一发 E 重发到确认出手的上限
    # 【第一轮的 E 要出成普通E, 不是强化E】(用户 2026-10-12: "优化一下弗洛洛攒音符的流程,
    # 我总感觉我们攒的慢了")。
    # 【环 = 强化A/强化E 解锁】: A3、普通E 出手第 1 帧解锁, 用掉一个强化A 或强化E 两个一起灭。
    # 环亮着时按 E 出的是【强化E】(没有 CD), 环灭了按 E 才是【普通E】(12 秒 CD, 并且重新点亮环)。
    # 【原来那一步一直在出强化E】: 闪避后那 0.2 秒"接A"整个落在闪避 21 帧里被吞, 环还亮着就按了 E。
    # 录屏 2026.10.12 22.19.49 四圈循环轴, E 图标【一次 CD 数字都没出现过】(Q 每圈都有 25 秒 CD),
    # 日志每圈 弗E(cap(环先亮),x5,基线0.0/顶0.0)。第一轮只拿到 2 个音符, 要转 3~4 轮才攒满。
    # 【教学视频「弗洛洛4a8赫」(E:\轴视频) 的第一轮】: A3 打中 -> 闪避 -> 强化A -> 普通E -> 强化A,
    # 4 个音符; 演示里入场到 6 个音符 5.4 秒, 我们 7.5 秒。
    # 【现在】: 闪避后连点 A 直到环灭(强化A 出去了) -> 按 E(普通E, 环重新亮) -> 连点 A 到环灭(第二个强化A)
    # -> 照旧接 Q / 闪避。设 False 回到原来"闪避 -> 接A 0.2 秒 -> 按 E"
    PHRO_EA_E_BODY = True
    PHRO_EA_E_PREP_CAP = 1.00    # 按 E 之前连点 A 等环灭的上限(盖过闪避 0.35 秒 + 强化A 出手)
    # 【按 E 之前没读到环, 先不点 A 再看这么久】(用户 2026-10-13, 弗坎卜录屏 01.23.41 L1):
    # 等 A3 音符等久了(0.75s)A3 已经能被打断, 闪避真的放出来, 闪避那 ~0.3s 技能栏变暗、环看不见;
    # 原来只读一帧就判"环已经用掉了"直接按 E, E 落在闪避和接着的强化A 里全被吞, 第一轮没有普通E。
    # 环是挂着等人用的, 真亮着一定会再露出来; 真灭了(接A 已经打出强化A)只多等这一下
    PHRO_EA_E_RING_LOOK = 0.40
    PHRO_EA_E_LIT_CAP = 0.60     # 普通E 出手后等环重新亮的上限(不点 A, 免得把环用掉了还没看见)
    PHRO_EA_E_A2_CAP = 1.20      # 普通E 之后连点 A 等环灭(第二个强化A)的上限; E 第 30F 前 A 接不上
    PHRO_EA_A_AFTER = 0.20       # 闪避之后先接多久的普攻, 再按 E
    # 【第二发闪避(替代Q的那个)往后挪一点】(用户 2026-09-01: "闪避A闪避,
    # 后面那个闪避慢0.1s试试, 有时候A没打出去")。
    # 【为什么 A 会没打出去】: 帧表里通用闪避【没有派生帧】、动作结束帧 21F(0.35秒),
    # 而 PHRO_EA_A_AFTER 才 0.20 秒 —— 那一段的点击全落在闪避动画里被丢掉。
    # 真正让 A 落地的是后面 press_e_until_fired 期间的连点; E 一发就中的话
    # 那段很短, 紧接着的闪避就把 A 顶掉了。这个数就是给 A 留的空
    # 0.10 -> 0.20 (用户 2026-09-01 实机: 还是没给够 A 落地的时间)
    PHRO_EA_Q_DODGE_DELAY = 0.20 # Q 在 CD 改发闪避时, 先等这么久
    # 【进场之后先打多久才开始认这次亮起】(用户 2026-09-01: "启动轴第一个闪避慢了1.1s")。
    # 【原来慢在哪】: 循环【之前】还有一段 macro_spam(a_to_e) 盲打 1.35 秒,
    # 那段里没人看环 —— 强化普攻在那 1.35 秒里(甚至进场就)亮了也白亮,
    # 1.35 - 0.30 ≈ 1.05, 正好是用户说的 1.1 秒。
    # 【现在那段盲打没了】: 循环自己的连点兼做"等亮起", 这两个常量只当下界 ——
    # 保证起手还是有几下 A, 而不是一进场就闪避
    O_PHRO_EA_MIN_A = 0.25       # 启动轴: 进场先打这么久
    L_PHRO_EA_MIN_A = 0.0        # 循环轴: 第一轮要打掉入场那个, 本来就该立刻上手
    # 【读环的节奏】: 原来借 CAN_E2_RING_* (0.10s x 3 = 0.3 秒延迟)。
    # 【这里的延迟直接加在闪避上】, 所以读密一点; 连读 3 次仍然挡得住单帧闪光
    PHRO_EA_READ_INTERVAL = 0.06
    PHRO_EA_CONFIRM = 3
    # 【指示一亮就当场按住左键】(用户 2026-09-01: "能不能做到回路条右边检测小鼠标
    # 亮起一瞬间开始预输入重击")。
    # 【省下来的是什么】: 原来闸门成立之后还要 返回 -> 记 mark -> 再读一次屏 ->
    # 回到段里 -> hold_heavy 进门再读一次屏, 才轮到 mouse_down。
    # 现在在【读到那一帧的循环里】直接按下去。
    # 【按下之后必须立刻 break】: 那个循环还在连点, 而 click 是 down+up ——
    # 多点一下就把我们刚按住的手松开了
    PHRO_PREHOLD = True          # 循环轴: 闸门一成立就按住(设 False 回到老行为)
    # 【鼠标指示 = 6 个音符 AND 谱曲冷却好了】(2026-10-12 录屏 23.36.35 量的):
    # 谱曲终末(强化重击)有 25 秒冷却, 按【游戏时间】算 —— 挑战倒计时上 上一发重击 -> 指示亮
    # 是 25.04 / 25.12 / 25.4 秒; 大招演出时游戏时间停, 墙钟上约 39 秒。
    # 循环轴四圈里三圈都是音符先满、再过 1.1~1.5 秒指示才亮, 指示亮 -> 按住 0.1 秒内、重击 0.3 秒出手。
    # 【那 1.1~1.5 秒不是读晚了, 也不能提前按】: 指示没亮长按 = 普通重击(见 phro_forte_full)
    # 【循环轴: 闪避 / 接A / Q 这几步之间也查闸门】(用户 2026-10-12: "明明音符满了没有马上接上重击")。
    # 原来闸门只在"连点等环"里查, 读到环亮之后 闪避 -> 接A -> Q 那 1 秒里不看:
    # 第 2 圈第三轮指示在读到环亮后 0.07 秒就亮了, 照样闪避、接A、放Q, 1.2 秒后才按住重击
    L_PHRO_GATE_IN_STEPS = True
    # 【一轮的收尾: 连点到环灭 -> 当场 Q / 闪避】(用户 2026-10-13: "特别是Q释放的应该不对,
    # 开头4个音符打的还行, 后面2个接的太慢了")。
    # 【Q 抢在强化A 前面出去了】: 录屏 00.05.00 四圈循环轴的第二轮全都只拿到 1 个音符(A3)。
    # 接A 那 0.2 秒还落在 A3 动作里, 紧接着就按 Q —— 声骸抢先出手, 环(重世)跟着没了, 强化A 根本没出,
    # 第 6 个音符只能等第三轮, 第 5->6 个隔 3 秒。上一份录屏能拿到, 是 A3 刚好先派生出强化A、Q 晚一帧, 碰运气。
    # 教学视频: 强化A 出手 0.13~0.2 秒后接 Q, 两个都出伤, 音符照拿(变彩乐)。
    # 【第一轮收尾慢 0.6 秒】: 读环跟查闸门轮流读, 环灭 0.33 秒才认; 再读 Q 冷却、再连点 0.2 秒才闪避。
    # 演示里 第 4 个音符 -> 下一次 A3 环亮 2.0 秒, 我们 2.6~2.7 秒, 差的全在这一段。
    # 【现在(只管循环轴)】: 每轮 闪避/接A 之后连点到环灭 -> 当场 Q(冷却提前读好) / Q 在冷却就当场闪避,
    # 不再等 PHRO_EA_Q_DODGE_DELAY(那 0.2 秒是给"A 没打出去"留的, 现在环灭就是打出去了)。
    # 【这一段只读环、不查闸门】: 第 6 个音符就是这一发强化A 给的, 它出手之前指示不可能亮;
    # 第一轮 E 那几步同理(那时最多 3 个音符)。查闸门挪到环灭之后、Q 之前
    L_PHRO_EA_TAIL_AFTER_DARK = True
    L_PHRO_EA_TAIL_DARK_CAP = 1.00   # 连点等环灭的上限; 到点照样 Q / 闪避
    # 【启动轴的保底: 给 0 链玩家】(用户 2026-09-01: "需要同时满足协奏值35以及
    # 重击检测亮起才可以重击R接流程")。
    # 【为什么要保底】: 45 那条线是照着有链的算的 —— 强化重击(+40) 和大招(+20)
    # 要从 45 起跳才填得满协奏。0 链攒得慢, 等不到 45 就会一直空转,
    # 到点了照样往下走反而更糟(那时候连指示都不一定亮)。
    # 【降的只是协奏那一条, 指示那一条不降】: 提示没亮就长按, 出来的是【普通重击】,
    # 既没有那 40 点协奏也拿不到定音状态(大招不解锁), 整圈全塌 —— 这条是硬的。
    # 【降档之后还等不到就干脆不打这一发】: 见 hold_heavy 的 skip_if_dark
    PHRO_CON_FALLBACK = 0.35     # 保底档的协奏线
    PHRO_EA_FALLBACK_CAP = 6.0   # 降档之后再给这么久
    # 【循环轴第一轮那发闪避是定点的, 不看环】(用户 2026-09-01: "循环轴我从实机看
    # 你没有闪避, 应该从开始A算起0.9s后闪避")。
    # 【为什么这一轮只能定点】: 循环轴第一轮走的是"等入场那个强化普攻被打灭",
    # 那条路上【没有一次亮起可以当锚点】—— 它进场就亮着。而且闸门要是在第一轮之后
    # 就满了, 整段会一次闪避都没有。
    # 【从这一轮的连点起算】: 也就是变奏入场锁结束、开始出手的那一刻
    # 0.90 -> 0.30 -> 【改成事件锚定, 这个数不再用】(用户 2026-09-01 问
    # "为什么循环轴闪避有的好有的不好", 查日志查出来的):
    #   第一轮走哪条路【是不确定的】—— 进场那一瞬间环亮着就走"打掉入场强化普攻",
    #   没亮就走"等亮起"。两条路的闪避规则完全不同, 表现自然不一样。
    #   而走"打掉"那条时【定点闪避几乎必然跳过】: 实机 弗打掉入场强化普攻(到,A x5,
    #   0.26s) —— 那个强化普攻 0.26 秒就被打灭了, 循环早退出了, 0.30 秒还没轮到。
    # 【B 方案: 环一灭就闪避】—— 环灭 = 那一发强化普攻打出去了, 正是要取消后摇的
    # 时刻; 这样两条路的语义统一了(都是"强化普攻打完 -> 闪避取消后摇"),
    # 而且不会再因为时刻浮动而跳过
    L_PHRO_EA_DODGE_ON_DARK = True   # 循环轴第一轮: 环灭了就闪避
    # 【读到环灭之后再等一会才闪】(用户 2026-09-01: "循环轴第一下闪避慢0.3s")。
    # 【这段是连点着过的】(macro_gap 跟随持续普攻), 不是干等 —— 强化普攻刚打出去,
    # 那几下 A 正好接在它后面
    L_PHRO_EA_DARK_TO_DODGE = 0.30
    L_PHRO_EA_DODGE_AT = 0.0     # 保留定点那条路(>0 就用定点, 0 = 只走事件锚定)
    # 【循环轴第一轮: 等 A3 打出来的音符到了再闪避】(用户 2026-10-12: "循环轴里音符打的
    # 并不稳定, 有时候一下3个有时候4个")。
    # 【少的那个是 A3 的音符】: 录屏 23.36.35 第 2 圈(23:34:43)第一轮只有 强化A/E/强化A 三个,
    # 另外三圈是 A3/强化A/E/强化A 四个。变奏入场后第一下 A 就是 A3(致命组歌之后短按 = 普攻第3段),
    # 环在 A3 第 1 帧就亮, 但 A3 要吸附过去才打中 —— 四圈里音符都在读到环亮之后 0.6~0.7 秒才出来,
    # 而接A 在 +0.55 秒左右就把强化A 派生出来了, 正好卡在 A3 打中前后;
    # 那一圈 Boss 离得远, A3 还没打中就被强化A 切掉了。
    # 【现在】: 读到环亮之后不点 A, 盯着回路条等第一个音符(连续 2 帧), 再 闪避 -> 接A;
    # 到上限没等到就照旧往下走。只管循环轴第一轮 —— 那一轮音符一定从 0 开始(指挥状态结束清空)。
    # 代价是那一轮的强化A 晚 0.2 秒左右; 循环轴出重击的时刻是谱曲冷却卡着的(见 PHRO_PREHOLD 下面), 不受影响
    L_PHRO_EA_A3_NOTE = True
    # 1.00 -> 0.80: 10-13 实机 到 0.37 / 0.40 / 0.50 秒, 另一次 1.03 秒 cap(那一下 A3 没打中, 白等)
    L_PHRO_EA_A3_NOTE_CAP = 0.80     # 读到环亮 -> 等音符的上限
    L_PHRO_EA_A3_NOTE_CONFIRM = 2
    # 【进场那一下读到环亮要连读确认】: 单帧会被变奏入场的粉色特效骗到 —— 第 2 圈 1.31 秒读到"亮",
    # 接下来 0.1 秒就读成灭, 于是走了"打掉入场强化普攻"那条, 0.3 秒后闪避; 录屏上那时候环根本没亮
    L_PHRO_EA_ENTRY_CONFIRM = True
    # 【回路条上的 6 个音符槽】: 3840x2160 口径, 第 i 格中心 x = X0 + DX*i。
    # 录屏标定(2K 和缩到 1080 一样): 有音符 0.15~0.38, 刚到那一帧闪到 0.4~0.65, 空槽 0.00~0.07;
    # 变奏入场/受击时整条会被染红, 所以要求"后面的空槽全干净 + 有音符的格不过亮"才算这一帧
    PHRO_NOTE_X0 = 1732
    PHRO_NOTE_DX = 82.5
    PHRO_NOTE_HALF_W = 24
    PHRO_NOTE_Y = (1950, 2018)
    PHRO_NOTE_RED = {'r': (150, 255), 'g': (0, 110), 'b': (0, 255)}    # 弦乐(红)
    PHRO_NOTE_BLUE = {'r': (0, 255), 'g': (0, 120), 'b': (150, 255)}   # 管乐(蓝) / 彩乐(紫)
    PHRO_NOTE_ON = 0.10
    PHRO_NOTE_OFF = 0.08
    PHRO_NOTE_FLASH = 0.65
    # 【第一轮那个音符认形状, 不认颜色】(用户 2026-10-13: "第一次循环轴弗洛洛音符打的不对")。
    # 录屏 00.29.21 第 1 圈: A3 的音符读到环亮后 0.1 秒就到了, 但回路条底下全是她打出来的红色地面特效,
    # 空槽也被染红, 上面那组颜色读法一帧"干净"的都没有 —— 一直不点 A 干等满 L_PHRO_EA_A3_NOTE_CAP,
