    # A4 打完那一刻读卦象栏, A4 的震一出现就停 A(心卜穗 10-09: 比等外圈转蓝早 ~0.3s)
    # 补卦象: G = A1A2 补艮(只点出 A1A2, 再点会排出 A3), Z = 跳A 下落补震; 最多补 BL1_FIX_MAX 次, 每步做完重读重排
