    CAN_INTRO_TO_E = 1.10        # 变奏 -> E。实测 1.07/1.14, 就是那 76 帧输入锁
    # E -> R。实测只有 0.15~0.25 秒。文字轴写的是"看到涨一格回路后开大打断",
    # 而 E1-翩跹1 第14F(0.23秒)就给核心, 所以【固定 0.25 秒等于读那一格】——
    # 真去读回路格数反而更慢更脆(那条能量条是 4 段小格, 没有现成判据)
    CAN_E_TO_LIB = 0.25
    # 【大招演出期间一直按住左键】: 演出一结束无缝接重击·浮潜幻海 -> 8 秒强化状态。
    # HUD 回来之后再按住这么久, 保证重击真的被接受(帧表: 重击第22F才给强化状态)
    CAN_HEAVY_TAIL = 0.25
    CAN_HEAVY_TO_E = 0.45        # 重击 -> E。重击·浮潜幻海-2 派生40F(0.67秒),
                                 # 加上 CAN_HEAVY_TAIL 正好落在派生帧上
    # 【第二发普通E 常常还在 CD 上】(用户 2026-09-01: "启动轴的坎在R后没有按出普通E,
    # 虽然按了好几次但是没按出来")。
    # 【录像实测她的普通E 是 12 秒 CD】(E 图标读数 46.5s 的 11.3 一路线性到 51.0s 的
    # 6.9), 而这一段两发普通E 之间只隔 8~11 秒:
    #   press_e --0.25-- R --大招演出3.5s-- 处决2~5s --0.7-- press_e
    # 所以第二发【必然落在第一发的 CD 里】, 再按多少下也出不来 —— 这不是时机问题,
    # 是根本没得按。
    # 【跳过它是安全的】: 粉环(强化E)跟普通E 的 CD 【无关】—— 录像 49.5s 环亮着的
    # 时候 CD 还在 8.8 往下走。这一段的输出靠长按和强化E, 不靠这一发
    # 【等它转好, 别跳过】(用户 2026-09-01: "循环轴 有时候重击变身后不按普通E了,
    # 只会等强化E出来才按E")。循环轴里第一发 E 的 CD 常常剩 2~4 秒, 门槛卡 2 秒
    # 就会时灵时不灵。
    # 【等这段不亏】: 左键一直按着, 强化A 在打、回路在攒 —— 等的是 CD, 不是空气
    # 5.00 -> 2.00, 而且【还要被强化状态的剩余时间卡住】
    # (2026-09-01 实机: 一轮里 坎等E转好(4.3s) 之后 坎E(cap) + 坎A等强化E(cap,8.01s),
    # 整段塌掉; 同一份代码另一轮却好好的)。
    # 【为什么会随机】: 段首那发 坎E(x4,A x0) 是老式的 press_e —— 发完就走、
    # 【不确认】。它成没成功决定了第二发进门时 E 在不在 CD 上:
    #   没成功 -> E 还是好的, 第二发直接出(日志 顶12.0)
    #   成功了 -> E 进 12 秒 CD, 第二发进门还剩 4 秒多
    # 【为什么等不起】: 重击给的强化状态【只有 8 秒】, 强化E 只在这 8 秒里会亮。
    # 等掉 4.3 秒 + 发 E 1.2 秒 = 只剩 1.9 秒, 环根本来不及亮。
    # 【所以真正的闸不是秒数, 是剩余窗口】: 见 CAN_BUFF_KEEP
    CAN_E2_WAIT = 2.00           # 等普通E 转好的上限, 超过这个数直接放弃
    CAN_BUFF_SECS = 8.00         # 重击·浮潜幻海 给的强化状态时长(帧表 ID=6 第22F)
    CAN_BUFF_KEEP = 5.00         # 【必须给强化E + Q 留下这么多】, 不够就不等 E
    # ==== 重击变身之后那一段: 一个读屏循环, 两件事同时盯 ====
    # (用户 2026-09-01: "首先这个就应该靠检测来, 不是靠运气。坎重击变身后,
    #  普通E cd转好了就点普通E, 等强化E亮起就点强化E")
