    # 而且这个窗口 poke=True, 期间照常连点, 不是干等
    # 【连发要在"Q 真的进 CD"那一刻停下来】(用户 2026-08-31 实机: "坎的Q接闪避没有
    # 出来, 实际上应该Q cd了马上闪避接着A")。
    # 原来是跑满整个窗口才闪避 —— Q 要是 0.3 秒就放出去了, 后面还要空发 1.7 秒,
    # 等闪避递出去时变身动画早就把它吃掉了。
    # 【stop_when 用 get_cd('echo') 是安全方向】: refresh_cd 漏读时 CD 会被清成 0,
    # 也就是"还没进CD" —— 那只会让连发多跑几轮, 不会提前停
    CAN_Q_DODGE_PRESSES = 2      # 闪避发几次(单发会被变身动画吞掉)
    CAN_Q_DODGE_INTERVAL = 0.15
    # 1.40 -> 2.00 (用户 2026-08-31 实机: "还是没有按出Q, 加到2s")。
    # 帧表算出来的 1.23 秒不够 —— 说明实际吃掉按键的那一段比 E3 的派生帧长
    # (强化A3-水母那一串 派生76F、或者被怪打断都会再往后拖)。
    # 【加长这个窗口几乎没有代价】: 声骸脱手, 落 CD 上的按键是空操作;
    # 窗口内 poke=True 照常连点; 唯一的代价是后面那个"闪避取消Q"跟着晚一点
    # 2.00 -> 4.00 (用户 2026-08-31 实机: "坎R后被打断了, Q也没放出来, 可能被打断的
    # 时间吞掉了。Q技能的连按延长到4s")。
    # 【被打断跟被演出吞不一样】: 演出那种 spam_ae 会把时长从 cap 里扣掉,
    # 但"被怪打了一下、动作被中断"是不掉 HUD 的 —— 窗口照样在烧, 而那几秒里
    # 发出去的键全丢。唯一的办法就是把窗口给够。
    # 【不怕给大】: 有 stop_when(Q 一进 CD 就停), 顺利的时候 0.2~0.3 秒就退出来了
    CAN_Q_SPAM = 4.00            # 声骸的盲连发窗口(有 stop_when, 放出去就提前结束)
    CAN_Q_INTERVAL = 0.10
    # 【判据是"CD 跳上去了", 不是"CD 大于零"】(用户 2026-09-01: "循环轴进去以后
    # 有时候Q还在cd, 你直接认为可以切了, 这不行")。
    # 【上一圈残留的 CD 会让第一次读屏就成立】—— 那一发 Q 根本没发出去就交棒了。
    # 这跟 wait_e_ready 那里是同一个坑: 【"条件成立就往下走"的判据, 必须先确认
    # 进门时条件是不成立的】, 否则残留状态会直接把它点着。
    # 做法: 进门先读一次 CD 当基线, 只有读到【比基线高出一截】才算这一发放出去了。
    # 【残值也会衰减】: get_cd 返回的是"还剩多少秒", 只会往下走 —— 所以拿固定基线比
    # 是安全的, 不会因为时间流逝而误判
    CAN_Q_CD_RISE = 1.50         # CD 比基线高出这么多秒才算"这一发进 CD 了"
    # 【Q 还在 CD 上时要等够】(用户: "得等强化E打完Q重新进入cd才能切")。
    # 窗口按剩余 CD 加一点余量算, 但封顶 —— 卡死比少一发声骸糟
    CAN_Q_CD_EXTRA = 2.00        # 在剩余 CD 之外再给这么久
    CAN_Q_MAX_WAIT = 10.0        # 连发窗口的硬上限
    # 【基线要读几次取最大】: get_cd 底下是 refresh_cd, 它【先把三个 CD 清零再用 OCR
    # 填回去】—— 漏读一次就读成 0。基线要是撞上这一下读成 0, 上面那个判据会从后门
    # 把同一个 bug 放回来(真实剩 6 秒, 下一次读到 6 > 基线0+1.5 -> 又误判成"放出去了")。
    # 【OCR 漏读只会读低不会读高】, 所以基线取几次里的最大值是对的方向
    CAN_Q_CD_PROBES = 3          # 基线读几次
    CAN_Q_FIRED_CONFIRM = 2      # "跳上去了"要连续读到几次才认
    # 【处决放在"大招演出 + 预输入重击"那一格里, 不掺进后面的 A/E 连发】
    # (用户 2026-08-31: "这个F好像会把普通E给打断。能不能把F放到坎R后? R的时候
    # 不是要预输入重击吗, 这个预输入放在处决动画里, 坎R了就一直按F")。
    # 【为什么这样最省】: 大招演出 -> 处决演出【串在一起】, 中间那一下预输入重击
    # 只花一次, 而且落在【最后】—— 8 秒强化状态从处决演完才开始烧, 一秒不浪费。
    # 【掺在 A/E 连发里为什么不行】: 实机验证 F 会把她的普通 E 打断。
    CAN_F_INTERVAL = 0.15        # 按处决键的间隔(演出里的按键被丢掉, 要密一点)
    # 【怪身上没有处决提示就别等】(用户 2026-09-01: "如果怪没有F 坎的流程就会乱,
    # 不会马上重击变身, 因为处决的动画没了, 这里要检测如果没处决马上重击")。
    # 【原来错在哪】: 没处决时照样把 CAN_F_WAIT(1.2秒) 连发满才往下走, 那 1.2 秒里
    # 还在连点普攻 —— 重击变身整整晚 1.2 秒, 8 秒强化状态白丢一大截。
    # 【判据直读模板, 不用 task.check_f_break()】: 那个方法里的 can_break 是【粘的】
    # (只有框架自己的 f_break() 会清), 而这里是我自己发 F 键的, 清不掉 ——
    # 拿它当判据会一直读到"有提示", 等于没判。
    # 【探测窗口为什么能这么短】: 谐度是被大招打破的, 提示在大招演完那一刻就该在了;
    # 真要是晚出来, 下面 in_team() 掉下去那一路照样接得住
    CAN_F_PROBE = 0.35           # 探这么久没看到提示, 就当这只怪没处决
    CAN_F_PROBE_INTERVAL = 0.08  # 探测的读屏间隔
    CAN_F_TPL = 0.92             # 处决提示模板的阈值(跟框架 check_f_break 一致)
    CAN_F_WAIT = 1.20            # 大招演完之后, 连发处决键等它触发的上限。
                                 # 【等不到也不亏】: 这一段一直在连点普攻;
                                 # 到点就直接按住拿那 8 秒强化状态
    CAN_ANIM_SETTLE = 0.35       # HUD 连续回来这么久才算两段演出都完了 ——
                                 # 大招演完到处决演出开始之间 HUD 会闪回来一下
    CAN_HOLD_ANIM_CAP = 10.0     # 按住跨演出的总上限(大招 3.5 + 处决最长 5 + 余量)
    CAN_Q_TO_DODGE = 0.10        # 声骸【进CD那一刻】-> 闪避。给这么小是因为连发已经
                                 # 在进 CD 时停了, 不用再等。
                                 # 【她的声骸是变身型, 动画很长】, 不取消要站着演完
    CAN_Q_TO_INTRO = 0.30        # 闪避/处决之后 -> 开始"连发到协奏满"那一段
    CAN_Q_CAP = 1.20             # 声骸重发到进 CD 的上限, 见 fire_echo_until_fired
    # 【已不用】: 坎段的处决改成掺进 A/E 连发里(CAN_F_INTERVAL), 不再单独占一格。
    # 留着这个数是记录: 分步版那会儿它是 0.25 秒
    CAN_F_WINDOW = 0.25
    # 2.00 -> 4.00, 并且把"读数不动就放弃"的门槛也放宽(用户 2026-08-31 实机:
    # "提前切弗洛洛了, 坎协奏都没满")。
    # 【这一次交棒的变奏是【必须】拿到的】: 弗洛洛整段都建立在"变奏入场"上 ——
    # 没有变奏就没有那 1.28 秒输入锁、连段起点也不一样, 整圈跟着错位。
    # 所以这里宁可多打两秒也要等满, 而不是像别的格子那样"到点就走"
    # 【收尾要等两件事: 回路打空 + 协奏满】(用户 2026-08-31 实机: "明显坎的回路没A完
    # 就切弗洛洛了")。
    # 【强化E 就绪跟回路打没打空【没关系】】—— 录像 loop3 里大招一演完(115.2s)
    # 强化E 就亮了, 而回路要到 79.55s 那种时候才打空。所以"连发到强化E 出手"停下来时,
    # 回路多半还剩一大截; 收尾这一段必须自己再等回路。
    # 【收尾分两轮, 中间补一次重击】(用户 2026-08-31: "坎R后被打断了, 流程就乱了,
    # 没打完回路就切弗洛洛了" / "一定要确保回路A完再切弗洛洛")。
    # 【被打断真正毁掉的是"进没进强化状态"】: 预输入重击没接上 -> 没有 8 秒强化状态
    # -> 平A 出不了强化A -> 回路【根本消不掉】。这种情况下光加长上限只是站着白等。
    # 所以第一轮打不空就【长按一次重新拿 8 秒强化状态】再打第二轮 ——
    # 重击·浮潜幻海 本来就是回路满时才能出的招, 回路还满着正好能出。
    CAN_TAIL_CAP = 6.00          # 收尾连发【每一轮】的上限
    CAN_TAIL_ROUNDS = 2          # 打不空就补重击再来一轮
    CAN_TAIL_MIN = 0.30          # 收尾这一段的前这么久不判 ——
                                 # 刚闪避完那几帧指示还没画出来
    # ==================== 坎特蕾拉: 大招充能环 ====================
    # 【交棒前的保底: R 的充能要到 50%】(用户 2026-08-31: "坎还得加个保底,
    # 我需要R的充能打到50%才能切弗洛洛")。
    # 【读的是图标外圈那道粉色弧, 不是纯白占比】: 纯白占比只分得出"亮/不亮"
    # (见 CAN_LIB_READY_PCT), 而这道弧是【线性的充能进度】。
    # 录像实测(圆心≈box_liberation 的中心, 半径≈0.58 倍框宽):
    #     大招刚放完        0%
    #     她交棒给弗洛洛时   56% ~ 63%     <- 用户给的 50% 门槛跟这个对得上
    #     她下一次要开R 时   100%
    # 【整段只用框架 API 写】(用户 2026-08-31: "坎那个R的检测有没有可能在原版OK的
    # 基础上进行, 因为我需要打包到工坊")。
    # 第一版是自己 import cv2 + HSV 逐角度采样 —— 能用, 但那是这个文件私有的图像代码,
    # 分享出去别人既看不懂也没法跟着框架升级。
    # 【现在的写法】: 沿环放 N 个小方块, 每块用 task.calculate_color_percentage()
    # (框架自带, is_forte_full 用的就是它)判断是不是粉的, 数有几块 = 充能百分比。
    # 用到的东西只有 ok.Box + task.get_box_by_name + task.calculate_color_percentage,
    # 全是框架公开接口; math 是标准库。
    # 【精度够用】: N=24 -> 每格 4%; 跟逐角度版对比(见 ring_boxes.py.tool):
    #     角度版 0/15/35/47/51/99%  <->  小方块版 0/12/33/33/46/96%
    # 【小方块版读数会低几个点】(46% vs 51~57%), 所以门槛用 0.45 而不是 0.50 ——
    # 折算过来大约就是用户要的"真实 50%"
    # 【为什么按框宽算半径而不是写死像素】: box_liberation 是框架按分辨率换算出来的,
    # 跟着它走就不用为每个分辨率重标
    RING_R = 0.58                # 环半径 = 这个倍数 x box_liberation 的宽
    RING_BOX = 0.055             # 小方块的半边 = 这个倍数 x 框宽
    RING_SAMPLES = 24            # 沿环放几块
    # 0.35 -> 0.12 (用户 2026-08-31 实机: 门槛设在 35% 的那一格, 实际到 60% 才切人)。
    # 【单格读数是近乎二值的】(录像量的爬升: 0.01 -> 0.12 -> 0.68), 所以门槛定在哪
    # 对【录像】几乎没影响; 但不同机器上这个数会整体偏低(配色/画质/环的粗细跟框宽的
    # 比例都不一样) —— 0.35 就变成"要等弧完全盖过这一格", 于是晚很多才触发。
    # 【录像里有的格子平台值只有 0.37~0.40】(345/0 两格), 本来就贴着 0.35, 余量为零。
    # 压到 0.12 留 3 倍余量; 弧没到的时候那一格是 0.00~0.01, 加上 RING_HALF_CONFIRM=2
    # 挡特效闪烁, 不会假阳性
    RING_FILL = 0.12             # 一块里粉色占到这个比例才算"这一段亮着"
    RING_COLOR = {'r': (150, 255), 'g': (20, 115), 'b': (80, 205)}   # 充能环的粉色
    CAN_RING_MIN = 0.33          # 【只给日志和兜底用】交棒门槛的百分比刻度
                                 # (跟 RING_HALF_ANGLE=315 对应, 见下)
    # 【判"过没过半"只读一个方块, 不读 24 个】(用户 2026-08-31: "R的检测还是会慢")。
    # 【24 个方块为什么慢】: task.calculate_color_percentage 每次都会 draw_boxes,
    # 也就是往 UI 发一个 Qt 信号 —— 一次读 24 个、每秒读 10 次 = 每秒 240 次跨线程信号。
    # 【一个方块就够】: 环是【从正上方起、逆时针】填的(实测: 8% 时只亮上方偏左那两格,
    # 46% 时边缘走到左下 285°) —— 所以"过半"就等于【弧的末端越过正下方】。
    # 角度约定跟代码里一致: 90=正上, 0=正左, 270=正下(th = 角度 - 90)。
    # 【270(正下方)不能用】: 那一格是环的【起止缺口】—— 实测充能 96% 那一帧, 24 格里
    # 唯一暗着的就是它。用它当判据的话永远不会翻 True(端到端验过, 96% 也读"否")。
    # 【每一格对应的充能百分比是实测出来的】(ring_one.py.tool 逐格量的):
    #     330 ≈ 29%   315 ≈ 35%   300 ≈ 42%   285 ≈ 46%(录像里人手交棒的位置)
    #     270 = 缺口, 不可用      255 ≈ 54%
    # 285 -> 315 (用户 2026-08-31: "可以, 这次测的很准, 试试到35%切人")
    RING_HALF_ANGLE = 315        # 判"充能够了"的那一格所在角度(315 ≈ 35%)
    RING_HALF_CONFIRM = 2        # 连着读到这么多次才认(挡特效闪一下的假阳性)
    # 6.00 -> 8.00: 现在收尾【只剩这一格】, 被打断的轮次要留出补打的时间
    CAN_RING_CAP = 8.00          # 等充能的上限。到了也走 —— 卡死比少一发大招糟
    # 【已不用】: 收尾改成"回路指示一暗就切", 不再单独等协奏
    # (用户 2026-08-31: "坎的回路已经打完了还不切弗洛洛, 只要回路条右边的指示暗了就切啊")
    CAN_TAIL_CON_CAP = 4.00
    CAN_TAIL_CON_STALL = 2.50
    CAN_TAIL_CON_STALL = 2.50    # 读数不动多久才放弃(默认 0.8 太急)

    # ---- 启动轴的开头 ----
    O_ENTER_SETTLE = 0.15        # 手动切到弗洛洛之后的稳定时间(没有变奏输入锁)

    # ==================== 生命周期 ====================

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.opener_armed = True
        self.last_opener = -1
        self.macro_t0 = 0.0
        self.macro_marks = []
        self.cur = None              # 宏执行期间"现在场上是谁", 交接记账要用
        self.holding_attack = False  # 长按要跨过切人, 按下和松开不在同一个方法里
        self.poking = False          # 【持续普攻】总开关: 打开之后所有间隙自动变连点
        self.lib_press_at = 0.0      # 最近一次按大招键的时刻, fire_lib 里落笔
        self.macro_yield_logged = 0.0
        self._ee_state = {'ready': False, 'dark': 0, 'best': 0.0}  # 强化E 判据的状态
        # 【这里也要启】: reset_state() 只在 load_chars() 时跑, 而角色对象会被粘性复用
        try:
            start_f_watch(self.task, self.logger)
            start_enable_watch(self.task, self.logger)
        except Exception:
            pass

    prehold_at = None            # 预输入重击按下去的时刻, 见 PHRO_PREHOLD
    can_buff_at = None           # 坎的 8 秒强化状态从什么时候开始, 见 CAN_BUFF_KEEP

    def reset_state(self):
        super().reset_state()
        self.opener_armed = True
        self.cur = None
        self.poking = False
        # 物理 F 键监视挂在 task 上, 每个 task 只启一次。放这里是因为 reset_state
        # 每次重读队伍都会跑, 而 __init__ 里设的字段会被 apply_team_char_classes 的
        # __dict__.update 打回内置值(线程是副作用, 不受影响)
        start_f_watch(self.task, self.logger)
        start_enable_watch(self.task, self.logger)

    # ==================== 队伍判定 ====================

    @property
    def is_in_phro_cycle(self) -> bool:
        team_members = 0
        for char in self.task.chars:
            if char is not None and char.name in {'Cantarella', 'Douling'}:
                team_members += 1
        return team_members == 2

    def opener_blocked_by(self):
        """启动轴不跑的原因; 返回 None 表示该跑。

        【这里不查任何"某个技能可用"】: BaseChar.available() 对场上/场下用的是两套
        机制 —— 场下读的是该角色【上次在场时 OCR 到的 CD 记录】, 而大招是能量门控、
        图标上没有 CD 数字, 场下那条路读的是残值。防重入靠 opener_armed +
        OPENER_MIN_GAP 就够。
        """
        if not self.is_in_phro_cycle:
            return 'team is not phrolova/cantarella/buling'
        # 【开关过自动战斗 -> 启动轴重跑】: 见 start_enable_watch。
        # 【放在 armed 判断之前、不管 armed 真假都放行】, 直到启动轴真跑了(last_opener 刷新)为止 ——
        # 只在 armed=False 那一次放行的话, 选人时三个人的 get_switch_priority 都会调进来,
        # 第二次 armed 已经是 True, 就撞上下面的 OPENER_MIN_GAP: 一圈打到一半去开关必中(2026-10-11 爱琳莫)。
        # 按过 F 且界面上配了等待秒数的话, 照样等够再跑
        restarted = getattr(self.task, '_ww_task_restarted_at', -1)
        if restarted > self.last_opener:
            if not self.opener_armed:
                self.logger.info('auto combat 重开过 — 启动轴重新武装, 从头跑')
                self.opener_armed = True
            f_press = getattr(self.task, '_f_last_press', -1)
            if f_press > self.last_opener:
                waited = time.time() - f_press
                delay = f_settings(self.task)[1]
                if waited < delay:
                    return f'F pressed {waited:.2f}s ago, waiting {delay:.2f}s for the mobs'
            return None
        if not self.opener_armed:
            return 'already armed-down (ran once this combat)'
        # 玩家按过 F 就当成"真的重开了一局"直接放行: 60 秒门槛分不清"战斗判定抖动"
        # 和"玩家重开副本", 而物理 F 键正好能分 —— 抖动不会有人按 F
        f_press = getattr(self.task, '_f_last_press', -1)
        if f_press > self.last_opener:
            waited = time.time() - f_press
            delay = f_settings(self.task)[1]
            if waited < delay:
                return f'F pressed {waited:.2f}s ago, waiting {delay:.2f}s for the mobs'
            return None
        if self.last_opener >= 0 and time.time() - self.last_opener < self.OPENER_MIN_GAP:
            return f'ran {time.time() - self.last_opener:.1f}s ago (< {self.OPENER_MIN_GAP:.0f}s)'
        if not self.task.use_liberation:
            return 'task.use_liberation is off'
        return None

    # ==================== 宏原语 ====================
    # 通用的在 src/combat/MacroKit.py (MacroKit); 这里只有这条轴自己的写法, 同名的盖过 MacroKit 的。

    def poll_wait(self, sec, tag=None):
        """等一段时间, 【不点击, 但一直刷新画面】。

        跟 macro_wait 的区别只有 next_frame: 纯 macro_wait 期间画面是冻的,
        战斗判定线程拿到的是旧帧, 容易误判 target lost(2026-08-30 实机在变奏入场
        那段静默期脱战过)。要"这段别出手"又不想让判定线程瞎, 就用这个。
        """
        start = time.time()
        while time.time() - start < sec:
            self.task.next_frame()
            self.macro_wait(0.02)
        if tag:
            self.macro_mark(f'{tag}({time.time() - start:.2f}s)')

    def macro_spam(self, window, interval=None, tag='A', max_clicks=None):
        """连点一个窗口。

        打出几段由 window 决定, 不由单次点击的时机决定 —— 动画期间的点击会被丢掉,
        连点保证总有一下落在动画刚结束的瞬间。

        【max_clicks 会提前结束整个窗口】: 循环条件是"窗口没到 and n 没到上限",
        所以封顶 2 下 + 间隔 0.12 = 0.24 秒就返回了, window 写多少都不生效。
        只在【空中】那几格用它(多余的点击会变成下落攻击), 用的时候记得窗口本身
        也要相应缩短。
        """
        interval = self.A_INTERVAL if interval is None else interval
        start = time.time()
        n = 0
        cap = int(window / max(interval, 0.01)) + 2
        max_clicks = cap if max_clicks is None else min(cap, max_clicks)
        self.macro_mark(f'{tag}_start')
        while time.time() - start < window and n < max_clicks:
            self.click()
            n += 1
            remaining = window - (time.time() - start)
            if remaining <= 0:
                break
            self.macro_wait(min(interval, remaining))
        self.macro_mark(f'{tag}_end(x{n})')
        return n

    def spam_f(self, window=None, tag='处决'):
        """发处决键, 【发的同时就在看它触发没有】。

        【为什么要合成一个循环】(用户 2026-08-30: "如果没有处决会a几下再RR,
        这里能不能优化一下检测"): 原来是"先发满 0.50 秒的 F, 再花 0.40 秒判有没有
        触发" —— 没处决的那些轮次白白占掉 0.90 秒。现在每发一次就读一帧,
        没触发就跑满 window(约 0.35 秒)、触发了立刻进演出等待。

        【绝对不调 f_break()】: 框架那个是阻塞的 —— 0.5 秒起步、最长 5 秒,
        期间还一直发左键(会打断长按、烧掉墙钟计时)。
        【触发了必须等演完】: 处决动画带全局时停, 不等的话后面每一格的固定时长
        都会被它整体推歪。
        """
        if not self.USE_F_BREAK:
            return 0
        window = self.F_BURST if window is None else window
        start = time.time()
        n = 0
        gone = False
        while time.time() - start < window:
            self.task.send_key('f', after_sleep=0)
            n += 1
            self.task.next_frame()
            if not self.task.in_team()[0]:
                gone = True
                break
            self.macro_wait(self.F_BURST_INTERVAL)
        self.macro_mark(f'{tag}(x{n},{"触发" if gone else "无"},'
                        f'{time.time() - start:.2f}s)')
        if gone:
            self.poke_until_hud_back(tag=f'{tag}Anim',
                                     time_out=self.F_ANIM_TIME_OUT,
                                     tail=self.F_ANIM_TAIL)
        return n

    def spam_then_hold(self, window, clicks, interval, tag='A'):
        """先点【固定几下】, 再把窗口剩下的时间等完(不再点)。

        【为什么不能用 macro_spam 连点】: 地面连段可以连点 —— 多出来的点击落在动画里
        被丢掉, 不花钱。【空中不行】: 空中连段只有 空中A1/空中A2 两段, 打完之后
        下一次点击就变成"空中普攻-下落", 人当场落地 —— 用户 2026-08-29 看到的
        "A4 还没出来就下落了" 就是这么来的。

        【为什么不能用 macro_spam(max_clicks=N)】: 那个参数会【提前结束整个窗口】,
        循环条件是"窗口没到 and n < 上限", 封顶四下就等于窗口只有四下的长度。

        【interval 取派生帧, 不是越密越好】: 点得比派生帧还快, 多出来的那几下并不会
        让连段推得更快(动画期间的输入被丢掉), 却会在段数用完之后立刻捅出下落攻击。
        所以这一格的"最快"就是【贴着派生帧点】。
        """
        start = time.time()
        n = 0
        self.macro_mark(f'{tag}_start')
        while n < clicks and time.time() - start < window:
            self.click()
            n += 1
            if n < clicks:
                self.macro_wait(min(interval, max(0.0, window - (time.time() - start))))
        self.macro_wait(max(0.0, window - (time.time() - start)))
        self.macro_mark(f'{tag}_end(x{n},{time.time() - start:.2f}s)')
        return n

    # ==================== 直切 ====================

    def quick_switch(self, target, click_during=None, settle=None, time_out=None,
                     read_con=False, assume_con=False, click_interval=None,
                     click_first=0):
        """按数字键直切给指定角色。

        不走 switch_next_char(): 那个要先跑 _choose_switch_target 选人(顺序是框架
        说了算), 而且每次发数字键都跟一次左键, 想不要那下 A 就没法不要。

        Args:
            click_during: 等换人生效的这段时间里继续点。默认跟随持续普攻开关。
                这几下落在上一个角色身上, 正好把他最后那一段打出来。
                【角色在空中时必须传 False】—— 那时的点击会变成下落攻击。
            read_con: 按键之前读一次协奏, 决定要不要按"带变奏"记账。
                【不便宜】(能量环连通域分析, 睡完之后第一次读屏能到 0.86 秒),
                只有真的要变奏的那几处才传 True。
            assume_con: 不读屏, 直接按满协奏记。用在【刚放完大招】之后 ——
                那时协奏必满, 而演出期间能量环读数不可信。
            click_first: 先点几下再发第一个数字键。用在"边打A边切人"的格子上:
                游戏在角色动作期间会拒绝切人, 这正是那种写法不会掐掉 A 的原因。

        Returns: 是否真的切过去了。
        """
        if target is None:
            return False
        if target is self.cur:
            # 【必须早退】: 不早退的话到场判据立刻成立, 整步 50 毫秒走完,
            # 后面那些"给他的"按键其实发在了别人身上
            self.macro_mark(f'>{target.name[:3]}(already)')
            return True
        entry = time.time()
        time_out = self.SWITCH_TIME_OUT if time_out is None else time_out
        settle = self.SWITCH_SETTLE if settle is None else settle
        click_during = self.poking if click_during is None else click_during
        click_interval = self.A_INTERVAL if click_interval is None else click_interval
        source = self.cur if self.cur is not None else self
        slot = target.index + 1
        for i in range(int(click_first)):
            self.click()
            if i + 1 < int(click_first):
                self.macro_wait(click_interval)
        # 【第一个数字键要抢在读协奏之前发】: 读协奏夹在"上一个动作"和"数字键"之间
        # 就是纯延迟, 而切人本身要 0.06~0.11 才落地, 完全来得及在换人之前读完
        self.task.send_key(slot, down_time=self.SWITCH_KEY_DOWN_TIME)
        if assume_con:
            con_full = True
        elif read_con:
            con_full = bool(source.is_con_full())
        else:
            con_full = False
        return self._await_switch(target, source, slot, entry, time_out, settle,
                                  click_during, click_interval, con_full)

    def _await_switch(self, target, source, slot, entry, time_out, settle,
                      click_during, click_interval, con_full):
        """一直重发数字键直到 HUD 确认换人生效。quick_switch 的后半段。"""
        start = time.time()
        last = start          # 第一个数字键已经在调用方发过了
        next_click = 0.0
        trace = [] if self.TRACE_SWITCH else None
        team_size = len([c for c in self.task.chars if c is not None])
        untrusted_hits = 0
        clicks = 0
        while time.time() - start < time_out:
            now = time.time()
            if now - last >= self.SWITCH_KEY_INTERVAL:
                self.task.send_key(slot, down_time=self.SWITCH_KEY_DOWN_TIME)
                last = now
            # 点击的节奏跟切人键解耦: 切人键每轮都发, 点击照旧按 click_interval
            if click_during and now >= next_click:
                self.click()
                clicks += 1
                next_click = now + click_interval
            self.task.next_frame()
            in_team, index, count = self.task.in_team()
            # 【count 不达标的 index 打折扣, 但不能一票否决】: in_team() 在只找到
            # 一个槽位文本时照样返回 True 和一个 index; 一票否决会在槽位被特效盖住时
            # 造成假失败 —— 切人明明成功了也判不出来, 卡满超时, 整条轴从这里崩
            hit = in_team and index == target.index
            trusted = in_team and count >= team_size
            untrusted_hits = untrusted_hits + 1 if (hit and not trusted) else 0
            if trace is not None:
                trace.append(f'{time.time() - start:.2f}:'
                             f'{(index if trusted else f"?{index}") if in_team else "x"}')
            if hit and (trusted or untrusted_hits >= self.UNTRUSTED_CONFIRM):
                self.handoff(source, target, con_full)
                self.macro_mark(f'>{target.name[:3]}{"^" if con_full else ""}'
                                f'({time.time() - entry:.2f}|A x{clicks})')
                if trace:
                    self.logger.info(f'switch trace -> {target.name}: {" ".join(trace)}')
                self.macro_gap(settle)
                return True
        # 【失败时更要打 trace】: 一直是旧角色的 index -> 游戏真的在拒绝切人;
        # 带 ? 的都是目标 index -> 切过去了, 是 count 判据把它挡住了;
        # 全是 x -> HUD 整个不在(演出/时停里)
        self.logger.warning(f'switch to {target.name} slot {slot} timed out '
                            f'after {time_out:.1f}s (stuck in an animation?)'
                            + (f' trace: {" ".join(trace)}' if trace else ''))
        self.macro_mark(f'>{target.name[:3]}FAIL')
        # 【失败之后必须重新对齐"场上是谁"】(卡夏风那条轴 2026-08-29 栽过):
        # 不对齐的话 self.cur 还指着目标角色, 后面整段都发在错的人身上 ——
        # 日志里 >XxxFAIL 之后照样给他发 E、开大招, 而场上其实是别人,
        # 于是后面一连串判据全是假象, 查都没法查
        actual = self.on_field_char(time_out=0.5)
        if actual is not None and actual is not self.cur:
            self.macro_mark(f'resync>{actual.name[:3]}')
            self.cur = actual
        return False

    def wait_switch_ready(self, char, tag='swCD', lead=0.0):
        """等某个角色的换人 CD 转好。

        Args:
            lead: 【提前这么多就返回】, 把剩下这段留给调用方拿去跟切人并行 ——
                quick_switch 本来就会一直重发数字键, 让它压着 CD 尾巴开始按,
                游戏 CD 一到那一帧就生效。
        """
        left = self.switch_cd_left(char)
        wait = left - lead
        if wait <= 0:
            self.macro_mark(f'{tag}(0.00|left{left:.2f})')
            return 0.0
        self.macro_gap(wait, tag=tag)
        self.macro_mark(f'{tag}({wait:.2f})')
        return wait

    def switch_out_while_key(self, target, source, key_send, click=True,
                             read_con=False, time_out=None, tag=None):
        """一边切人, 一边给【离场角色】补技能键 —— 键只在 HUD 还读得到他时才发。

        【为什么要那道门】: 切人期间发出去的技能键会被游戏【带过换人边界, 落在新上场
        的角色身上】—— 真同时发的话那一发会变成新角色放的, 白烧一个 CD。判据是
        "HUD 还显示离场角色在场 = 这一发还会落在他身上", 一从 HUD 上消失就停发。

        点击不受这道门约束 —— 点击落错人无所谓(顶多多推一段连段)。
        """
        if target is None:
            return False
        if target is self.cur:
            self.macro_mark(f'>{target.name[:3]}(already)')
            return True
        entry = time.time()
        time_out = self.SWITCH_TIME_OUT if time_out is None else time_out
        src = source if source is not None else (self.cur or self)
        slot = target.index + 1
        self.task.send_key(slot, down_time=self.SWITCH_KEY_DOWN_TIME)
        con_full = bool(src.is_con_full()) if read_con else False
        team_size = len([c for c in self.task.chars if c is not None])
        n_key = n_click = 0
        untrusted_hits = 0
        arrived = False
        next_click = 0.0
        while time.time() - entry < time_out:
            now = time.time()
            self.task.send_key(slot, down_time=self.SWITCH_KEY_DOWN_TIME)
            self.task.next_frame()
            in_team, index, count = self.task.in_team()
            if in_team and index == src.index:
                key_send()
                n_key += 1
            if click and now >= next_click:
                self.click()
                n_click += 1
                next_click = now + self.A_INTERVAL
            hit = in_team and index == target.index
            trusted = in_team and count >= team_size
            untrusted_hits = untrusted_hits + 1 if (hit and not trusted) else 0
            if hit and (trusted or untrusted_hits >= self.UNTRUSTED_CONFIRM):
                arrived = True
                break
        label = tag or f'>{target.name[:3]}+key'
        if arrived:
            self.handoff(src, target, con_full)
            self.macro_mark(f'{label}{"^" if con_full else ""}'
                            f'({time.time() - entry:.2f}|key x{n_key},A x{n_click})')
        else:
            self.logger.warning(f'switch_out_while_key: {target.name} never came in '
                                f'({n_key} keys, {n_click} clicks)')
            self.macro_mark(f'{label}FAIL(x{n_key})')
        return arrived


    # ==================== 大招 ====================

    def fire_lib(self, char, tag='R', window=None, poke=None, click_interval=None):
        """把大招发出去。判据是【队伍 HUD 掉下去 = 演出开始】。

        不用 click_liberation(): 它一路阻塞到演出结束才返回, 而这条轴上好几处要在
        演出【期间】继续做事(连点、连发 E、切人)。

        【发键之前不读屏确认可放】: 那次读屏是纯延迟; 而且它并不能替我们做决定 ——
        读到不可用我们照样要发。可用性只在失败分支里读一次, 用来分辨"能量不够"和
        "键被动画吞了"。

        Args:
            poke: 发 R 的同时点不点普攻。默认跟随持续普攻开关。
                【弗洛洛那一发必须打开】(用户 2026-08-31: "循环轴弗洛洛打到后面不A了"):
                她的窗口要给到 3.2 秒 —— 强化重击 第139F(2.32s) 才解锁大招, R 得一直
                重发到那时候。原来这一整段【一下 A 都不点】, 就是她后半段站着不动的原因。
                【点了不会打断强化重击】: 它中断优先=9、普攻是 2, 低的打不断高的,
                所以这几下要么被动画丢掉(不花钱), 要么落在"重击压根没蓄出来"的
                情况下把她救回来继续输出。
        """
        window = self.LIB_FIRE_WINDOW if window is None else window
        poke = self.poking if poke is None else poke
        click_interval = self.A_INTERVAL if click_interval is None else click_interval
        start = time.time()
        self.lib_press_at = start
        n = 0
        clicks = 0
        next_click = start
        while time.time() - start < window:
            # 【先发键再读屏】: 原来是"读一帧 -> 判HUD -> 才发R", 于是每次放大招前
            # 都白读一次屏。多发的那一下不会有副作用 —— 演出期间的按键被丢掉、不排队
            char.send_liberation_key()
            n += 1
            # 点击的节奏跟发 R 的节奏各走各的, 挂在一起会被 LIB_KEY_INTERVAL 卡住
            if poke and time.time() >= next_click:
                self.click()
                clicks += 1
                next_click += click_interval
                if next_click < time.time():
                    next_click = time.time() + click_interval
            if n % self.LIB_READ_EVERY == 0:
                self.task.next_frame()
                if not self.task.in_team()[0]:
                    char.record_liberation_use()
                    self.macro_mark(f'{tag}_fired(x{n},A x{clicks})')
                    return True
            self.sleep(self.LIB_KEY_INTERVAL, check_combat=False)
        self.task.next_frame()
        if not self.task.in_team()[0]:
            char.record_liberation_use()
            self.macro_mark(f'{tag}_fired(x{n})')
            return True
        self.macro_mark(f'{tag}_NOFIRE(x{n},A x{clicks})')
        try:
            lit = bool(char.liberation_available())
        except Exception:
            lit = 'err'
        self.logger.warning(f'{tag}: {char.name} liberation never started an animation '
                            f'after {n} presses (icon lit={lit})')
        return False

    def wait_con_rise(self, char, cap, base=None, rise=None, min_wait=0.0,
                      tag='con涨'):
        """盯着协奏圈, 一涨就返回。

        【为什么用"涨"而不是"满"或固定时长】: 这里要的信号是"刚才那一下【结算了】"
        —— 而协奏是【打中才涨】的, 所以它一跳就是结算完成的那一刻。
        重击/强化重击一下给的协奏都是一大格, 很好认; 后面那段收招没有伤害,
        用别的招打断它纯赚。

        【这条轴目前没有调用点】: 坎特蕾拉那一格的"涨一格回路"用的是固定 0.25 秒
        (理由见 seg_cantarella)。留着是因为它是调时序时最趁手的判据 ——
        要把某一步改成"等上一下结算完再走", 直接用它。

        Args:
            base: 基线。【要在动作起手【之前】读】—— 动作跑完再读的话基线里已经
                含了这一下的收益, 永远检测不到"上涨"。
            rise: 涨多少才算数。【别设太小】(用户 2026-08-30: "协奏值还没变呢你就R了"):
                协奏读数是能量环的连通域分析, 本身每帧抖几个千分点, 0.02 会被噪声
                直接触发。强化重击一下给 25 点(=0.25), 阈值放到 0.08 都绰绰有余。
            min_wait: 这之前一律不判。【为什么需要】: 长按重击的判据是"准星旁的
                提示消失", 而那个掉得比出伤早得多(招式起手就掉, 伤害要再等半秒多)
                —— 一返回就开始判的话, 等于在重击还没打出来的时候等一个永远不会来的
                上涨, 然后噪声一抖就往下走了。
        """
        rise = self.CON_RISE_THRESHOLD if rise is None else rise
        start = time.time()
        if min_wait > 0:
            self.macro_wait(min_wait)
        if base is None:
            try:
                base = char.get_current_con()
            except Exception:
                base = 0.0
        got = False
        now_v = base
        while time.time() - start < cap:
            try:
                now_v = char.get_current_con()
            except Exception:
                pass
            if now_v - base >= rise:
                got = True
                break
            self.macro_wait(self.CON_POLL_INTERVAL)
        self.macro_mark(f'{tag}({base:.2f}->{now_v:.2f},'
                        f'{"涨" if got else "cap"},{time.time() - start:.2f}s)')
        return got

    def wait_con_for_intro(self, char, next_name, poke=True, time_out=None,
                           stall_give_up=None):
        """等协奏结算到满再交棒 —— 满协奏离场, 下一个人才有变奏入场。

        伤害打中和协奏涨上去之间有延迟, 打完立刻切就没有变奏。
        【协奏必须打中才涨】, 所以这里等不到就往上游找哪笔伤害打空了, 而不是加大超时。

        Args:
            poke: 等的期间补不补普攻。【角色在空中时必须传 False】,
                那时的点击会变成下落攻击。
        """
        start = time.time()
        samples = []
        full = False
        stalled_at = None
        stalled_since = start
        next_click = 0.0
        time_out = self.CON_WAIT_TIME_OUT if time_out is None else time_out
        stall_give_up = (self.CON_STALL_GIVE_UP if stall_give_up is None
                         else stall_give_up)
        while time.time() - start < time_out:
            con = char.get_current_con()
            if len(samples) < self.CON_SAMPLE_MAX:
                samples.append(f'{time.time() - start:.2f}:{con:.2f}')
            if con >= self.CON_ENOUGH:
                full = True
                break
            # 【读数一动不动就别等满超时了】。阈值不能太小 —— 协奏会在 0.99 上卡一下
            if stalled_at is None or abs(con - stalled_at) > 0.005:
                stalled_at = con
                stalled_since = time.time()
            elif time.time() - stalled_since >= stall_give_up:
                self.macro_mark(f'con(stalled@{con:.2f})')
                return False
            now = time.time()
            if poke and now >= next_click:
                self.click()
                next_click = now + self.A_INTERVAL
            self.macro_wait(self.CON_POLL_INTERVAL)
        self.macro_mark(f'con({"full" if full else "timeout"})')
        # 轨迹是判断"上一下打没打中"的唯一手段: 一跳到顶 = 打中了, 这段等待是伤害
        # 飞行时间; 一路慢爬 = 那一下打空了, 协奏是补刀的普攻蹭上去的
        self.logger.info(f'{char.name} con {" ".join(samples)} '
                         f'{"(full)" if full else f"(never filled, {next_name} gets no intro)"}')
        return bool(full)

    # ==================== 场上是谁 ====================

    FIELD_SETTLE_TIME_OUT = 1.5

    def on_field_char(self, time_out=None):
        """现在场上是谁 —— 【只在拿不到入口角色时才用】, 因为它开局会说谎。

        in_team() 的判据是"哪个槽位的名字文本【找不到】, 谁就在场"。战斗刚开始时
        队伍 HUD 还在渐入, 三个槽位的文本不是同时出现的 —— 这时它只找到一个文本,
        但那个分支照样返回 True 和一个 index, 而那个 index 只是渲染顺序的产物。
        可信判据是 count >= 队伍人数。
        """
        time_out = self.FIELD_SETTLE_TIME_OUT if time_out is None else time_out
        expected = len([c for c in self.task.chars if c is not None])
        end = time.time() + time_out
        while True:
            self.task.next_frame()   # in_team() 读的是缓存帧, 不刷就是反复读同一张图
            in_team, index, count = self.task.in_team()
            if in_team and count >= expected:
                for char in self.task.chars:
                    if char is not None and char.index == index:
                        return char
                return None
            if time.time() >= end:
                self.logger.warning(f'team HUD never settled in {time_out:.1f}s '
                                    f'(in_team={in_team} index={index} count={count})')
                return None
            self.macro_wait(0.03)

    def wait_lib_ready(self, char, cap=2.5, tag='能量'):
        """边点普攻边等某个角色的大招能量转满(能量环亮)。

        大招是【能量门控不是 CD 门控】: 用 liberation_available()(读能量环),
        不要用 has_cd('liberation') —— 那是 OCR 读 CD 数字, 而大招图标上没有数字。
        """
        start = time.time()
        n = 0
        ready = False
        next_click = 0.0
        while time.time() - start < cap:
            now = time.time()
            if now >= next_click:
                self.click()
                n += 1
                next_click = now + self.A_INTERVAL
            self.task.next_frame()
            try:
                if char.liberation_available():
                    ready = True
                    break
            except Exception:
                pass
        self.macro_mark(f'{tag}({"满" if ready else "cap"},x{n},{time.time() - start:.2f}s)')
        return ready

    def cd_baseline(self, box_name, probes=3):
        """读几次某个技能的剩余 CD, 取最大值当基线。

        【为什么要取最大】: refresh_cd 是"先清零再 OCR 填回", 漏读一次就是 0 ——
        单次读数只会偏低。而基线偏低会让"CD 跳上去了"这个判据误判成真,
        正是我们要修的那个 bug。取最大就把这个方向堵死了。
        """
        best = 0.0
        for i in range(max(1, probes)):
            self.task.next_frame()
            try:
                v = float(self.task.get_cd(box_name))
            except Exception:
                v = 0.0
            if v > best:
                best = v
        return best

    def press_e_until_fired(self, char, cap, interval=None, tag='E'):
        """把 E 发到【真的放出去】为止 —— 一进 CD 就立刻停。

        【"发出去"和"放出来"是两回事】: 动画期间的按键是被丢掉的、不排队, 而日志上
        只看得到"键发过了"。press_e 那种固定窗口的连发是在赌"总有一下落在能出招的帧上",
        赌不中就整发丢掉 —— 症状就是用户说的【E 没打断后摇】, 看上去像根本没按。

        【判据是 CD 读数出现, 不是图标变暗】: 图标底色跟着战斗特效走, 不可靠;
        get_cd 读的是 OCR 出来的那个数字, 一进 CD 就有。

        【期间一直在连点】: macro_gap 跟随持续普攻开关, 所以重发不是干等 ——
        重发几次都不会把连段卡住。

        【坎特蕾拉也能用了】(2026-09-01): 原来不敢给她用, 是怕"图标上本来就挂着读数"
        让判据一进门就成立 —— 那个坑已经用 cd_baseline 堵了(判据是【比进门时的基线
        高出一截】, 不是"大于零")。
        """
        interval = self.KEY_INTERVAL if interval is None else interval
        # 【基线】: 同 CAN_Q_CD_RISE 那一段 —— "CD 大于零"会被上一轮的残值点着,
        # 判据必须是"比进门时高出一截"
        cd0 = self.cd_baseline('resonance', probes=self.CAN_Q_CD_PROBES)
        # 【第二条出口: 粉环亮了】: 普通E 出手第 1 帧点亮环(解锁强化A/强化E)。
        # 【更正 2026-10-12】: 09-01 当时写的"环亮着却 never entered cd = E本体 打出去了、
        # 只是 CD 读不到"是错的 —— 环亮着时按 E 出的是强化E(没有 CD), 普通E 根本没出;
        # 普通E 出了 E 图标就有 12 秒 CD 数字(教学视频和 10-12 录屏对照)。见 PHRO_EA_E_BODY
        # 【强化E 是 E本体 的派生】, 所以"环亮了"本身就是"E本体 落地了"的铁证 ——
        # 拿它当第二条出口, 比死等 OCR 靠谱
        # 【环也要取基线】(2026-09-01 实机: 弗E(出(环),x0,0.02s) —— 【一次都没按就
        # 宣告成功】, E本体 根本没发出去)。
        # 这是同一个坑的第五次(wait_e_ready / Q的CD / 弗洛洛的E / 坎的ee_gone / 这次):
        # 【"条件成立就往下走"的判据, 必须先确认进门时条件是不成立的】。
        # 【进门就亮着 = 这一发跟环没关系】: 那说明强化E 在按 E本体 之前就已经挂着了,
        # 环亮不能证明这一发落地 —— 这一次就【不用环这条出口】, 老老实实按满窗口
        try:
            self.task.next_frame()
            ring_pre = self.ee_ring_pct(char) >= self.CAN_EE_RING_FILL
        except Exception:
            ring_pre = False
        ring_hits = [0]
        start = time.time()
        n = 0
        fired = False
        # 【把读到的 CD 记下来】(2026-09-01: 弗洛洛这一发 59 次 never entered cd,
        # 而修判据之前那行是"出,x0" —— 【0 次按键就宣告成功】, 说明进门时 CD 读数
        # 本来就不是 0)。光看"出/cap"分不清三种情况, 所以要把数字带出来:
        #   基线0.0 顶0.0   = 这一格【一直读不到数】(OCR 认不出她的图标 / 她的 E
        #                     压根不显示读数) -> 判据本身用不了, 得换判据
        #   基线8.2 顶8.2   = 她的 E 【真的在 CD 上】-> 是排轴的问题, 按几次都没用
        #   基线0.0 顶16.3  = 【放出去了】, 只是没跨过 CAN_Q_CD_RISE 的门槛
        cd_top = cd0
        by_ring = ''
        while time.time() - start < cap:
            self.task.next_frame()
            try:
                cur = float(self.task.get_cd('resonance'))
            except Exception:
                cur = 0.0
            if cur > cd_top:
                cd_top = cur
            if cur > cd0 + self.CAN_Q_CD_RISE:
                fired = True
                break
            try:
                rv = self.ee_ring_pct(char)
            except Exception:
                rv = None
            if rv is not None:
                if not ring_pre:
                    # 【环从没亮变亮 = 这一发落地了】: 强化E 是 E本体 的派生
                    ring_hits[0] = (ring_hits[0] + 1
                                    if rv >= self.CAN_EE_RING_FILL else 0)
                    if ring_hits[0] >= self.CAN_EE_LIT:
                        fired = True
                        by_ring = '亮'
                        break
                # 【进门就亮着的时候, 环这条出口整个不用】(2026-09-01 实机教训):
                # 我试过拿"环灭"当出口, 结果 弗E(出(环灭),x2,0.31s) 之后
                # 弗等强化E(没亮,1.50s) —— 【环灭不是 E本体 落地】, 是那一发把
                # 【上一发还挂着的强化E】吃掉了。进这一段时环本来就亮着,
                # 按 E 先放掉的是强化E, 再按才是 E本体。提前退出的话 E本体 根本没发,
                # 环自然再也不亮。这一档就老老实实按满窗口
            char.send_resonance_key()
            n += 1
            self.macro_gap(interval)
        if fired:
            char.record_resonance_use()
        else:
            self.logger.warning(
                f'{tag}: never entered cd after {n} presses ({cap:.1f}s) —— '
                f'基线 {cd0:.1f}s, 全程最高 {cd_top:.1f}s。'
                f'【两个都是 0.0】= 这一格读不到数, 判据用不了(换判据); '
                f'【两个都非 0 且相等】= 技能真的在 CD 上(排轴问题, 按几次都没用); '
                f'【最高明显高于基线】= 其实放出去了, 只是没过 CAN_Q_CD_RISE 的门槛')
        if by_ring:
            how = f'出(环{by_ring})'
        elif fired:
            how = '出'
        elif ring_pre:
            how = 'cap(环先亮)'
        else:
            how = 'cap'
        self.macro_mark(f'{tag}({how},x{n},基线{cd0:.1f}/顶{cd_top:.1f},'
                        f'{time.time() - start:.2f}s)')
        return fired

    def fire_echo_until_fired(self, char, cap, interval=None, tag='Q'):
        """把声骸键发到【真的放出去】为止 —— 一进 CD 就立刻停。

        跟 fire_echo 的区别: 那个是"发一次就走", 建立在"声骸是脱手技能、随时都能放"
        这个前提上。前提在【动画里】不成立 —— 演出/长招期间的按键是被丢掉的、
        不排队, 那一轮的声骸就整个没了, 而日志上只看得到"键发过了"。

        【先发再读】: 第一发不花任何等待, 所以顺利的时候跟 fire_echo 一样快;
        只有被吞了才多跑几轮。期间 macro_gap 跟随持续普攻开关, 不是干等。

        【判据是"CD 比进门时的基线高出一截"】, 不是"CD 大于零" ——
        后者会被上一圈的残值点着, 一进门就说"已经放出去了"。
        这条轴上同一个形状栽过五次(wait_e_ready / Q的CD / 弗洛洛的E /
        坎的 ee_gone / 粉环), 所以这里一开始就按基线写。
        """
        interval = self.KEY_INTERVAL if interval is None else interval
        cd0 = self.cd_baseline('echo', probes=self.CAN_Q_CD_PROBES)
        start = time.time()
        n = 0
        fired = False
        hits = 0
        while time.time() - start < cap:
            char.send_echo_key()
            n += 1
            self.task.next_frame()
            try:
                up = float(self.task.get_cd('echo')) > cd0 + self.CAN_Q_CD_RISE
            except Exception:
                up = False
            # 【连读到才认】: 单帧 OCR 有把数字认到隔壁格的时候
            hits = hits + 1 if up else 0
            if hits >= self.CAN_Q_FIRED_CONFIRM:
                fired = True
                break
            self.macro_gap(interval)
        if fired:
            char.record_echo_use()
        else:
            self.logger.warning(f'{tag}: echo never entered cd after {n} presses '
                                f'({cap:.1f}s), 基线 {cd0:.1f}s —— '
                                f'被动画吞了, 还是这一格读不到数?')
        self.macro_mark(f'{tag}({"出" if fired else "cap"},x{n},'
                        f'{time.time() - start:.2f}s)')
        return fired

    def click_sequence(self, offsets, tag='A'):
        """按【绝对时刻表】点固定几下, 多一下都不点。

        【空中/观测状态专用】: 那些状态下连段是有段数的, 打完之后再点一下就变成
        "空中攻击-下落", 人当场落地。莫宁的观测状态更狠 —— 帧表明写着
        【施放空中攻击下落时移除该状态】, 状态一没, 观测重击就永远出不来。

        【为什么不能用 macro_spam】: 那个是"按窗口连点", 窗口多长就点多少下 ——
        地面连段多点几下只是被动画丢掉(不花钱), 空中多点一下就是掉下去。
        【为什么不能用 spam_then_hold】: 它只能用一个固定间隔, 而观测A 三段的派生帧
        是 21F / 39F / 39F, 不等距。点早了被吞(那一段就没打出来), 点晚了就是空档。
        """
        start = time.time()
        n = 0
        for off in offsets:
            wait = start + off - time.time()
            if wait > 0:
                self.macro_wait(wait)
            self.click()
            n += 1
        self.macro_mark(f'{tag}(x{n},{time.time() - start:.2f}s)')
        return n

    def lib_ring_half(self, char):
        """R 的充能过没过半 —— 【只读一个小方块】, 给热路径用。

        (用户 2026-08-31: "R的检测还是会慢")

        【为什么不用 lib_ring_pct】: 那个要读 24 个方块, 而
        task.calculate_color_percentage 每次都 draw_boxes(往 UI 发一个 Qt 信号) ——
        一次 24 个、每秒 10 次 = 每秒 240 次跨线程信号, 判据本身就成了卡顿源。
        百分比只在这一格【结束之后打日志时】读一次就够。

        【一个方块凭什么够】: 环是从正上方起、逆时针填的(见 RING_HALF_ANGLE 那一段),
        所以"过半"是个纯粹的位置问题 —— 弧的末端有没有越过正下方那一格。
        """
        return self.lib_ring_cell(self.RING_HALF_ANGLE) >= self.RING_FILL

    def lib_ring_cell(self, angle):
        """充能环上某个角度那一小格的【粉色原始占比】。

        【单独拆出来是为了能打进日志】: 判据本身是布尔, 但出问题时要看的是这个数 ——
        它在别人机器上会整体偏低(配色/画质/环粗细跟框宽的比例都不同),
        看一眼就知道该调 RING_FILL 还是该调 RING_COLOR。
        """
        box = self.task.get_box_by_name('box_liberation')
        if box is None or box.width <= 0:
            return 0.0
        cx = box.x + box.width / 2.0
        cy = box.y + box.height / 2.0
        r = box.width * self.RING_R
        half = max(2.0, box.width * self.RING_BOX)
        th = math.radians(angle - 90)
        cell = Box(int(round(cx + r * math.sin(th) - half)),
                   int(round(cy - r * math.cos(th) - half)),
                   int(round(2 * half)), int(round(2 * half)), name='lib_ring_cell')
        try:
            return float(self.task.calculate_color_percentage(self.RING_COLOR, cell))
        except Exception:
            return 0.0

    def lib_ring_pct(self, char):
        """读大招图标外圈那道能量弧亮了多少 (0~1) = 【充能百分比】。

        (用户 2026-08-31: "我需要R的充能打到50%才能切弗洛洛")

        【跟 liberation_available() 的区别】: 那个是布尔 —— 图标亮着【并且】没有 CD
        读数才算可放; 这个给的是【进度】, 才回答得了"到 50% 没有"。
        录像实测: 大招刚放完 0% -> 她交棒时 46%(小方块刻度) -> 下次要开 R 时 96%。

        【全程只用框架 API】: ok.Box + task.get_box_by_name + task.calculate_color_percentage
        —— 最后那个就是 is_forte_full 在用的那个函数。没有自己写的图像代码,
        分享到工坊之后别人看得懂、也能跟着框架升级(理由见 RING_R 上面那段)。

        【圆心和半径都从 box_liberation 推】: 那个框是框架按分辨率换算出来的,
        所以这段代码换分辨率不用重标。
        """
        box = self.task.get_box_by_name('box_liberation')
        if box is None or box.width <= 0:
            return 0.0
        cx = box.x + box.width / 2.0
        cy = box.y + box.height / 2.0
        r = box.width * self.RING_R
        half = max(2.0, box.width * self.RING_BOX)
        hits = 0
        for i in range(self.RING_SAMPLES):
            th = 2 * math.pi * i / self.RING_SAMPLES - math.pi / 2   # 从正上方起算
            bx = int(round(cx + r * math.sin(th) - half))
            by = int(round(cy - r * math.cos(th) - half))
            cell = Box(bx, by, int(round(2 * half)), int(round(2 * half)),
                       name='lib_ring')
            try:
                if self.task.calculate_color_percentage(self.RING_COLOR, cell) >= self.RING_FILL:
                    hits += 1
            except Exception:
                pass
        return hits / float(self.RING_SAMPLES)

    def lib_energy(self, char):
        """大招能量条的读数(0~1)。【读占比, 不用 liberation_available()】——
        理由见 CAN_LIB_READY_PCT 那一段: 那个布尔在坎身上恒为 True。
        """
        return float(char.current_liberation())

    def wait_lib_energy(self, char, level, cap, tag='能量', poke=True,
                        interval=None, read_every=0.10, confirm=2):
        """边打边等【大招能量到 level】, 到了立刻返回。

        跟 wait_lib_ready 的区别: 那个用的是框架的 liberation_available()(布尔),
        对某些角色恒为 True; 这个读的是能量条的【占比】, 分得出"还差多少"。
        【打不满也往下走】: 上限到了就返回 False, 调用方自己决定要不要照样按 R。
        """
        interval = self.A_INTERVAL if interval is None else interval
        start = time.time()
        n = reads = streak = 0
        pct = 0.0
        best = 0.0
        ok = False
        next_click = start
        next_read = start
        while time.time() - start < cap:
            now = time.time()
            if poke and now >= next_click:
                self.click()
                n += 1
                next_click += interval
                if next_click < now:
                    next_click = now + interval
            now = time.time()
            if now >= next_read:
                next_read = now + read_every
                reads += 1
                self.task.next_frame()
                try:
                    pct = self.lib_energy(char)
                except Exception:
                    pct = 0.0
                best = max(best, pct)
                streak = streak + 1 if pct >= level else 0
                if streak >= confirm:
                    ok = True
                    break
            nap = min(next_click if poke else next_read, next_read) - time.time()
            if nap > 0:
                self.macro_wait(min(nap, 0.02))
        self.macro_mark(f'{tag}({"满" if ok else "不够"}{best:.2f},A x{n},读x{reads},'
                        f'{time.time() - start:.2f}s)')
        return ok

    def f_break_then_hold(self, tag='处决', wait_break=None, f_interval=None,
                          anim_cap=None, settle=None, tail=None, blind_hold=None,
                          keep_held=False, probe=None):
        """连发处决键; 【处决演出一开始才按住左键(预输入重击)】; 演完松手。

        (用户 2026-08-31: "处决后没变身, 应该在处决的时候开始预输入重击, 你好像搞反了")

        【为什么不能从大招演出就一直按住】—— 我上一版就是这么写的, 反了:
        那样重击会在【大招演完那一刻】就出手, 8 秒强化状态从那时候开始烧;
        紧接着的处决演出(带全局时停, 最长好几秒)把它吃掉一大截 ——
        处决完人已经不是强化状态了, 表现出来就是"处决后没变身"。
        按住必须压在【处决演出】上, 让那一下重击落在处决【之后】,
        8 秒才从那一刻开始算。

        两段:
          1. 连发 F + 连点普攻, 等处决演出开始(队伍 HUD 掉下去)。
             【演出里的按键被丢掉】, 所以要连发不能单发。
          2. HUD 一掉就 mouse_down 按住, 一直按到演出结束(HUD 连续回来 settle 秒),
             再多按 tail 秒松手 —— 重击就在这一刻出手。

        【等不到处决也要按住】(blind_hold): 谐度不是每圈都破得掉, 但那 8 秒强化状态
        是这一整段伤害的来源, 不能因为没处决就不要了。

        Returns: 处决有没有触发。
        """
        wait_break = self.CAN_F_WAIT if wait_break is None else wait_break
        f_interval = self.CAN_F_INTERVAL if f_interval is None else f_interval
        anim_cap = self.F_ANIM_TIME_OUT if anim_cap is None else anim_cap
        settle = self.CAN_ANIM_SETTLE if settle is None else settle
        tail = self.CAN_HEAVY_TAIL if tail is None else tail
        blind_hold = self.CAN_FALLBACK_HOLD if blind_hold is None else blind_hold
        probe = self.CAN_F_PROBE if probe is None else probe
        # ---- 1 连发 F, 等处决演出开始 ----
        start = time.time()
        nf = n = 0
        broke = False
        seen_f = not self.USE_F_BREAK   # 关掉处决时不探, 直接走"没提示"那条路
        no_f = False
        next_f = next_click = next_probe = start
        while time.time() - start < wait_break:
            now = time.time()
            if self.USE_F_BREAK and now >= next_f:
                self.task.send_key('f', after_sleep=0)
                nf += 1
                next_f += f_interval
                if next_f < now:
                    next_f = now + f_interval
            now = time.time()
            if now >= next_click:
                self.click()
                n += 1
                next_click += self.A_INTERVAL
                if next_click < now:
                    next_click = now + self.A_INTERVAL
            self.task.next_frame()
            if not self.task.in_team()[0]:
                broke = True
                break
            # ---- 没有处决提示就别把窗口等满 ----: 见 CAN_F_PROBE
            now = time.time()
            if not seen_f and now >= next_probe:
                next_probe = now + self.CAN_F_PROBE_INTERVAL
                try:
                    if self.task.find_one('f_break_full', threshold=self.CAN_F_TPL):
                        seen_f = True
                except Exception:
                    # 【读不到就当没看见】: 这个方向是安全的 —— 顶多退回原来那套
                    # "等满窗口", 不会误判成"有处决"而把重击往后拖
                    pass
            if not seen_f and time.time() - start >= probe:
                no_f = True
                break
            self.macro_wait(0.01)
        self.macro_mark(f'{tag}({"触发" if broke else ("无提示" if no_f else "无")},'
                        f'F x{nf},A x{n},{time.time() - start:.2f}s)')
        # ---- 2 按住左键: 预输入重击 ----
        self.task.mouse_down()
        self.holding_attack = True
        hold_start = time.time()
        back_since = None
        back = False
        try:
            if broke:
                while time.time() - hold_start < anim_cap:
                    self.task.next_frame()
                    if not self.task.in_team()[0]:
                        back_since = None
                    elif back_since is None:
                        back_since = time.time()
                    elif time.time() - back_since >= settle:
                        back = True
                        break
                    self.macro_wait(0.01)
                # 处决演出计入 freeze, 否则框架会把它算成"这个角色磨蹭了几秒"
                self.add_freeze_duration(hold_start, time.time() - hold_start)
            else:
                self.macro_wait(blind_hold)
            if tail > 0:
                self.macro_wait(tail)
        finally:
            # 【keep_held: 不松手, 交给调用方接着按】(用户 2026-09-01: "把从F开始
            # 预输入的重击一直持续到切人位置, 保持一致长按攻击键的状态")。
            # 【只有异常路径才在这里松】—— 正常路径松手的责任在调用方,
            # 而 perform_loop 的 finally 里还有一道 release_attack 兜底
            if not keep_held:
                self.release_attack()
        self.macro_mark(f'{tag}按住({"ok" if (back or not broke) else "timeout"},'
                        f'{time.time() - hold_start:.2f}s{",不松手" if keep_held else ""})')
        return broke

    def phro_ea_lit(self):
        """强化普攻亮着没有 —— 就是那圈粉环。

        【名字澄清】: 我一直管它叫"强化E 的环", 用户口径是【强化普攻】。
        读的自始至终是同一格(box_resonance 外扩 + 粉色占比), 实机标定
        亮 0.06~0.20 / 暗 0.000, 门槛 CAN_EE_RING_FILL=0.015。
        """
        try:
            return self.ee_ring_pct(self) >= self.CAN_EE_RING_FILL
        except Exception:
            return False

    def phro_gate_ok(self, opener, con_level=None):
        """这一段该收尾了没有: 音符收集满(启动轴还要协奏够)。

        返回 (够没够, 说明用的字符串)。
        【音符满 = 回路条右边那个鼠标指示亮】—— 用户 2026-09-01 给的口径,
        判据见 PHRO_FORTE_BOX 那一段(颜色在前, 框架模板兜底)。
        【还要左键亮黄】: 循环轴见 L_PHRO_FORTE_NEED_YELLOW, 启动轴见 O_PHRO_FORTE_NEED_YELLOW。
        说明字符串带上开闸那一刻的白/黄读数, 下次对得出是真亮还是误报。
        """
        need_yellow = (self.O_PHRO_FORTE_NEED_YELLOW if opener
                       else self.L_PHRO_FORTE_NEED_YELLOW)
        full, by = self.phro_forte_full(self, need_yellow=need_yellow)
        if not full:
            return False, ''
        wy = getattr(self, '_forte_last', None)
        tail = f',白{wy[0]:.2f}黄{wy[1]:.3f}' if (wy and by == '色') else ''
        # 【启动轴不看协奏】: 见 O_PHRO_GATE_NEED_CON
        if not opener or not self.O_PHRO_GATE_NEED_CON:
            return True, by + '亮' + tail
        try:
            con = float(self.get_current_con())
        except Exception:
            con = 0.0
        need = (self.PHRO_CON_BEFORE_HEAVY if con_level is None else con_level)
        if con >= need:
            return True, f'{by}亮,协奏{con:.2f}/{need:.2f}{tail}'
        return False, ''

    def phro_wait_ea(self, want_lit, cap, tag, poke=True, min_wait=0.0,
                     dodge_at=0.0, gate=None, prehold=False,
                     dodge_on_hit=False, dodge_delay=0.0):
        """连点普攻, 等强化普攻【亮起】或者【灭掉】。

        want_lit=True  -> 等它亮(那串 AAAAA 就是在这里打的)
        want_lit=False -> 等它灭(循环轴第一轮: 靠连点把已经挂着的那个打出去)

        【连点和读屏各走各的时刻表】: 挂在一起会把 A 挤慢, 这条轴上栽过一次。
        【要连着读到才认】: 单帧会闪, 而且粉色特效满天飞
        """
        interval = self.PHRO_A_INTERVAL
        start = time.time()
        next_click = start
        next_read = start
        hits = 0
        n = 0
        which = 0
        gated = ''
        got = False
        dodged = False
        while time.time() - start < cap:
            # ---- 定点闪避 ----: 见 L_PHRO_EA_DODGE_AT。
            # 【放在点击前面】: dodge 是 after_sleep=0 立刻返回的, 紧接着那一下
            # 点击就是"用A把闪避接回去"的那一下
            if dodge_at and not dodged and time.time() - start >= dodge_at:
                dodged = True
                self.dodge(tag='弗闪避')
            now = time.time()
            if poke and now >= next_click:
                self.click()
                n += 1
                next_click += interval
                if next_click < now:
                    next_click = now + interval
            now = time.time()
            if now >= next_read:
                next_read = now + self.PHRO_EA_READ_INTERVAL
                self.task.next_frame()
                # 【两个判据轮流读, 不是每轮都读两个】(用户 2026-09-01:
                # "协奏到45应该马上开始重击" / "音符满了还多A了几下")。
                # 【原来闸门只在每一轮开头查一次】—— 一轮里最多 4 秒不看,
                # 满了也得等这一轮走完。现在挂进等待循环里, 一满就走。
                # 【轮流读是为了不把连点挤慢】: 模板匹配和协奏环都不便宜,
                # 挂在一起会让 A 变稀 —— 这条轴上栽过一次
                which += 1
                if gate is not None and which % 2 == 0:
                    ok, why = gate()
                    if ok:
                        gated = why or 'ok'
                        if prehold and not self.holding_attack:
                            # 【就在读到的这一帧按下去】: 见 PHRO_PREHOLD
                            self.task.mouse_down()
                            self.holding_attack = True
                            self.prehold_at = time.time()
                            self.macro_mark('弗预输入重击')
                        break
                else:
                    hits = hits + 1 if self.phro_ea_lit() == want_lit else 0
                    # 【min_wait 之前一律不认】: 起手总要先打几下,
                    # 不然一进场就闪避。【闸门那一条不受 min_wait 管】——
                    # 满了就是该走了, 跟打了多久没关系
                    if hits >= self.PHRO_EA_CONFIRM and now - start >= min_wait:
                        got = True
                        if dodge_on_hit and not dodged:
                            # 【就在读到的这一帧闪避】: 见 L_PHRO_EA_DODGE_ON_DARK。
                            # 【不能等返回再闪】—— 返回要先记 mark、再回到 cycle,
                            # 中间那几十毫秒后摇就白留了
                            dodged = True
                            if dodge_delay > 0:
                                # 见 L_PHRO_EA_DARK_TO_DODGE; 这段连点着过
                                self.macro_gap(dodge_delay, tag='弗A')
                            self.dodge(tag='弗闪避')
                        break
            nap = min(next_click if poke else next_read, next_read) - time.time()
            if nap > 0:
                self.macro_wait(min(nap, 0.02))
        if (dodge_at or dodge_on_hit) and not dodged:
            # 【一发都没闪成】: 定点那条是 这一轮比 dodge_at 还短;
            # 事件锚定那条是 判据压根没成立(cap 了)
            self.macro_mark(f'弗闪避跳过({time.time() - start:.2f}s)')
        how = '闸门' if gated else ('到' if got else 'cap')
        self.macro_mark(f'{tag}({how},A x{n},{time.time() - start:.2f}s)')
        if gated:
            return 'gate'
        return 'got' if got else ''

    def phro_gate_step(self, gate, prehold, tag):
        """循环轴两步之间读一次闸门; 成立就当场按住(prehold)并返回 True, 调用方 break 收尾。

        见 L_PHRO_GATE_IN_STEPS。按住的写法跟 phro_wait_ea 里那份一样(见 PHRO_PREHOLD)。
        """
        self.task.next_frame()
        ok, _ = gate()
        if not ok:
            return False
        if prehold and not self.holding_attack:
            self.task.mouse_down()
            self.holding_attack = True
            self.prehold_at = time.time()
            self.macro_mark('弗预输入重击')
        self.macro_mark(f'弗闸门在{tag}')
        return True

    def phro_delay_gate(self, delay, gate, prehold):
        """PHRO_EA_DELAY 那段等待(不点 A), 循环轴边等边查闸门。成立返回 True。

        【剩不到一次读屏的时间就干等】: 一次读屏 30~40ms, 读完再闪避会把用户标的 0.1 秒拖长
        """
        start = time.time()
        while True:
            if self.phro_gate_step(gate, prehold, '亮后'):
                return True
            left = delay - (time.time() - start)
            if left <= 0:
                break
            if left < 0.04:
                self.macro_wait(left)
                break
            self.macro_wait(0.01)
        self.macro_mark(f'弗强化普攻等({time.time() - start:.2f}s)')
        return False

    def phro_ea_entry_lit_confirmed(self):
        """循环轴进场读到环亮之后再连读几帧, 都亮才算。见 L_PHRO_EA_ENTRY_CONFIRM。"""
        if not self.L_PHRO_EA_ENTRY_CONFIRM:
            return True
        for _ in range(self.PHRO_EA_CONFIRM - 1):
            self.task.next_frame()
            if not self.phro_ea_lit():
                self.macro_mark('弗进场环(单帧,不算)')
                return False
        return True

    def phro_note_count(self):
        """回路条上从左数连着几个音符, 以及这一帧干不干净。框和阈值见 PHRO_NOTE_* 那组。

        干净 = 有音符的格没有被染成一片(不过 PHRO_NOTE_FLASH), 后面的空槽全空(不过 PHRO_NOTE_OFF)。
        """
        y1, y2 = self.PHRO_NOTE_Y
        vals = []
        for i in range(6):
            cx = self.PHRO_NOTE_X0 + self.PHRO_NOTE_DX * i
            box = self.task.box_of_screen_scaled(
                3840, 2160, int(round(cx - self.PHRO_NOTE_HALF_W)), y1,
                int(round(cx + self.PHRO_NOTE_HALF_W)), y2,
                name=f'phro_note{i}', hcenter=True)
            vals.append(float(self.task.calculate_color_percentage(self.PHRO_NOTE_RED, box))
                        + float(self.task.calculate_color_percentage(self.PHRO_NOTE_BLUE, box)))
        n = 0
        while n < 6 and vals[n] >= self.PHRO_NOTE_ON:
            n += 1
        clean = (all(v <= self.PHRO_NOTE_OFF for v in vals[n:])
                 and max(vals[:n] or [0.0]) <= self.PHRO_NOTE_FLASH)
        return n, clean

    def phro_note0_score(self):
        """第 0 格像不像彩乐音符: 返回 -1~1(灰度小图去均值归一后跟模板点积); 拿不到画面返回 -1。

        见 PHRO_NOTE0_TPL_B64 上面那段。框跟 phro_note_count 的第 0 格是同一个。
        """
        try:
            import base64
            import cv2
            import numpy as np
            tpl = getattr(self, '_phro_note0_tpl', None)
            if tpl is None:
                tpl = np.frombuffer(base64.b64decode(self.PHRO_NOTE0_TPL_B64),
                                    dtype=np.uint8).astype(np.float32)
                tpl = tpl - tpl.mean()
                tpl = tpl / np.linalg.norm(tpl)
                self._phro_note0_tpl = tpl
            y1, y2 = self.PHRO_NOTE_Y
            box = self.task.box_of_screen_scaled(
                3840, 2160, int(round(self.PHRO_NOTE_X0 - self.PHRO_NOTE_HALF_W)), y1,
                int(round(self.PHRO_NOTE_X0 + self.PHRO_NOTE_HALF_W)), y2,
                name='phro_note0', hcenter=True)
            crop = self.task.frame[box.y:box.y + box.height, box.x:box.x + box.width]
            g = cv2.cvtColor(crop, cv2.COLOR_BGR2GRAY).astype(np.float32)
            g = cv2.resize(g, (self.PHRO_NOTE0_TPL_W, self.PHRO_NOTE0_TPL_H),
                           interpolation=cv2.INTER_AREA).ravel()
            g = g - g.mean()
            n = float(np.linalg.norm(g))
            if n < 1e-6:
                return 0.0
            return float(g @ tpl) / n
        except Exception:
            return -1.0

    def phro_wait_a3_note(self, cap):
        """循环轴第一轮: 读到环亮(A3 出手)之后【不点 A】, 等 A3 打出来的第一个音符。

        见 L_PHRO_EA_A3_NOTE。返回到没到; 没到就到点返回, 调用方照旧 闪避 -> 接A。
        【只认"正好 1 个"】: 这一轮从 0 开始, 不点 A 就只有 A3 一个来源;
        整条被染红时左边几格会一起读成有, 那种帧不算
        """
        start = time.time()
        hits = 0
        reads = 0
        best = -1.0
        # 【变奏入场的才比形状】: 第一个音符是彩乐; 没变奏进来的是红色弦乐, 退回颜色读法
        by_shape = bool(getattr(self, 'has_intro', True))
        while time.time() - start < cap:
            self.task.next_frame()
            reads += 1
            if by_shape:
                v = self.phro_note0_score()
                best = max(best, v)
                ok = v >= self.PHRO_NOTE0_MIN
            else:
                try:
                    n, clean = self.phro_note_count()
                except Exception:
                    n, clean = 0, False
                ok = clean and n == 1
            hits = hits + 1 if ok else 0
            if hits >= self.L_PHRO_EA_A3_NOTE_CONFIRM:
                self.macro_mark(f'弗等A3音符(到,{"形" if by_shape else "色"},'
                                f'{time.time() - start:.2f}s)')
                return True
            self.macro_wait(0.01)
        tail = f',最高{best:.2f}' if by_shape else ''
        self.macro_mark(f'弗等A3音符(cap,{reads}帧{tail},{time.time() - start:.2f}s)')
        return False

    def phro_ea_e_body(self, gate, prehold, fast=False):
        """第一轮: 连点 A 用掉环(强化A) -> 普通E -> 等环重新亮 -> 连点 A 用掉环(第二个强化A)。

        返回 'gate'(闸门在中途成立了, 调用方收尾) / ''。理由见 PHRO_EA_E_BODY 上面那段。
        【每一步都看环, 读不到就退回原来那一步】: 环一直不灭就照样按 E(多半出强化E, 跟原来一样),
        普通E 没确认出手就不打第二个强化A —— 少打一下, 不打错一下。
        fast(循环轴, 见 L_PHRO_EA_TAIL_AFTER_DARK): 只读环不查闸门, 并且停在"环重新亮"——
        第二个强化A 交给 phro_ea_tail(连点到环灭 -> 当场 Q / 闪避)
        """
        if fast:
            gate = None
        lit = self.phro_ea_lit()
        if not lit and self.PHRO_EA_E_RING_LOOK > 0:
            # 【没读到环先别按 E】: 见 PHRO_EA_E_RING_LOOK
            lit = self.phro_wait_ea(True, self.PHRO_EA_E_RING_LOOK, tag='弗E前看环', poke=False,
                                    gate=gate, prehold=prehold)
            if lit == 'gate':
                return 'gate'
        if lit:
            r = self.phro_wait_ea(False, self.PHRO_EA_E_PREP_CAP, tag='弗A用掉环',
                                  gate=gate, prehold=prehold)
            if r == 'gate':
                return 'gate'
        fired = self.press_e_until_fired(self, cap=self.PHRO_EA_E_CAP, tag='弗E')
        if not fired:
            return ''
        if not self.phro_ea_lit():
            # 【不点 A 等它亮】: 一边点一边等, 环可能刚亮就被点掉了, 读屏还没看见
            r = self.phro_wait_ea(True, self.PHRO_EA_E_LIT_CAP, tag='弗E后等环',
                                  poke=False, gate=gate, prehold=prehold)
            if r == 'gate':
                return 'gate'
            if not r:
                return ''
        if fast:
            return ''
        r = self.phro_wait_ea(False, self.PHRO_EA_E_A2_CAP, tag='弗E接强化A',
                              gate=gate, prehold=prehold)
        return 'gate' if r == 'gate' else ''

    def phro_ea_tail(self, gate, prehold, steps_gate, tag):
        """一轮的收尾(循环轴): 连点 A 到环灭(这一轮的强化A 出手了) -> 当场 Q / Q 在冷却就当场闪避。

        见 L_PHRO_EA_TAIL_AFTER_DARK。返回 'gate'(Q 之前闸门成立了, 已经按住) / ''。
        【Q 冷却提前读】: 读 OCR 要几十毫秒, 放在环灭那一刻读就把 Q 推晚了;
        冷却卡在边上(差不到 0.3 秒)才在那一刻重读一次 —— 估错了 fire_echo 会白空转 1.2 秒
        """
        qcd = self.cd_baseline('echo', probes=2)
        t_q = time.time()
        self.phro_wait_ea(False, self.L_PHRO_EA_TAIL_DARK_CAP, tag=tag)
        if steps_gate and self.phro_gate_step(gate, prehold, 'Q前'):
            return 'gate'
        left = qcd - (time.time() - t_q) if qcd > 0 else 0.0
        if qcd > 0 and -0.3 < left <= 0.3:
            left = self.cd_baseline('echo', probes=1)
        if left <= 0:
            self.fire_echo_until_fired(self, cap=self.PHRO_Q_CAP, tag='Q弗声骸')
            return ''
        self.macro_mark(f'弗QCD改闪避({left:.1f}s)')
        self.dodge(tag='弗闪避Q')
        return ''

    def phro_ea_cycle(self, opener, prehold=False):
        """强化普攻循环 —— 这一段的主体。流程见 PHRO_EA_DELAY 上面那段。

        【为什么把闪避放在"亮起 + 0.3 秒"】(用户 2026-09-01): 闪避取消的是
        强化普攻亮起前那一下的后摇; 太早发落在动画里会被整发丢掉。
        【Q 在 CD 就用闪避顶上】: 那一步要的是"取消后摇", 声骸只是顺手;
        CD 上按 Q 是空操作, 会让这一下后摇白留着。
        """
        start = time.time()
        rounds = 0
        first = True

        self.prehold_at = None
        self._gate_white_only_logged = False   # 见 phro_gate_white_only: 每段只记一笔
        self._forte_last = None
        # 【协奏那条线会降一档】: 见 PHRO_CON_FALLBACK。指示那条不降
        con_need = self.PHRO_CON_BEFORE_HEAVY
        budget = self.PHRO_EA_TOTAL
        downgraded = False

        def gate():
            return self.phro_gate_ok(opener, con_need)
        # 见 L_PHRO_GATE_IN_STEPS; 启动轴不动
        steps_gate = (not opener) and self.L_PHRO_GATE_IN_STEPS

        why = ''
        while rounds < self.PHRO_EA_ROUNDS:
            ok, why = self.phro_gate_ok(opener)
            if ok:
                break
            if time.time() - start >= budget:
                if opener and not downgraded:
                    # 【0 链保底: 协奏线降到 35, 再给一段时间】
                    downgraded = True
                    con_need = self.PHRO_CON_FALLBACK
                    budget += self.PHRO_EA_FALLBACK_CAP
                    self.macro_mark(f'弗协奏降档({con_need:.2f})')
                    self.logger.info(
                        f'phrolova: {self.PHRO_EA_TOTAL:.0f} 秒没等到协奏 '
                        f'{self.PHRO_CON_BEFORE_HEAVY:.2f}, 按 0 链保底降到 '
                        f'{self.PHRO_CON_FALLBACK:.2f} 再等 '
                        f'{self.PHRO_EA_FALLBACK_CAP:.0f} 秒')
                    continue
                self.logger.warning(
                    f'phrolova: 强化普攻循环跑满 {budget:.0f} 秒还没攒够 '
                    f'({rounds} 轮), 照样往下走 —— 往上游查: 那圈粉环读得到吗'
                    f'(看 弗等强化普攻 那几行), 音符判据读得到吗(看下面 弗闸门 那一行)')
                break
            rounds += 1
            if (first and not opener and self.phro_ea_lit()
                    and self.phro_ea_entry_lit_confirmed()):
                # 【循环轴第一轮: 进场就挂着一个, 先把它打出去】
                # 【环一灭就闪避】: 见 L_PHRO_EA_DODGE_ON_DARK。
                # dodge_at 留着当另一条路(设成 >0 就变回定点)
                if self.phro_wait_ea(False, self.PHRO_EA_DARK_CAP,
                                     tag='弗打掉入场强化普攻',
                                     dodge_at=self.L_PHRO_EA_DODGE_AT,
                                     dodge_on_hit=self.L_PHRO_EA_DODGE_ON_DARK,
                                     dodge_delay=self.L_PHRO_EA_DARK_TO_DODGE,
                                     gate=gate, prehold=prehold) == 'gate':
                    break
            else:
                # 【只有第一轮压下界】: 后面几轮是紧接着 AAAAA 来的, 早就打过了
                floor = 0.0
                if first:
                    floor = (self.O_PHRO_EA_MIN_A if opener
                             else self.L_PHRO_EA_MIN_A)
                # 【上一轮的 AAAAA 折进这里当下界】: 原来是一段 macro_spam,
                # 那 1.2 秒里不看闸门 —— 正是"音符满了还多A几下"的来源
                if not first:
                    floor = max(floor, self.PHRO_EA_TAIL)
                r = self.phro_wait_ea(True, self.PHRO_EA_LIT_CAP,
                                      tag=f'弗等强化普攻{rounds}',
                                      min_wait=floor, gate=gate,
                                      prehold=prehold)
                if r == 'gate':
                    break
                if not r:
                    # 【等不到就别硬转】: 多半是音符已经满了(判据在循环顶上会拦),
                    # 或者这一格读不到 —— 两种都该出去交给下面的兜底
                    break
                if first and not opener and self.L_PHRO_EA_A3_NOTE:
                    # 【循环轴第一轮: A3 的音符到了再闪避】: 见 L_PHRO_EA_A3_NOTE
                    self.phro_wait_a3_note(self.L_PHRO_EA_A3_NOTE_CAP)
                elif steps_gate:
                    # 【这 0.1 秒边等边查闸门】: 见 L_PHRO_GATE_IN_STEPS
                    if self.phro_delay_gate(self.PHRO_EA_DELAY, gate, prehold):
                        break
                # 【0 就整个跳过】: poll_wait(0) 虽然也是立刻返回, 但会白记一条 mark
                elif self.PHRO_EA_DELAY > 0:
                    self.poll_wait(self.PHRO_EA_DELAY, tag='弗强化普攻等')
                self.dodge(tag='弗闪避')
                # 【马上接A】: 闪避那 21 帧是硬的(帧表: 通用闪避没有派生帧),
                # 早点的几下会被吃掉, 但结束帧一到就有一下落地
                self.macro_spam(self.PHRO_EA_A_AFTER, self.PHRO_A_INTERVAL,
                                tag='弗接A')
                if steps_gate and self.phro_gate_step(gate, prehold, '接A后'):
                    break
            # ---- 只有第一轮按 E ----
            # (用户 2026-09-01: "除了循环轴第一次需要E之外, 后面不需要E")
            # 【后面几轮的形状是 闪避 -> 接A -> 闪避 -> AAAA】: E 挤在中间只会
            # 把两发闪避之间的 A 顶掉 —— 而那几下 A 才是这一段攒音符的来源。
            # 【E 本来就一轮一发】: 她的 E 有 CD, 后面几轮按了也是空操作,
            # 却实打实占着 press_e_until_fired 那个窗口
            # 见 L_PHRO_EA_TAIL_AFTER_DARK; 启动轴不动
            tail_fast = (not opener) and self.L_PHRO_EA_TAIL_AFTER_DARK
            if first:
                if self.PHRO_EA_E_BODY:
                    # 【先把环用掉再按 E】: 见 PHRO_EA_E_BODY。闸门在这几步里照样边打边查
                    if self.phro_ea_e_body(gate, prehold, fast=tail_fast) == 'gate':
                        break
                else:
                    self.press_e_until_fired(self, cap=self.PHRO_EA_E_CAP, tag='弗E')
            was_first = first
            first = False
            if tail_fast:
                # 【连点到强化A 出手 -> 当场 Q / 闪避】: 见 L_PHRO_EA_TAIL_AFTER_DARK
                if self.phro_ea_tail(gate, prehold, steps_gate,
                                     tag='弗E接强化A' if was_first else '弗A到环灭') == 'gate':
                    break
                continue
            if steps_gate and self.phro_gate_step(gate, prehold, 'Q前'):
                break
            # ---- Q; 在 CD 就用闪避代替 ----
            if self.cd_baseline('echo', probes=2) > 0:
                self.macro_mark('弗QCD改闪避')
                if self.PHRO_EA_Q_DODGE_DELAY > 0:
                    # 【给前面那一下 A 留出落地的时间】: 见 PHRO_EA_Q_DODGE_DELAY
                    self.macro_gap(self.PHRO_EA_Q_DODGE_DELAY, tag='弗A')
                self.dodge(tag='弗闪避Q')
            else:
                self.fire_echo_until_fired(self, cap=self.PHRO_Q_CAP, tag='Q弗声骸')
            # ---- AAAAA ----: 下一轮的"等亮起"接着连点, 这里只压一个下界
            # 【尾巴那段 AAAAA 不再单独打】: 折进下一轮 phro_wait_ea 的 min_wait,
            # 那里边打边查闸门
        ok, why2 = self.phro_gate_ok(opener, con_need)
        self.macro_mark(f'弗闸门({why2 or why or "没满"},{rounds}轮,'
                        f'{time.time() - start:.2f}s)')
        return rounds

    def phro_press_ee(self, delay):
        """反复"等粉环亮 -> 等 delay -> 按到环灭", 直到没环了或者预算用完。

        【为什么是循环不是一发】: 见 PHRO_EE_ROUNDS 上面那段 —— 她这一段有好几发
        强化E, 只处理第一发的话后面几发就成了盲按。
        【按到环灭才算这一发出去了】: 判据是"亮过又不亮了"的跳变, 不是"暗着" ——
        暗着可能只是还没轮到。这条轴上这个坑栽过五次。
        """
        end = time.time() + self.PHRO_EE_TOTAL
        done = 0
        for r in range(1, self.PHRO_EE_ROUNDS + 1):
            left = end - time.time()
            if left <= 0:
                break
            cap = self.PHRO_EE_WAIT if r == 1 else self.PHRO_EE_NEXT_WAIT
            tag = '弗等强化E' if r == 1 else f'弗等强化E{r}'
            lit = self.wait_ee_ring(self, cap=min(cap, left), tag=tag)
            if not lit:
                break
            if delay > 0:
                # 【lit 和 already 都等】: 理由见 PHRO_EE_ROUNDS 上面那段
                self.poll_wait(delay, tag=f'弗强化E延迟({delay:.2f}s)')
            ee = {'n': 0, 'lit': True}

            def ee_gone():
                self.task.next_frame()
                try:
                    v = self.ee_ring_pct(self)
                except Exception:
                    v = 0.0
                if v >= self.CAN_EE_RING_FILL:
                    ee['n'] = 0
                    return False
                ee['n'] += 1
                return ee['n'] >= self.PHRO_EE_GONE

            self.spam_key(self.send_resonance_key, self.PHRO_E2_WINDOW,
                          interval=self.PHRO_E2_INTERVAL,
                          tag='弗强化E' if r == 1 else f'弗强化E{r}',
                          poke=False, stop_when=ee_gone)
            if ee['n'] < self.PHRO_EE_GONE:
                self.macro_mark(f'弗强化E{r}判(亮着没按掉)')
                break
            done += 1
        self.macro_mark(f'弗强化E共{done}发')
        return done

    def phro_forte_pct(self):
        """回路条右边那个鼠标指示的纯白占比。全用原版 OK 的 API。"""
        box = self.task.box_of_screen_scaled(
            3840, 2160, *self.PHRO_FORTE_BOX, name='phro_forte', hcenter=True)
        return float(self.task.calculate_color_percentage(
            self.PHRO_FORTE_WHITE, box))

    def phro_forte_yellow_pct(self):
        """同一个框里左键那块亮黄的占比(真亮起 0.058 / 暗 0.000)。"""
        box = self.task.box_of_screen_scaled(
            3840, 2160, *self.PHRO_FORTE_BOX, name='phro_forte', hcenter=True)
        return float(self.task.calculate_color_percentage(
            self.PHRO_FORTE_YELLOW, box))

    def phro_gate_white_only(self, white, yellow):
        """循环轴闸门读到"白亮、黄不亮": 每段记一笔; 开着排查截图就存一张全屏。"""
        self._gate_white_only_n = getattr(self, '_gate_white_only_n', 0) + 1
        if getattr(self, '_gate_white_only_logged', False):
            return
        self._gate_white_only_logged = True
        self.macro_mark(f'弗闸门白无黄(白{white:.2f},黄{yellow:.3f})')
        if not self.PHRO_SHOT_GATE:
            return
        shots = getattr(self.task, '_fck_gate_shots', 0)
        if shots >= self.PHRO_SHOT_GATE_MAX:
            return
        self.task._fck_gate_shots = shots + 1
        try:
            self.task.screenshot(f'fck_gate_L_白{white:.2f}_黄{yellow:.3f}')
        except Exception as e:
            self.logger.info(f'闸门排查截图没存上: {e}')

    def phro_forte_full(self, char, need_yellow=False):
        """回路满了没有 —— 【颜色判据在前, 框架模板兜底】。

        返回 (满没满, 是谁判出来的)。白亮的时候顺手读一次黄, 读数记在 self._forte_last 给日志用。
        need_yellow(循环轴闸门): 白亮还要左键那块亮黄, 理由见 L_PHRO_FORTE_NEED_YELLOW 上面那段。
        【为什么颜色和模板一起用】: 颜色那条是实机标出来的(亮 0.23 / 暗 0.00),
        模板那条【已知会漏】但不会误报 —— 或起来只会补上漏的, 不会多判。
        【误报的代价很大】: 提示没亮就长按, 出来的是普通重击, 既没有那 40 点协奏
        也拿不到定音状态(大招不解锁), 整圈全塌。所以宁可用 0.08 这种保守门槛"""
        try:
            white = self.phro_forte_pct()
            if white >= self.PHRO_FORTE_FILL:
                try:
                    yellow = self.phro_forte_yellow_pct()
                except Exception:
                    yellow = -1.0
                self._forte_last = (white, yellow)
                if not need_yellow or yellow >= self.PHRO_FORTE_YELLOW_FILL:
                    return True, '色'
                self.phro_gate_white_only(white, yellow)
        except Exception:
            pass
        try:
            if char.is_mouse_forte_full():
                return True, '模板'
        except Exception:
            pass
        return False, ''

    def wait_ee_ring(self, char, cap, tag='等强化E', confirm=None, interval=None):
        """等强化E 的粉环亮起。【期间一下都不出手】——

        派生窗口开着的时候点普攻会出 A1 把窗口吃掉, 所以这里只刷新画面。
        返回: 亮没亮。顺手把读到的最高值写进 mark, 门槛不对时一眼看得出来。
        """
        confirm = self.CAN_EE_LIT if confirm is None else confirm
        interval = self.CAN_E2_RING_INTERVAL if interval is None else interval
        start = time.time()
        next_read = start
        hits = 0
        best = 0.0
        # 【进门就亮着的话, "亮起"这件事没有发生过】: 直接返回会让调用方以为
        # 刚等到一次亮起, 于是把后面那 0.3 秒挂在一个【早就过去的时刻】上 ——
        # 表现出来就是用户说的"明显按晚了"。这种情况如实返回 already
        try:
            self.task.next_frame()
            if self.ee_ring_pct(char) >= self.CAN_EE_RING_FILL:
                self.macro_mark(f'{tag}(进门就亮着)')
                return 'already'
        except Exception:
            pass
        while time.time() - start < cap:
            now = time.time()
            if now >= next_read:
                next_read = now + interval
                self.task.next_frame()
                try:
                    v = self.ee_ring_pct(char)
                except Exception:
                    v = 0.0
                if v > best:
                    best = v
                hits = hits + 1 if v >= self.CAN_EE_RING_FILL else 0
                if hits >= confirm:
                    self.macro_mark(f'{tag}(亮{v:.3f},{time.time() - start:.2f}s)')
                    return 'lit'
            self.macro_wait(0.02)
        self.macro_mark(f'{tag}(没亮,最高{best:.3f}/门槛'
                        f'{self.CAN_EE_RING_FILL:.3f},{cap:.2f}s)')
        return ''

    def shoot_burst(self, prefix, n=None, interval=None):
        """连拍几张存到 screenshots/ —— 拿来标定读屏判据。

        【用框架自带的 task.screenshot】(用户 2026-09-01: "OKWW自带截图"),
        文件名带序号和相对时刻, 事后一眼看得出哪张是第几帧。
        【期间不出手也不点击】: 这几张是拿来量颜色的, 手上有动作会把画面搅乱
        """
        n = self.PHRO_SHOT_N if n is None else n
        interval = self.PHRO_SHOT_INTERVAL if interval is None else interval
        t0 = time.time()
        for i in range(n):
            self.task.next_frame()
            try:
                self.task.screenshot(f'{prefix}_{i:02d}_{time.time() - t0:.2f}s')
            except Exception as e:
                self.logger.warning(f'shoot_burst: 截图失败 {e}')
                break
            self.macro_wait(interval)
        self.macro_mark(f'连拍{prefix}(x{n},{time.time() - t0:.2f}s)')

    def spam_ae(self, char, cap, stop, tag='AE连发', a_interval=None, e_interval=None,
                f_interval=None, read_every=0.10, min_wait=0.0):
        """【A 和 E 一起连发】, 各走各的节奏: 点普攻 / 发 E / (发 F) / 读屏。

        坎特蕾拉那一整段用的就是这个(用户 2026-08-31 给的口径, 见 CAN_AE_A_INTERVAL
        上面那段)。E 落在 CD 上是空操作、不花钱, 所以不用算"什么时候该按" ——
        强化E 一亮就会被下一次连发按掉。

        【三个节奏必须解耦】: 挂在一起的话点击会被 E 的间隔或者读屏的耗时卡住,
        表现出来就是"A一下停一下"(这条轴上栽过一次)。

        Args:
            stop: 每次读屏【之后】调一次, 返回 True 就停。它自己负责读它要的东西
                (画面已经由本函数 next_frame 刷好了)。
            f_interval: 顺带按处决键的间隔(None = 不按)。
                【处决是"随时"的, 不是排在某一格的】(用户 2026-08-31: "坎的F不必在
                这么后啊, R后随时处决就行")。谐度什么时候破由怪说了算, 排在固定位置
                要么早了(白按)要么晚了(错过窗口) —— 掺进连发里最省事,
                没得打的时候按 F 什么也不会发生。
                【所以这里【不】调 spam_f】: 那个是阻塞的 —— 一触发就要
                poke_until_hud_back 等整个演出。掺在连发里只需要把键递出去,
                演出来了下面的"HUD 不在就不判"自己会处理。

        【演出/时停期间不判 stop】: 处决(或者任何演出)一触发队伍 HUD 就掉下去,
        这时候读到的亮度、协奏全是假的 —— 直接跳过那几次读屏, 并且把这段时间
        【从 cap 里扣掉】, 免得一次处决把整格的预算吃光。
        """
        a_interval = self.A_INTERVAL if a_interval is None else a_interval
        e_interval = self.KEY_INTERVAL if e_interval is None else e_interval
        start = time.time()
        na = ne = nf = reads = 0
        anim = 0.0
        anim_from = None
        hit = False
        next_a = next_e = next_f = start
        next_read = start + max(0.0, min_wait)
        while time.time() - start - anim < cap:
            now = time.time()
            # 【a_interval 给 0 就完全不点】: 坎的收尾在"一路按住左键"那一档时要用 ——
            # 按住期间再插点击会把长按打断
            if a_interval and now >= next_a:
                self.click()
                na += 1
                next_a += a_interval
                if next_a < now:
                    next_a = now + a_interval
            now = time.time()
            # 【e_interval 给 0 就只连点、不发 E】: "等强化E 亮"那一格要用 ——
            # 一边盲发 E 一边等它亮是矛盾的, E 会把刚亮的那一帧当场按掉,
            # 读屏永远看不见(实机症状: 判据跑满上限, Q 晚了 8 秒)
            if e_interval and now >= next_e:
                char.send_resonance_key()
                ne += 1
                next_e += e_interval
                if next_e < now:
                    next_e = now + e_interval
            now = time.time()
            if f_interval and self.USE_F_BREAK and now >= next_f:
                self.task.send_key('f', after_sleep=0)
                nf += 1
                next_f += f_interval
                if next_f < now:
                    next_f = now + f_interval
            now = time.time()
            if now >= next_read:
                next_read = now + read_every
                reads += 1
                self.task.next_frame()
                if not self.task.in_team()[0]:
                    # 演出里: 判据不可信, 只记时间不判
                    if anim_from is None:
                        anim_from = now
                else:
                    if anim_from is not None:
                        anim += time.time() - anim_from
                        anim_from = None
                    try:
                        if stop():
                            hit = True
                            break
                    except Exception:
                        pass
            targets = [next_read]
            if a_interval:
                targets.append(next_a)
            if e_interval:
                targets.append(next_e)
            nap = min(targets) - time.time()
            if nap > 0:
                self.macro_wait(min(nap, 0.02))
        if anim_from is not None:
            anim += time.time() - anim_from
        if anim > 0:
            # 演出那一段计入 freeze, 否则框架会把它算成"这个角色磨蹭了几秒"
            self.add_freeze_duration(time.time() - anim, anim)
        self.macro_mark(f'{tag}({"ok" if hit else "cap"},A x{na},E x{ne}'
                        f'{f",F x{nf}" if nf else ""}'
                        f'{f",演出{anim:.1f}s" if anim > 0 else ""},'
                        f'读x{reads},{time.time() - start:.2f}s)')
        return hit

    def wait_e_cd_or_ring(self, char, cd_left):
        """等普通E 的 CD 转好, 但【粉环先亮就提前返回】。

        返回 'cd'(等到 CD 转好) / 'ring'(强化E 先亮了) / 'ready'(压根不用等)。

        【为什么两件事要合成一个等待】: 分两步写的话第二步会从头开始重新等 ——
        弗洛洛那边的 wait_heavy_ready 就是被这个坑逼出来的。
        【等的期间不出手】: 左键还按着, 强化A 自己在打; 这里只刷新画面
        """
        if cd_left <= 0:
            return 'ready'
        end = time.time() + cd_left
        next_read = time.time()
        hits = 0
        best = 0.0
        while time.time() < end:
            now = time.time()
            if now >= next_read:
                next_read = now + self.CAN_E2_RING_INTERVAL
                self.task.next_frame()
                try:
                    v = self.ee_ring_pct(char)
                except Exception:
                    v = 0.0
                if v > best:
                    best = v
                # 【连读才认】: 见 CAN_E2_RING_CONFIRM。中间断一次就清零 ——
                # 闪光是一两帧, 环是持续亮的, 清零把两者分得干干净净
                hits = hits + 1 if v >= self.CAN_EE_RING_FILL else 0
                if hits >= self.CAN_E2_RING_CONFIRM:
                    self.macro_mark(f'坎E让位强化E(环{v:.3f})')
                    return 'ring'
            self.macro_wait(0.02)
        self.macro_mark(f'坎等E转好({cd_left:.1f}s,环最高{best:.3f})')
        return 'cd'

    def ee_ring_pct(self, char=None):
        """强化E 那圈粉环的占比。判据框 = 框架的 box_resonance 外扩一圈。

        【全用原版 OK 的 API】(用户 2026-08-31: "我需要打包到工坊"):
        get_box_by_name / Box.scale / calculate_color_percentage 都是框架自带的,
        没有一行私有的 cv2。
        【框跟着框架走】: box_resonance 是框架按实际截图标注的图标框, 各种分辨率下
        它自己会算对; 我只在它中心上放大, 不去猜屏幕坐标
        """
        box = self.task.get_box_by_name('box_resonance').scale(
            self.CAN_EE_RING_W, self.CAN_EE_RING_H)
        return float(self.task.calculate_color_percentage(
            self.CAN_EE_RING_COLOR, box))

    def ee_ring_probe(self, char, confirm=1):
        """"强化E 亮了"的判据: 粉环出现。给 spam_ae 当 stop 用。"""
        st = self._ee_state

        def probe():
            self.task.next_frame()
            try:
                v = self.ee_ring_pct(char)
            except Exception:
                return False
            if v > st['best']:
                st['best'] = v
            st['lit'] = st['lit'] + 1 if v >= self.CAN_EE_RING_FILL else 0
            return st['lit'] >= confirm

        return probe

    def ee_bright_probe(self, char, bright, confirm=1):
        """给 spam_ae 用的 stop: 【E 图标亮了】= 强化E 就绪。

        (用户 2026-08-31: "坎特的强化E有时候会提前, 所以不能用时间来判断Q,
         应该说按下了强化E就开始按Q")

        【跟 ee_fired_probe 的区别, 以及为什么换成这个】: 那个判的是"亮过又不亮了"
        = 被按掉了 —— 但它跟"一边盲发 E"是矛盾的: E 一亮就被自己的连发按掉,
        读屏根本没机会看到亮的那一帧, 判据永远不成立, 跑满上限。
        现在改成【自己控制那一下】: 这一段只连点不发 E, 一读到亮就退出去,
        由调用方按 E, 按完立刻开始按 Q —— "按下了强化E就开始按Q"。
        """
        st = self._ee_state

        def probe():
            pct = float(char.current_resonance())
            st['best'] = max(st['best'], pct)
            st['lit'] = st.get('lit', 0) + 1 if pct >= bright else 0
            return st['lit'] >= confirm
        return probe

    def ee_fired_probe(self, char, bright, dark_confirm):
        """给 spam_ae 用的 stop: 【图标先亮过, 再看到它不亮】= 强化E 被按掉了。

        【只读亮度, 不读 OCR】: current_resonance() 是一个 90x68 小框的纯白像素占比,
        比模板匹配和 CD 的 OCR 都便宜得多, 而且【不会像 OCR 那样漏读一帧就假阳性】
        (refresh_cd 漏读时三个 CD 全变 0, 见 wait_e_ready 里的说明)。
        实测: 挂着 CD 0.016~0.041 / 强化E 就绪 0.122~0.171。
        """
        st = self._ee_state

        def probe():
            pct = float(char.current_resonance())
            st['best'] = max(st['best'], pct)
            if pct >= bright:
                st['ready'] = True
                st['dark'] = 0
                return False
            if st['ready']:
                st['dark'] += 1
                return st['dark'] >= dark_confirm
            return False
        return probe

    def wait_forte_spent(self, char, cap, dark, tag='回路打空', poke=True,
                         interval=None, read_every=0.08, min_wait=0.0):
        """边打边等【回路条右边那个指示灭掉】= 回路被强化A 吃完了。

        坎特蕾拉的交棒判据(用户 2026-08-31: "回路没消耗完之前她回路条右边的指示
        一直都是亮的, 消耗完了再切弗洛洛")。

        【同一个 mouse_forte 模板, 在她身上好用、在莫宁和卜灵身上都读不到】—— 这就是
        "不是每个角色都做了检测"的具体样子, 用之前先看类文档里那张审计表。

        【要求"连续灭够 dark 秒"而不是"灭了一帧"】: 实测她那一段中间会有两次
        0.2 秒左右的短暂熄灭(出招时图标没渲染), 只看单帧会提前 5 秒交棒。

        【⚠ 别再加"先看到它亮过"这个条件】(2026-08-31 栽过): 直觉上那样能挡住
        "一进门就误判", 实际后果是【回路要是在进这一格之前就打完了, 判据永远不成立】,
        只能跑满上限 —— 用户的原话是"回路已经打完了还不切弗洛洛"。
        要挡进门那几帧就用 min_wait, 不要用 seen_lit。
        (下面这个 seen_lit 是给"从头到尾没亮过 = 压根没进强化状态"那条早退用的,
         不参与"算不算打空"的判定。)

        【到上限也往下走】: 被怪打断、回路没吃完是常事(用户: "那也没关系,
        直接走弗洛洛的流程就行") —— 卡在这里比少打几下强化A 糟得多。
        """
        interval = self.A_INTERVAL if interval is None else interval
        start = time.time()
        n = 0
        reads = 0
        spent = False
        dark_since = None
        seen_lit = False
        next_click = start
        next_read = start + max(0.0, min_wait)
        while time.time() - start < cap:
            now = time.time()
            if poke and now >= next_click:
                self.click()
                n += 1
                next_click += interval
                if next_click < now:
                    next_click = now + interval
            now = time.time()
            if now >= next_read:
                next_read = now + read_every
                reads += 1
                self.task.next_frame()
                try:
                    lit = bool(char.is_mouse_forte_full())
                except Exception:
                    lit = True          # 读不出来当作"还亮着", 宁可多打几下
                if lit:
                    seen_lit = True
                    dark_since = None
                elif dark_since is None:
                    dark_since = now
                elif now - dark_since >= dark:
                    spent = True
                    break
                # 【从头到尾就没亮过 = 压根没进强化状态】(大招丢了、重击没接上)。
                # 这时候没有回路可打空, 跑满上限纯亏, 早点走人
                if not seen_lit and now - start >= min_wait + self.CAN_FORTE_NOLIT:
                    break
            nap = min(next_click if poke else next_read, next_read) - time.time()
            if nap > 0:
                self.macro_wait(min(nap, 0.02))
        self.macro_mark(f'{tag}({"空" if spent else "cap"},'
                        f'{"见过亮" if seen_lit else "没见过亮"},'
                        f'A x{n},读x{reads},{time.time() - start:.2f}s)')
        return spent

    def wait_e_ready(self, char, cap, tag='E亮', poke=True, interval=None,
                     read_every=0.10, min_wait=0.0, bright=0.08, confirm=2):
        """边打边等【E 图标亮起来】(不再显示 CD 读数), 亮了立刻返回。

        坎特蕾拉的强化E 专用(用户 2026-08-31: "坎的强化E都亮了你没马上按")。
        【判据是两条 AND, 而且要连着读到几次】(用户 2026-08-31 实机: "有一次坎没有
        按强化E 而且提前切弗洛洛了, 坎协奏都没满")。
        【只看"CD 读数消失"会假阳性】: refresh_cd 是【先把三个 CD 全清零, OCR 读到
        什么才填回去】—— OCR 一次没读出来(特效糊住数字/数字正在换)三个就全是 0,
        这一格当场认为"强化E 好了"。按下去是空操作(E 其实还在 CD), 后面 1.9 秒、Q、
        协奏没满就切人, 一串全塌。
        【所以再加一条正向判据: 图标亮不亮】。录像量的 E 图标框纯白像素占比:
            挂着 CD 读数         0.016 ~ 0.041
            换图标、没读数(过渡)  0.000
            强化E 就绪(发亮)      0.122 ~ 0.171   <- 三四倍的分离
        这正是框架 current_resonance() 的算法(text_white_color 244-255)。
        两条都成立、并且连着 confirm 次才认。

        【方向很重要】: 这一格是"条件成立就往下走", 假阳性直接毁掉后面一串;
        而 press_e_until_fired / fire_echo_until_fired 是"条件成立就停手发键",
        假阳性只是多按几下, 无害。同一个 get_cd, 用在两个方向上风险完全不同。

        【为什么不用固定秒数】: 那一段实测 6.5 秒, 但它取决于这一轮打出了多少强化A
        (每下吃一格回路), 被打断就会推后。定时要么早按(空操作)要么晚按(干等)。

        【回路条右边那个 mouse_forte 在这里不适用】: 那是"长按重击"的提示,
        她整段强化状态里一直亮着(录像 75.65~79.55), 分不出强化E 就绪没有。
        """
        interval = self.A_INTERVAL if interval is None else interval
        start = time.time()
        n = 0
        reads = 0
        ready = False
        streak = 0
        nocd_streak = 0
        pct = 0.0
        best = 0.0
        next_click = start
        next_read = start + max(0.0, min_wait)
        while time.time() - start < cap:
            now = time.time()
            if poke and now >= next_click:
                self.click()
                n += 1
                next_click += interval
                if next_click < now:
                    next_click = now + interval
            now = time.time()
            if now >= next_read:
                next_read = now + read_every
                reads += 1
                self.task.next_frame()
                try:
                    no_cd = not self.task.has_cd('resonance')
                except Exception:
                    no_cd = False
                try:
                    pct = float(char.current_resonance())
                except Exception:
                    pct = 0.0
                best = max(best, pct)
                streak = streak + 1 if (no_cd and pct >= bright) else 0
                nocd_streak = nocd_streak + 1 if no_cd else 0
                if streak >= confirm:
                    ready = True
                    break
                # 【亮度门槛万一没标准(换分辨率/框对不上)的兜底】: 连着这么多次都读到
                # "没有 CD 读数"也认。OCR 漏读是单帧事件, 不会连着 confirm*3 次都漏
                if nocd_streak >= confirm * 3:
                    ready = True
                    self.logger.info(f'{tag}: 靠"连续 {nocd_streak} 次没读到 CD"判定就绪 '
                                     f'(亮度只到 {pct:.3f} < {bright:.2f}) —— '
                                     f'亮度门槛可能要重标')
                    break
            nap = min(next_click if poke else next_read, next_read) - time.time()
            if nap > 0:
                self.macro_wait(min(nap, 0.02))
        self.macro_mark(f'{tag}({"亮" if ready else "cap"},白{best:.2f},'
                        f'A x{n},读x{reads},{time.time() - start:.2f}s)')
        if not ready:
            self.logger.info(
                f'{tag}: 强化E 判据没成立(最亮 {best:.3f} / 门槛 {bright:.2f}) — '
                f'亮度一直上不去就是这一轮强化A 打得不够、回路没吃完; '
                f'要是画面上明明亮了, 调 bright 那个门槛(它跟 box_resonance 这个框的'
                f'大小有关, 换分辨率可能要重标)')
        return ready

    def press_e(self, char, tag='E', window=0.20, interval=0.07, poke=False):
        """把一发技能键【递进去】。

        【为什么不是单发】: 动画期间的按键是被丢掉的、不排队, 单发很容易整个丢掉,
        症状是"那一步慢了"(要等整个动画演完才有第二次机会)。窗口给 0.2 秒:
        比任何一个"按完到能再按"的派生帧都短, 不会把下一发提前按出来。
        """
        return self.spam_key(char.send_resonance_key, window, interval=interval,
                             tag=tag, poke=poke)

    def wait_con_full(self, char, cap, tag='协奏', poke=False):
        """盯着协奏圈等它满, 满了立刻返回。【默认不点击】。

        跟 rover_air_a_until_con 的区别: 那个是"边打边看", 这个是【纯等】——
        用在"上一个动作自己就会把协奏顶满、只是要知道什么时候到"的地方。
        """
        start = time.time()
        full = False
        n = 0
        next_click = 0.0
        while time.time() - start < cap:
            self.task.next_frame()
            try:
                if char.get_current_con() >= self.CON_ENOUGH:
                    full = True
                    break
            except Exception:
                pass
            now = time.time()
            if poke and now >= next_click:
                self.click()
                n += 1
                next_click = now + self.A_INTERVAL
        self.macro_mark(f'{tag}({"满" if full else "cap"},x{n},'
                        f'{time.time() - start:.2f}s)')
        return full
    # ==================== 长按重击(三个人都要用) ====================

    def wait_mouse_forte(self, char, cap, min_wait=0.0, tag='长按提示', poke=True,
                         interval=None, read_every=0.10):
        """边连点边等准星旁的【长按重击提示】亮起来, 亮了立刻返回。

        【弗洛洛那一段现在不走这里, 走 wait_heavy_ready】(它要同时等协奏那一条)。
        这个留着是因为它是"只等长按提示"的最小形态 —— 想把某一格单独拆出来调,
        或者别的角色要用, 直接调它。

        这是这条轴上最重要的一个读屏判据 —— 三个人的"该长按了"都是它:
          弗洛洛: 六个乐声满 -> 可以出强化重击
        判据用的是框架自带的 find_mouse_forte()(模板匹配 + 二值化), 不是自己数图标。

        【连点期间可能读不到这个图标】: 莫宁那边就是这样(她一直在出招, 图标没渲染),
        清达莫为此在连点里挖了 MOR_READ_PAUSE 的停顿。弗洛洛这边实机是读得到的,
        所以没挖 —— 哪天她也卡在"重击闸门(乐声?)"上, 照清达莫 Denia.py 里 mor_hold_heavy 那个形状改。

        【为什么不按固定时长】: 攒资源的速度取决于每一下有没有打中, 转火/位移都会
        让它浮动。实机三圈"变奏 -> 六个乐声"分别是 7.1 / 7.0 / 6.9 秒, 看着稳,
        但那是没脱手的理想情况; 打歪一下就要多走一整轮连段。

        Args:
            min_wait: 【这之前一律不认】。参考录像里这个提示在乐声还没满的时候
                会闪一下(单帧), 一读到就长按的话就是拿五个乐声去出强化重击 ——
                招出得去, 但后面那一发大招少一层, 整圈的伤害都不对。
                所以压一个下界: 比"最快能攒满"再短一点, 只挡误判、不当等待用。
            read_every: 两次读屏之间至少隔这么久。见下面那段【必须解耦】。

        【点击的节奏和读屏的节奏必须各走各的】(用户 2026-08-31 指出"A一下停一下"):
        原来是"点一下 -> next_frame -> 模板匹配 -> 再回到点击", 一圈要 0.05~0.09 秒,
        于是点击实际落在 0.12~0.20 秒一下, 而不是 interval 说的那个数。
        这一格盖的是弗洛洛攒乐声最长的那一段, 八九个派生点每个晚 0.1 秒就累出快一秒。
        engine 里 spam_key 早就写过同一条(发键和点击各走各的), 我在读屏这边又踩了一次。
        现在: 点击按【绝对时刻表】走(next_click += interval, 不用 now + interval,
        免得读屏耗时一点点累进去), 读屏另开一个 read_every 的节奏。
        """
        interval = self.A_INTERVAL if interval is None else interval
        start = time.time()
        deadline_min = start + max(0.0, min_wait)
        n = 0
        reads = 0
        lit = False
        next_click = start
        next_read = deadline_min      # 到点之前一律不读, 省下来的全给点击
        while time.time() - start < cap:
            now = time.time()
            if poke and now >= next_click:
                self.click()
                n += 1
                # 【累加不重置】: 用 next_click += interval 而不是 now + interval,
                # 后者会把每次点击自身的耗时一点点累进节奏里, 越点越慢
                next_click += interval
                if next_click < now:      # 掉队太多就重新对齐, 别攒出一串补点
                    next_click = now + interval
            now = time.time()
            if now >= next_read:
                next_read = now + read_every
                reads += 1
                self.task.next_frame()
                try:
                    if char.is_mouse_forte_full():
                        lit = True
                        break
                except Exception:
                    pass
            # 【睡到"下一件事"为止】: 睡固定 0.01 秒的话空转一圈也要走一遍循环开销,
            # 点击照样会被挤晚
            nap = min(next_click if poke else next_read, next_read) - time.time()
            if nap > 0:
                self.macro_wait(min(nap, 0.02))
        self.macro_mark(f'{tag}({"亮" if lit else "cap"},A x{n},读x{reads},'
                        f'{time.time() - start:.2f}s)')
        return lit

    def wait_heavy_ready(self, char, con_level, cap, note_min=0.0,
                         tag='重击闸门', poke=True, interval=None, read_every=0.06,
                         dodge_at=0.0):
        """一个循环里【同时】等两件事, 两个都成立就立刻长按重击:
             1) 六个乐声满 —— 准星旁的长按重击提示亮了(find_mouse_forte)
             2) 协奏 >= con_level —— 强化重击(+40)和大招(+20)要从这里起跳才填得满

        【为什么必须合成一个循环】(用户 2026-08-31 实机: "协奏已经过了45你没有马上打
        强化重击还是多A了很多"): 原来是先 wait_mouse_forte 再 wait_con_at_least
        两段【顺序】等 —— 先满的那个满了之后, 后一个还要【从头跑一遍】:
        重新计 min_wait、重新走第一次读屏。早就成立的条件白白又等了一轮。

        【两个判据轮流读, 不是每轮都读两个】: 模板匹配和能量环连通域分析都不便宜,
        挂在一起会把点击挤慢(见 wait_mouse_forte 里那段)。已经成立的那个不再读。

        Args:
            note_min: 乐声这一条在这之前一律不认(提示图标起手会闪单帧)。
        【长按提示是硬条件, 没有"到点强行走"这一说】(用户 2026-08-31 实机:
        "强化重击没放出来"): 我原来加过一个兜底 —— 协奏够了之后再给提示 0.8 秒,
        读不到就照样长按。那是错的: 提示没亮就长按, 出来的是【普通重击】,
        既没有强化重击那 40 点协奏、也拿不到定音状态(=大招不解锁), 整圈全塌。
        宁可多 A 几下等它亮, 也不能空放。

        【提示离线验证过是准的】: 把框架的 mouse_forte 模板抠出来在参考录像上跑,
        它在六个乐声满的那一帧(49.72s -> 判据 49.80s)亮起, score 0.67~0.71,
        阈值 0.6 有余量。所以读不到就是真的没准备好, 不是判据坏了。
        """
        interval = self.A_INTERVAL if interval is None else interval
        start = time.time()
        note_ok_after = start + max(0.0, note_min)
        n = 0
        reads = 0
        notes_ok = False
        con_ok = False
        con = 0.0
        which = 0
        next_click = start
        next_read = start
        con_ok_at = None
        notes_by = ''
        dodged = False
        next_shot = start if self.PHRO_SHOT_FORTE else None
        nshot = 0
        while time.time() - start < cap:
            # ---- 插一发闪避取消后摇 ----: 见 PHRO_DODGE_AT
            # 【放在点击前面】: 闪避发完立刻回来(after_sleep=0), 紧接着的那一下点击
            # 就是"用A把闪避接回去"的那一下
            if dodge_at and not dodged and time.time() - start >= dodge_at:
                dodged = True
                self.dodge(tag='弗闪避')
            now = time.time()
            if poke and now >= next_click:
                self.click()
                n += 1
                next_click += interval
                if next_click < now:
                    next_click = now + interval
            now = time.time()
            if now >= next_read:
                next_read = now + read_every
                reads += 1
                # 轮流读: 已经成立的那一条不再花钱
                if not notes_ok and (con_ok or which % 2 == 0):
                    self.task.next_frame()
                    full, by = self.phro_forte_full(char)
                    if full and time.time() >= note_ok_after:
                        notes_ok = True
                        notes_by = by
                elif not con_ok:
                    try:
                        con = float(char.get_current_con())
                    except Exception:
                        con = 0.0
                    if con >= con_level:
                        con_ok = True
                        con_ok_at = time.time()
                which += 1
                if notes_ok and con_ok:
                    break
            # ---- 连拍标定 ----: 见 PHRO_SHOT_FORTE。【只发一次截图, 不等】,
            # 所以点击时刻表照跑, 这一段的输出一点不受影响
            if next_shot is not None and nshot < self.PHRO_SHOT_FORTE_MAX:
                now = time.time()
                if now >= next_shot:
                    next_shot = now + self.PHRO_SHOT_FORTE_EVERY
                    try:
                        self.task.screenshot(
                            f'phro_forte_{nshot:02d}_{now - start:.2f}s'
                            f'_{"亮" if notes_ok else "暗"}')
                        nshot += 1
                    except Exception:
                        next_shot = None
            nap = min(next_click if poke else next_read, next_read) - time.time()
            if nap > 0:
                self.macro_wait(min(nap, 0.02))
        if dodge_at and not dodged:
            # 【没轮到就说明这一段比 3.6 秒短】: 闸门先成立了, 闪避不该再拖时间
            self.macro_mark('弗闪避跳过(闸门先到)')
        self.macro_mark(f'{tag}(乐声{notes_by + "亮" if notes_ok else "?"},'
                        f'协奏{con:.2f}{"ok" if con_ok else "!"},'
                        f'A x{n},读x{reads},{time.time() - start:.2f}s)')
        if not (notes_ok and con_ok):
            self.logger.info(f'{tag}: gave up after {cap:.1f}s '
                             f'(notes={notes_ok} con={con:.2f}/{con_level:.2f})')
        return notes_ok and con_ok

    def wait_con_at_least(self, char, level, cap, tag='协奏', poke=True,
                          interval=None, read_every=0.12):
        """边连点边等协奏圈涨到 level 以上(0~1)。到上限也往下走, 不把轴卡死。

        【弗洛洛那一段现在不走这里, 走 wait_heavy_ready】(它要同时等乐声那一条)。
        这个留着是"只等协奏门槛"的最小形态, 别处要用直接调。

        跟 wait_con_for_intro 的区别: 那个是"等满了才交棒", 这个是
        【等到某个门槛才做下一个动作】—— 因为后面那两发(强化重击 +40、大招 +20)
        自己还会把圈推上去一大截, 等满再动手就是把那一截白等掉。

        【读协奏不便宜】(能量环的连通域分析), 所以跟点击【分成两个节奏】:
        点击按绝对时刻表走, 读屏另按 read_every。挂在一起就是"A一下停一下"。
        【等的期间必须继续打】: 圈是靠打中才涨的, 干站着等只会等到超时。

        【第一局可能一直读 0】: get_current_con 要先见过一次满圈才知道满圈多大
        (task.con_full_size 是学出来的)。所以读不到不当异常处理, 跑满 cap 往下走。
        """
        interval = self.A_INTERVAL if interval is None else interval
        start = time.time()
        n = 0
        reads = 0
        con = 0.0
        hit = False
        samples = []
        next_click = start
        next_read = start
        while time.time() - start < cap:
            now = time.time()
            if poke and now >= next_click:
                self.click()
                n += 1
                next_click += interval
                if next_click < now:
                    next_click = now + interval
            now = time.time()
            if now >= next_read:
                next_read = now + read_every
                reads += 1
                try:
                    con = float(char.get_current_con())
                except Exception:
                    con = 0.0
                if len(samples) < self.CON_SAMPLE_MAX:
                    samples.append(f'{time.time() - start:.2f}:{con:.2f}')
                if con >= level:
                    hit = True
                    break
            nap = min(next_click if poke else next_read, next_read) - time.time()
            if nap > 0:
                self.macro_wait(min(nap, 0.02))
        self.macro_mark(f'{tag}({con:.2f},{"ok" if hit else "CAP"},A x{n},'
                        f'读x{reads},{time.time() - start:.2f}s)')
        if not hit:
            self.logger.info(f'{tag}: con only reached {con:.2f} (< {level:.2f}) in '
                             f'{cap:.1f}s — {" ".join(samples)}')
        return hit

    def hold_heavy(self, char, cap, min_hold=0.20, tag='长按重击',
                   skip_if_dark=False, held_since=None, full_probe=None):
        """按住左键出重击, 【提示一消失就松手】。

        【为什么不用原版的 heavy_click_forte】: 那个进门先读一次屏判断提示在不在,
        读到不在就整段跳过 —— 而我们是刚从 wait_mouse_forte 出来的, 那一次读屏是
        纯重复; 更麻烦的是它的 wait_until 上限写死 2 秒, 这里三个人要的上限不一样。

        【min_hold 是必需的】: 提示图标在起手那几帧会闪一下, 不压一个下界的话
        第一帧就会误判成"招已经出去了"当场松手, 重击根本没蓄出来。

        【松手不会取消已经出去的招】: 强化重击/观测重击是完整的一整段动作,
        按住只是把它【触发】出来 —— 触发之后松手, 它照样演完。所以这里越早松手
        越好, 后面那一发 R 才能贴着解锁帧打断它。
        """
        # 【按下去之前先记一笔提示状态】: 出问题时这一条能直接分清是
        # "根本没准备好就长按"(灭) 还是 "按了但没蓄出来"(亮)
        # 【full_probe: 换一个读得到的判据】: 框架的 is_mouse_forte_full 是模板匹配,
        # 在弗洛洛身上会漏(实机连拍抓到过: 指示一直亮着, 模板却判暗)。
        # 这一格的颜色判据见 PHRO_FORTE_BOX
        probe = full_probe or (lambda: bool(char.is_mouse_forte_full()))
        if held_since is not None:
            # 【手已经按在上面了】(预输入): 进门那次读屏和 mouse_down 全跳过 ——
            # 见 PHRO_PREHOLD。min_hold 也要从【真正按下去的那一刻】算,
            # 不然会白等一遍
            lit_at_entry = True
        else:
            try:
                self.task.next_frame()
                lit_at_entry = probe()
            except Exception:
                lit_at_entry = None
        if skip_if_dark and lit_at_entry is False:
            # 【提示没亮就干脆不按】: 提示灭着长按出来的是普通重击 ——
            # 没有强化重击那 40 点协奏, 也拿不到定音状态(大招不解锁),
            # 比不打还糟(用户 2026-09-01: 需要重击检测亮起才可以重击R)
            self.macro_mark(f'{tag}(提示灭,跳过)')
            self.logger.warning(f'{tag}: prompt not lit, skipping the hold entirely '
                                f'(a plain heavy would drop the state)')
            return False
        if held_since is None:
            self.task.mouse_down()
            self.holding_attack = True
        start = held_since if held_since is not None else time.time()
        fired = False
        try:
            if min_hold > 0:
                self.macro_wait(min_hold)
            while time.time() - start < cap:
                self.task.next_frame()
                try:
                    if not probe():
                        fired = True
                        break
                except Exception:
                    pass
                self.macro_wait(0.02)
        finally:
            self.release_attack()
        self.macro_mark(f'{tag}(按下时{"亮" if lit_at_entry else "灭" if lit_at_entry is not None else "?"},'
                        f'{"出" if fired else "cap"},{time.time() - start:.2f}s)')
        if lit_at_entry is False:
            self.logger.warning(f'{tag}: the heavy prompt was NOT lit when the hold '
                                f'started — this will come out as a plain heavy')
        return fired

    def hold_through_lib(self, tag='预输入重击', time_out=None, tail=0.0,
                         f_interval=None, settle=0.0):
        """演出期间【一直按住左键】(预输入重击), 顺带可以一直按处决键。

        坎特蕾拉那一格专用: 演出结束的第一帧就要有一个重击落进去, 她才能无缝接上
        重击·浮潜幻海(帧表第22F给 8 秒强化状态)。

        【为什么是按住而不是连点】: 重击是长按出的招, 连点只会打出普攻。
        而演出期间的输入是被丢掉的、不排队 —— 所以唯一可行的形状就是"一直按着",
        让游戏在放行的第一帧读到"左键处于按下状态"。

        【为什么不能只按 tail 那一段】: 演出结束的时刻是浮动的(大招哪一帧出手不定),
        等 HUD 回来再按下就已经晚了半拍, 中间那一下会变成普攻。

        Args:
            f_interval: 顺带按处决键的间隔(None = 不按)。
                【处决就该放在这里】(用户 2026-08-31: "能不能把F放到坎R后?
                R的时候不是要预输入重击吗, 这个预输入放在处决动画里, 坎R了就一直按F")。
                好处是【两段演出串在一起, 只花一次预输入】: 大招演完 -> 处决接上 ->
                处决演完 -> 那一下重击落在最后, 8 秒强化状态从那一刻才开始烧。
                【比掺在后面的 A/E 连发里好】: 那样 F 会把她的普通 E 打断(实机验证过)。
            settle: 【HUD 要连续回来这么久才算演出真的完了】。
                大招演完到处决演出开始之间 HUD 会短暂回来一下 —— 一看到就退的话,
                预输入正好卡在两段演出中间, 重击会在处决动画里被吃掉。
        """
        time_out = self.LIB_ANIM_TIME_OUT if time_out is None else time_out
        self.task.mouse_down()
        self.holding_attack = True
        start = time.time()
        gone_seen = False
        back = False
        nf = 0
        back_since = None
        next_f = start
        try:
            while time.time() - start < time_out:
                now = time.time()
                if f_interval and self.USE_F_BREAK and now >= next_f:
                    self.task.send_key('f', after_sleep=0)
                    nf += 1
                    next_f += f_interval
                    if next_f < now:
                        next_f = now + f_interval
                self.task.next_frame()
                if not self.task.in_team()[0]:
                    gone_seen = True
                    back_since = None
                elif gone_seen or time.time() - start >= self.HUD_NO_ANIM_GRACE:
                    # 【要连续在场 settle 秒才认】: 两段演出之间 HUD 会闪回来一下
                    if back_since is None:
                        back_since = time.time()
                    if time.time() - back_since >= settle:
                        back = True
                        break
                self.macro_wait(0.01)
            if tail > 0:
                self.macro_wait(tail)
        finally:
            self.release_attack()
        # 演出这一段计入 freeze, 否则框架的 time_elapsed_accounting_for_freeze
        # 会把它算成"这个角色磨蹭了 4 秒"
        self.add_freeze_duration(start, time.time() - start)
        self.macro_mark(f'{tag}({"ok" if back else "timeout"},'
                        f'{"anim" if gone_seen else "NOANIM"}'
                        f'{f",F x{nf}" if nf else ""},'
                        f'{time.time() - start:.2f}s)')
        return back

    # ==================== 弗洛洛段(启动/循环共用) ====================

    def seg_phrolova(self, opener=False):
        """攒 6 个乐声 -> 长按重击 -> 大招 -> 交棒前的最后一步(不切人)。

        【这一段不切人】: 下一个是谁、带不带变奏, 由 perform_opener / perform_loop 决定
        (启动轴切卜灵, 循环轴变奏坎特蕾拉)。

        【乐声怎么来的】(帧表 弗洛洛 核心回收1): A3、强化A、E、强化E 各给 1 层,
        上限 6 层, 大招一次吃掉 6 层。所以这一段就是"连点普攻 + 中间插一发 E",
        A3 -> 强化A -> (E) -> 强化A -> A3 -> 强化A 正好六个。
        【连段是自己推的, 不用数】: 打到 A3 之后下一下 A 自动变强化A, 再下一下又从
        A1 起 —— 所以除了那一发 E, 全程就是连点, 不需要按段数分窗口。

        Args:
            opener: 启动轴走这条。【两条轴的入场方式不一样】——
                启动轴是手动切人(连段从 A1 起、没有输入锁),
                循环轴是变奏入场(QTE 复用 A2, 有 77 帧输入锁), 所以参数分两档。
        """
        # 【没拿到变奏就走"手动切人"那一档】: 上一格协奏没填满时 handoff 会把
        # has_intro 记成 False —— 那这次进场就【没有 QTE 那 1.28 秒输入锁】,
        # 还按变奏那档等就是白站 1.3 秒, 后面每一格跟着错位。
        # (那种情况本身是个 bug, 坎那边会打 warning; 这里只是别让它雪上加霜)
        no_intro = (not opener) and (not self.has_intro)
        if no_intro:
            self.logger.warning('phrolova: came in WITHOUT an intro — 上一格协奏没满。'
                                '这一圈按手动切人那一档跑')
        if opener or no_intro:
            # 手动切人进来的, 没有变奏的输入锁, 给一点点稳定时间就能开打。
            # 【用 macro_gap 不用 macro_wait】: 持续普攻这时已经打开, 这一小段也该在打
            self.macro_gap(self.O_ENTER_SETTLE, tag='弗A')
            a_to_e = self.O_PHRO_ENTER_TO_E
        else:
            # 【变奏入场这一段不许出手】: QTE 第77F前不响应输入, 发出去的键全丢。
            # 用 poll_wait 不用 macro_wait —— 纯等待期间画面是冻的, 战斗判定线程
            # 拿到旧帧会误判 target lost
            self.poll_wait(self.PHRO_INTRO_LOCK, tag='弗入场锁')
            a_to_e = self.L_PHRO_INTRO_TO_E

        self.poking = True
        # 【这里原来有一段 macro_spam(a_to_e) 盲打】—— 已经去掉了:
        # 那 1.35 秒里没人看环, 强化普攻亮了也白亮, 第一次闪避因此迟到 1.1 秒
        # (用户 2026-09-01)。现在起手那几下 A 由 phro_ea_cycle 自己的连点打,
        # 下界见 O_PHRO_EA_MIN_A / L_PHRO_EA_MIN_A
        # ---- 强化普攻循环 ----: 见 phro_ea_cycle / PHRO_EA_DELAY 那一段
        # 【这里换掉了原来那串 E -> 强化E -> Q -> 连点等闸门】(用户 2026-09-01
        # 重新给的流程)。原来那套的所有零件都还在(press_e_until_fired /
        # phro_press_ee / wait_heavy_ready), 只是不在这条路上了
        # 【循环轴开预输入】(用户 2026-09-01: "检测小鼠标亮起一瞬间开始预输入重击")。
        # 启动轴不开: 它的闸门是"音符满 AND 协奏够", 协奏那一条可能比音符晚很多,
        # 提前按住会在等协奏的那段时间里空放一发普通重击
        # 启动轴闸门不看协奏时(O_PHRO_GATE_NEED_CON=False)也开: 空放普通重击的顾虑没了
        self.phro_ea_cycle(opener, prehold=self.PHRO_PREHOLD and ((not opener) or (not self.O_PHRO_GATE_NEED_CON)))

        # ---- 长按重击 -> 强化重击 -> R 大招。【打不出来就重来, 不许直接切人】 ----
        # 理由见 PHRO_LIB_TRIES 那一段
        fired_lib = False
        for attempt in range(1, self.PHRO_LIB_TRIES + 1):
            if attempt > 1:
                # 【重试前先把提示等回来】: 被打断之后乐声还在, 提示通常还亮着,
                # 这一步几乎不花时间; 等不到就直接再长按一次试试(强化重击"技能中断后"
                # 也会解锁大招, 说不定上一次已经解锁了, 只是 R 被吞了)
                self.poking = True
                self.wait_mouse_forte(self, cap=self.PHRO_RETRY_WAIT,
                                      min_wait=0.20,
                                      interval=self.PHRO_A_INTERVAL,
                                      tag=f'弗重击提示{attempt}')
            # 【长按期间不点】: hold_heavy 是按住左键, 再插点击只会把长按打断
            self.poking = False
            # 【第一轮接手预输入那只手】: prehold_at 是按下去的时刻, min_hold 从那里算;
            # 重试轮次没有预输入, 老老实实自己按
            # 【指示没亮就整发不打】(skip_if_dark): 那样出来的是普通重击 ——
            # 没有那 40 点协奏、也拿不到定音状态(大招不解锁), 比不打还糟。
            # 【这条是用户给的硬要求】(2026-09-01: "需要同时满足协奏值35以及
            # 重击检测亮起才可以重击R")
            self.hold_heavy(self, cap=self.PHRO_HEAVY_CAP,
                            min_hold=self.PHRO_HEAVY_MIN, skip_if_dark=True,
                            held_since=(self.prehold_at if attempt == 1 else None),
                            full_probe=lambda: self.phro_forte_full(self)[0],
                            tag='弗长按重击' if attempt == 1 else f'弗长按重击{attempt}')
            # 强化重击第139F(2.32秒)解锁大招, 所以 R 要一直重发到演出真的开始。
            # 【这几秒里必须继续连点】(poke=True): 不点的话她就是站着按 R
            if self.fire_lib(self, tag='R弗大招' if attempt == 1 else f'R弗大招{attempt}',
                             window=self.PHRO_HEAVY_TO_LIB,
                             poke=True, click_interval=self.PHRO_A_INTERVAL):
                fired_lib = True
                break
            self.prehold_at = None
            self.logger.warning(f'phrolova: 第 {attempt} 轮"重击+R"没放出来 —— '
                                f'多半是长按被打断了。乐声不会因此清掉, 接着打再来一次')
        if fired_lib:
            self.poke_until_hud_back(tag='弗大招Anim',
                                     time_out=self.PHRO_LIB_ANIM + 3)
        else:
            # 【试满还是不行才往下走】: 卡死比少一发大招更糟, 但要吼出来 ——
            # 这一圈的协奏也会跟着不够, 下一个人可能拿不到变奏入场
            self.logger.warning(
                f'phrolova: {self.PHRO_LIB_TRIES} 轮都没把大招放出来, 照样交棒 —— '
                f'这一圈少一发大招。往上游查: 六乐声那一格是不是根本没满'
                f'(看 重击闸门 那一行的"乐声"字段)')

        # ---- 演出完 -> 交棒前的最后一步 ----
        # 【循环轴补几下把协奏顶满】: 下一个是坎特蕾拉, 她这一次上场就是为了吃延奏
        # (大招-前置 协奏回收20, 演出结束时协奏基本就是满的, 实测这一格只要 0.85 秒)。
        # 【启动轴不等】: 下一个是卜灵, 她走跳A 那套, 变奏入场对她没有用处
        # (露丽卜实机: 变奏入场跳不起来)。满不满由游戏决定, 这里只是不去等
        self.poking = True
        if not opener:
            self.wait_con_for_intro(self, 'Cantarella', poke=True,
                                    time_out=self.PHRO_POST_LIB_CON)

    # ==================== 卜灵段 ====================

    def wait_hud_up(self, cap=None, tag='HUD'):
        """等队伍 HUD 【现在】在场。按 R 之前用 —— HUD 本来就不在的时候 fire_lib 会当场判
        "演出开始了", 一发都没按出去就记成放了。跟 wait_hud_back(先消失再回来)是两回事。"""
        cap = self.HUD_UP_CAP if cap is None else cap
        start = time.time()
        while time.time() - start < cap:
            self.task.next_frame()
            if self.task.in_team()[0]:
                if time.time() - start > 0.05:
                    self.macro_mark(f'{tag}在场({time.time() - start:.2f}s)')
                return True
            self.macro_wait(0.02)
        self.macro_mark(f'{tag}一直不在({cap:.1f}s)')
        return False

    def bl_ring(self):
        """卜灵重击图标外圈: 返回 ('blue' | 'yellow' | None, 黄占比, 蓝占比)。拿不到画面返回 (None, -1, -1)。

        手上不到两个卦象(或刚加卦象那半秒白光过渡)外圈不亮, 读成 None。
        按 HSV 判不按 RGB: 圈会呼吸, 亮度起伏大, 色相稳。只截圈附近一小块, 每帧读不花时间。
        """
        try:
            import cv2
            import numpy as np
            frame = self.task.frame
            h, w = frame.shape[:2]
            cx, cy = int(w * self.BL_RING_CX), int(h * self.BL_RING_CY)
            r0, r1 = h * self.BL_RING_R0, h * self.BL_RING_R1
            m = int(r1) + 2
            crop = frame[cy - m:cy + m + 1, cx - m:cx + m + 1]
            yy, xx = np.mgrid[-m:m + 1, -m:m + 1]
            d = np.sqrt(xx * xx + yy * yy)
            sel = (d >= r0) & (d <= r1)
            hsv = cv2.cvtColor(crop, cv2.COLOR_BGR2HSV)
            hh, ss, vv = hsv[..., 0][sel], hsv[..., 1][sel], hsv[..., 2][sel]
            blu = float(((hh >= 85) & (hh <= 115) & (ss > 110) & (vv > 140)).mean())
            yel = float(((hh >= 20) & (hh <= 35) & (ss > 60) & (vv > 150)).mean())
        except Exception:
            return None, -1.0, -1.0
        if blu >= self.BL_RING_BLUE:
            return 'blue', yel, blu
        if yel >= self.BL_RING_YELLOW:
            return 'yellow', yel, blu
        return None, yel, blu

    def bl_a4_until_blue(self, tag, max_clicks, cap, min_blue=0.0, gua_before=None):
        """隔 BL_A4_CLICK_GAP 点一下 A(最多 max_clicks 下), 外圈读到蓝的那一帧起不再点(min_blue 秒之前读到的蓝不算);
        连 BL_RING_CONFIRM 帧蓝返回 True, cap 到点返回 False(交给两段重击那段换卦象)。HUD 不在的帧不读。
        gua_before(E 之后读的卦象栏): 卦象栏变了、最新一个是震(A4 命中)连 BL_GUA_CONFIRM 帧就算到, 不再等 min_blue。"""
        start = time.time()
        gua_hits = 0
        gua_got = None
        n = streak = 0
        next_click = 0.0
        blue_seen = False
        last = None
        trace = []
        while time.time() - start < cap:
            now = time.time()
            if not blue_seen and n < max_clicks and now >= next_click:
                self.click()
                n += 1
                next_click = now + self.BL_A4_CLICK_GAP
            self.task.next_frame()
            if self.task.in_team()[0]:
                if gua_before is not None:
                    g = self.bl_gua()
                    if g and g != gua_before and g.endswith('震'):
                        gua_hits += 1
                        blue_seen = True            # A4 已经出了, 不再点(多点会排出 A1->A2, A2 的艮)
                        if gua_hits >= self.BL_GUA_CONFIRM:
                            gua_got = g
                            break
                    else:
                        gua_hits = 0
                color, yel, blu = self.bl_ring()
                last = color
                if len(trace) < 40:
                    # 带上协奏: A4 打中协奏 +7.5, 能分清是 A4 没出(协奏不动)还是符的顺序错了(协奏涨了圈还黄)
                    trace.append(f'{time.time() - start:.2f}:{(color or "-")[0]}{yel:.2f}/{blu:.2f}c{self.bl_con():.2f}')
                if color == 'blue' and time.time() - start >= min_blue:
                    blue_seen = True
                    streak += 1
                    if streak >= self.BL_RING_CONFIRM:
                        break
                else:
                    streak = 0
            self.macro_wait(0.02)
        if gua_got:
            self.macro_mark(f'{tag}A4震到({gua_before or "空"}->{gua_got},A x{n},{time.time() - start:.2f}s)')
            return True
        got = streak >= self.BL_RING_CONFIRM
        self.macro_mark(f'{tag}A4到蓝圈({"蓝" if got else "CAP:" + (last or "不亮")},A x{n},{time.time() - start:.2f}s)')
        if not got:
            self.logger.info(f'{tag}A4到蓝圈: 没等到蓝圈 — {" ".join(trace)}')
        return got

    def bl_hold(self, hold, tag):
        """按住左键 hold 秒松手。按住期间不发任何键(PostMessage 后端的键会先投 WM_ACTIVATE, 把按住打断)。"""
        self.task.mouse_down()
        self.holding_attack = True
        self.macro_mark(f'{tag}_down')
        try:
            self.macro_wait(hold)
        finally:
            self.release_attack()
        self.macro_mark(f'{tag}_up({hold:.2f}s)')

    def bl_ring_settled(self, cap):
        """不按键读圈, 连 BL_RING_CONFIRM 帧读数相同就返回它('blue' / 'yellow' / None=不亮); 到点没读稳返回 'unknown'。"""
        start = time.time()
        last, streak = 'unknown', 0
        while time.time() - start < cap:
            self.task.next_frame()
            if self.task.in_team()[0]:
                c = self.bl_ring()[0]
                streak = streak + 1 if c == last else 1
                last = c
                if streak >= self.BL_RING_CONFIRM:
                    return c
            self.macro_wait(0.02)
        return 'unknown'

    def bl_con(self):
        try:
            return self.con_now()
        except Exception:
            return -1.0

    def bl_heavy_once(self, tag, cap, jump, min_settle):
        """按住左键, 协奏连 2 帧比基准涨 jump(这一段第40F结算)就松手; 没读到涨按满 cap。返回读到涨没有。
        按下后 min_settle 秒内读到的涨是前一个动作晚到的协奏, 不算结算, 并进基准。按住期间不发任何键, 只读协奏。"""
        con0 = self.bl_con()
        base = con0
        self.task.mouse_down()
        self.holding_attack = True
        down = time.time()
        self.macro_mark(f'{tag}_down')
        hits = 0
        con = con0
        trace = []
        try:
            while time.time() - down < cap:
                self.task.next_frame()
                con = self.bl_con()
                t = time.time() - down
                if len(trace) < 45:
                    # 排查用(纯文字): 按住期间每帧协奏 + 外圈, 对得出哪一帧结算、外圈按住时读成什么
                    trace.append(f'{t:.2f}:c{con:.2f}{(self.bl_ring()[0] or "-")[0]}')
                if t < min_settle:
                    base = max(base, con)
                    hits = 0
                else:
                    hits = hits + 1 if (base >= 0 and con - base >= jump) else 0
                if hits >= 2:
                    break
                self.macro_wait(0.02)
        finally:
            self.release_attack()
        jumped = hits >= 2
        self.macro_mark(f'{tag}_up({"涨" if jumped else "CAP"},协奏{con0:.2f}->{con:.2f},{time.time() - down:.2f}s)')
        self.logger.info(f'{tag} 按住读数(基准{base:.2f}) — {" ".join(trace)}')
        return jumped

    def bl_plunge_for_blue(self, tag):
        """跳 -> 空中 A(补按一下), 下落落地命中给震; 每跳一次读圈 BL_PLUNGE_READ 秒, 连读蓝返回 'blue',
        跳满 BL_PLUNGE_MAX 次返回最后读数(交回 bl_heavy_pair 重新判)。读圈期间不按键。"""
        last = 'unknown'
        for i in range(self.BL_PLUNGE_MAX):
            self.task.jump(after_sleep=0)
            self.macro_wait(self.BL_JUMP_TO_A)
            for k in range(self.BL_A_PRESSES):
                self.click()
                if k + 1 < self.BL_A_PRESSES:
                    self.macro_wait(self.BL_A_PRESS_GAP)
            t0 = time.time()
            streak = 0
            while time.time() - t0 < self.BL_PLUNGE_READ:
                self.task.next_frame()
                if self.task.in_team()[0]:
                    c = self.bl_ring()[0]
                    last = c
                    streak = streak + 1 if c == 'blue' else 0
                    if streak >= self.BL_RING_CONFIRM:
                        self.macro_mark(f'{tag}跳A补震#{i + 1}(蓝,{time.time() - t0:.2f}s)')
                        return 'blue'
                self.macro_wait(0.02)
            self.macro_mark(f'{tag}跳A补震#{i + 1}({last or "不亮"})')
        return last

    def bl_gua_refs(self):
        refs = getattr(self, '_gua_refs', None)
        if refs is None:
            kinds, vecs = [], []
            for kind, b64 in self.BL_GUA_REFS:
                v = np.frombuffer(base64.b64decode(b64), np.uint8).astype(np.float32) - 128.0
                v -= v.mean()
                vecs.append(v / max(float(np.linalg.norm(v)), 1e-6))
                kinds.append(kind)
            refs = self._gua_refs = (np.array(vecs), kinds)
        return refs

    def bl_gua(self):
        """卦象栏从左到右, 如 '艮震震震', 一个都没有返回 ''(卜灵不在场也是 '')。HUD 不在 / 读不了返回 None。读当前帧。"""
        if not self.task.in_team()[0]:
            return None
        try:
            frame = self.task.frame
            H, W = frame.shape[:2]
            sc = H / 2160.0
            refs, kinds = self.bl_gua_refs()
            sh = self.BL_GUA_SHIFT if H >= 1000 else 1
            hw, hh = self.BL_GUA_HALF_W * sc, self.BL_GUA_HALF_H * sc
            cy = self.BL_GUA_Y * sc
            x0 = int(W / 2 + self.BL_GUA_DX[0] * sc - hw) - sh - 2
            x1 = int(W / 2 + self.BL_GUA_DX[-1] * sc + hw) + sh + 3
            y0, y1 = int(cy - hh) - sh - 2, int(cy + hh) + sh + 3
            m = frame[y0:y1, x0:x1, :3].min(axis=2).astype(np.float32)
            m -= cv2.GaussianBlur(m, (0, 0), max(1.0, 6.0 * sc))
            best = np.full(len(self.BL_GUA_DX), -1.0, np.float32)
            cls = [''] * len(self.BL_GUA_DX)
            for p, dx in enumerate(self.BL_GUA_DX):
                cx = W / 2 + dx * sc
                bx, by = int(round(cx - hw)) - x0, int(round(cy - hh)) - y0
                bw, bh = int(round(cx + hw)) - x0 - bx, int(round(cy + hh)) - y0 - by
                for sy in range(-sh, sh + 1):
                    for sx in range(-sh, sh + 1):
                        c = m[by + sy:by + sy + bh, bx + sx:bx + sx + bw]
                        v = cv2.resize(c, (16, 16), interpolation=cv2.INTER_AREA).ravel()
                        v -= v.mean()
                        n = float(np.linalg.norm(v))
                        if n < 1e-6:
                            continue
                        r = refs @ (v / n)
                        j = int(r.argmax())
                        if r[j] > best[p]:
                            best[p], cls[p] = r[j], kinds[j]
        except Exception as e:
            if not getattr(self, '_gua_err_logged', False):
                self._gua_err_logged = True
                self.logger.warning(f'bl_gua failed ({e}) — 卜灵卦象栏读不了, 改看外圈')
            return None
        taken = set()
        for p in np.argsort(-best):
            if best[p] < self.BL_GUA_MIN:
                break
            if p - 1 in taken or p + 1 in taken:
                continue
            taken.add(int(p))
        return ''.join(cls[p] for p in sorted(taken))

    def bl_gua_settled(self, cap, nonempty=False):
        """连 BL_GUA_CONFIRM 帧读数相同就返回它(nonempty: '' 不算); 到点没读稳返回最后一个读数(一次都没读到 None)。"""
        start = time.time()
        last, streak, seen = None, 0, None
        while time.time() - start < cap:
            self.task.next_frame()
            g = self.bl_gua()
            if g is not None and (g or not nonempty):
                seen = g
                streak = streak + 1 if g == last else 1
                last = g
                if streak >= self.BL_GUA_CONFIRM:
                    return g
            self.macro_wait(0.02)
        return seen

    @staticmethod
    def bl_gua_plan(gua, got, heavies_left, fixes_left):
        """手上卦象 gua -> 凑出一阴一阳(连同已出的 got)最省的步骤: 'H' = 一段重击(吃最新两个, 同字少阴/异字少阳),
        'G' = 补艮, 'Z' = 补震。凑不出返回 None。"""
        best = None

        def search(state, have, seq, hl, fl):
            nonlocal best
            if {'阴', '阳'} <= have:
                cost = sum(1.0 if x == 'G' else 1.2 for x in seq if x != 'H')
                if best is None or cost < best[0]:
                    best = (cost, seq)
                return
            if hl and len(state) >= 2:
                kind = '阳' if state[-1] != state[-2] else '阴'
                search(state[:-2], have | {kind}, seq + ['H'], hl - 1, fl)
            if fl:
                for step, g in (('G', '艮'), ('Z', '震')):
                    search((state + g)[-4:], have, seq + [step], hl, fl - 1)

        search(gua, set(got), [], heavies_left, fixes_left)
        return None if best is None else best[1]

    def bl_heavy_gua(self, tag, before, cap):
        """按住左键, 卦象栏比按下时少两个(这一段第40F结算)连 BL_GUA_CONFIRM 帧就松手。返回 (出没出, 松手后的卦象)。
        cap 到点还没少: 松手后再读一会儿, 少了也算出(结算正好卡在上限那几帧)。按住期间只读画面, 不发任何键。"""
        con0 = self.bl_con()
        self.task.mouse_down()
        self.holding_attack = True
        down = time.time()
        self.macro_mark(f'{tag}_down')
        hits = 0
        cur = before
        trace = []
        try:
            while time.time() - down < cap:
                self.task.next_frame()
                g = self.bl_gua()
                if len(trace) < 45:
                    trace.append(f'{time.time() - down:.2f}:{g if g is not None else "?"}')
                if g is not None and len(g) <= len(before) - 2:
                    hits += 1
                    cur = g
                    if hits >= self.BL_GUA_CONFIRM:
                        break
                else:
                    hits = 0
                self.macro_wait(0.02)
        finally:
            self.release_attack()
        out = hits >= self.BL_GUA_CONFIRM
        if not out:
            g = self.bl_gua_settled(self.BL_HEAVY_VERIFY_CAP)
            if g is not None and len(g) <= len(before) - 2:
                out, cur = True, g
        self.macro_mark(f'{tag}_up({"出" if out else "没出"},{before}->{cur or "空"},协奏{con0:.2f}->{self.bl_con():.2f},'
                        f'{time.time() - down:.2f}s)')
        self.logger.info(f'{tag} 按住卦象 — {" ".join(trace)}')
        return out, cur

    def bl_gua_add(self, tag, step, before, cap):
        """补一个卦象: G = 点出 A1A2(A2 命中给艮), Z = 跳起来 A(下落落地命中给震)。
        卦象栏变了而且最新那个是要的字, 连 BL_GUA_CONFIRM 帧才算。返回 (成没成, 卦象)。"""
        want = '艮' if step == 'G' else '震'
        start = time.time()
        n = 0
        if step == 'Z':
            self.task.jump(after_sleep=0)
            self.macro_wait(self.BL_JUMP_TO_A)
            for i in range(self.BL_A_PRESSES):
                self.click()
                n += 1
                if i + 1 < self.BL_A_PRESSES:
                    self.macro_wait(self.BL_A_PRESS_GAP)
        next_click = 0.0
        hits = 0
        cur = before
        while time.time() - start < cap:
            now = time.time()
            if step == 'G' and now - start < self.BL1_G_CLICK_WINDOW and now >= next_click:
                self.click()
                n += 1
                next_click = now + self.BL1_A_EVERY
            self.task.next_frame()
            g = self.bl_gua()
            if g is not None and g != before and g.endswith(want):
                hits += 1
                cur = g
                if hits >= self.BL_GUA_CONFIRM:
                    break
            else:
                hits = 0
            self.macro_wait(0.02)
        ok = hits >= self.BL_GUA_CONFIRM
        self.macro_mark(f'{tag}({"成" if ok else "没成"},{before}->{cur or "空"},A x{n},{time.time() - start:.2f}s)')
        return ok, cur

    def bl_heavies_gua(self, tag):
        """两段强化重击按卦象栏走: 读全排 -> 凑一阴一阳最省的步骤 -> 做一步重读一次重排。

        返回 (结果, 已出的['阴'/'阳'...]): 结果 True = 一阴一阳都出了; False = 凑不出 / 哪一步没出;
        None = 卦象栏读不到。False / None 时调用方用看外圈那套(bl_heavy_pair)接着补, 已出的带过去。
        【不算协奏账】: 见 BL_GUA_REFS 上面那段(弗坎卜放完 R 本来就要补满协奏)。
        """
        start = time.time()
        gua = self.bl_gua_settled(self.BL_HEAVY_VERIFY_CAP, nonempty=True)
        if not gua:
            self.macro_mark(f'{tag}卦象栏读不到({gua!r})->看外圈')
            return None, []
        got = []
        heavies = fixes = 0
        last_heavy_up = 0.0
        while True:
            if {'阴', '阳'} <= set(got):
                self.macro_mark(f'{tag}两段重击(齐,{"+".join(got)},补{fixes}次,{time.time() - start:.2f}s)')
                return True, got
            plan = self.bl_gua_plan(gua, got, 2 - heavies, self.BL1_FIX_MAX - fixes)
            if plan is None:
                self.macro_mark(f'{tag}卦象{gua or "空"}凑不出(已出{"+".join(got) or "无"})->看外圈')
                return False, got
            self.macro_mark(f'{tag}卦象{gua}->{"".join(plan)}(协奏{self.bl_con():.2f})')
            step = plan[0]
            chained = bool(last_heavy_up)
            if chained:
                left = last_heavy_up + self.BL_HEAVY_NEXT_GAP - time.time()
                if left > 0:
                    self.macro_wait(left)
            if step == 'H':
                kind = '阳' if gua[-1] != gua[-2] else '阴'
                out, after = self.bl_heavy_gua(f'{tag}重击#{heavies + 1}({gua[-2:]}少{kind})', gua,
                                               self.BL_HEAVY_GUA_CAP[1 if chained else 0])
                heavies += 1
                if not out:
                    return False, got
                got.append(kind)
                last_heavy_up = time.time()
                gua = after or ''
            else:
                ok, after = self.bl_gua_add(f'{tag}补{"艮" if step == "G" else "震"}', step, gua, self.BL1_FIX_CAP[step])
                fixes += 1
                last_heavy_up = 0.0
                if not ok:
                    return False, got
                gua = after

    def bl_heavy_pair(self, tag, jump, min_settle, got=None):
        """强化重击蓝(少阴)黄(少阳)各出一段再返回; 返回凑齐没有。常量块里有整套规则。

        got: 卦象栏那套(bl_heavies_gua)已经出了的颜色, 接着补还差的。
        """
        start = time.time()
        got = list(got or [])
        tries = na = 0
        chained = False
        next_down_at = 0.0
        color = self.bl_ring_settled(self.BL_HEAVY_VERIFY_CAP)
        while len(got) < 2 and time.time() - start < self.BL_PAIR_CAP:
            if color in ('blue', 'yellow') and color not in got:
                left = next_down_at - time.time()
                if left > 0:
                    self.macro_wait(left)
                tries += 1
                cap = self.BL_HEAVY_CAP if chained else self.BL_HEAVY_FIRST_CAP
                jumped = self.bl_heavy_once(f'{tag}重击#{tries}({color})', cap, jump, min_settle)
                up_at = time.time()
                after = self.bl_ring_settled(self.BL_HEAVY_VERIFY_CAP)
                out = jumped or after not in (color, 'unknown')
                if out:
                    got.append(color)
                self.macro_mark(f'{tag}{"出" if out else "没出"}{color}(圈->{after})')
                # 读到结算: 20F 后接得上下一段; 没读到(没出 / 协奏满了读不出涨): 当成还有动作在演, 下一段用长上限
                chained = jumped
                next_down_at = up_at + self.BL_HEAVY_NEXT_GAP if jumped else 0.0
                color = after
                continue
            chained = False
            need = [c for c in ('blue', 'yellow') if c not in got]
            if need == ['blue']:
                # 只差蓝: 跳 A 下落补震。上一段重击结算后 20F 才接得上动作, 早跳会被吞
                left = next_down_at - time.time()
                if left > 0:
                    self.macro_wait(left)
                color = self.bl_plunge_for_blue(tag)
                continue
            # 圈不亮 / 只差黄: 连点 A 换卦象, 还差的颜色连读几帧亮就停手去按
            t0 = time.time()
            n = streak = 0
            seen = 'unknown'
            next_click = 0.0
            while time.time() - start < self.BL_PAIR_CAP:
                self.task.next_frame()
                now = time.time()
                c = self.bl_ring()[0] if self.task.in_team()[0] else 'unknown'
                if c in need:
                    streak = streak + 1 if c == seen else 1
                else:
                    streak = 0
                seen = c
                if streak >= self.BL_RING_CONFIRM:
                    break
                # 读到还差的颜色那一帧起就不点: 多点出去的普攻要演完, 重击压在它后面
                if streak == 0 and now >= next_click:
                    self.click()
                    n += 1
                    next_click = now + self.A_INTERVAL
                self.macro_wait(0.02)
            na += n
            color = seen if streak >= self.BL_RING_CONFIRM else 'unknown'
            self.macro_mark(f'{tag}A换卦象(A x{n},->{color},{time.time() - t0:.2f}s)')
        done = len(got) >= 2
        self.macro_mark(f'{tag}两段重击({"齐" if done else "CAP"},{"+".join(got) or "无"},按x{tries},A x{na},'
                        f'{time.time() - start:.2f}s)')
        if not done:
            self.logger.warning(f'{tag}: 卜灵两段重击 {self.BL_PAIR_CAP:.0f}s 没凑齐({got}), 照样 QR —— 这发 R 不开阵')
        return done

    def bl_ensure_r(self, bl, tag):
        """卜灵 R: R 和 A 错开帧一起连发, 队伍 HUD 连续消失 LIB_GONE_CONFIRM 帧 = 大招出来了。返回放出去没有。

        R 没转好的时候这段就在打怪攒能量, 转好的那一刻 R 打断普攻放出来; BL_R_CAP 封顶(打不到怪时防卡死)。
        这几下 A 攒出来的卦象由后面补协奏那段的长按重击清掉。
        """
        self.wait_hud_up(tag=f'{tag}R前HUD')
        start = time.time()
        self.lib_press_at = start
        nr = na = gone = 0
        next_r = next_a = 0.0
        fired = False
        while time.time() - start < self.BL_R_CAP:
            now = time.time()
            if now >= next_r:
                bl.send_liberation_key()
                nr += 1
                next_r = now + self.BL_R_KEY_INTERVAL
            elif now >= next_a:
                self.click()
                na += 1
                next_a = now + self.A_INTERVAL
            self.task.next_frame()
            if not self.task.in_team()[0]:
                gone += 1
                if gone >= self.LIB_GONE_CONFIRM:
                    fired = True
                    break
            else:
                gone = 0
            self.macro_wait(0.02)
        self.task.skip_combat_check = True
        if fired:
            bl.record_liberation_use()
            self.macro_mark(f'{tag}R_fired(R x{nr},A x{na},{time.time() - start:.2f}s)')
            return True
        self.macro_mark(f'{tag}R_NOFIRE(R x{nr},A x{na},{time.time() - start:.2f}s)')
        self.logger.warning(f'{tag}: 卜灵 R 边 A 边按了 {time.time() - start:.1f}s 没放出来, 不等了')
        return False

    def bl_fill_con(self, bl, tag, defer_on_full=False):
        """【没打满不许走】: 协奏没满就补 —— 重击提示连读几帧亮(手上两个卦象)长按放掉, 不亮就平 A。返回满了没有。

        放弃只有两个理由: 协奏 BL_CON_STALL 秒一点没涨(打不到怪, 再站也不会满), 或 BL_CON_CAP 兜底。
        协奏满要连着 INTRO_CON_FULL_CONFIRM 帧读到(一个假的满会把交棒提前)。
        """
        start = time.time()
        best = -1.0
        best_at = start
        hits = lit = na = nh = 0
        next_click = 0.0
        why = 'cap'
        samples = []
        while time.time() - start < self.BL_CON_CAP:
            self.task.next_frame()
            now = time.time()
            try:
                # 【0.99 哨兵】: 见 CON_SOFT_RATIO
                con = self.con_now()
            except Exception:
                con = 0.0
            if len(samples) < self.CON_SAMPLE_MAX:
                samples.append(f'{now - start:.2f}:{con:.2f}')
            hits = hits + 1 if con >= self.INTRO_CON_ENOUGH else 0
            if hits >= self.INTRO_CON_FULL_CONFIRM:
                why = 'full'
                break
            if con > best + self.BL_CON_STALL_EPS:
                best, best_at = con, now
            if now - best_at >= self.BL_CON_STALL:
                why = 'stall'
                break
            try:
                # 外圈黄蓝都算(补协奏不挑颜色); is_mouse_forte_full 在卜灵身上读不到东西
                # 差不到 10 只点 A: 见 BL_FILL_HEAVY_BELOW
                lit = lit + 1 if (self.task.in_team()[0] and self.bl_ring()[0]
                                  and con < self.BL_FILL_HEAVY_BELOW) else 0
            except Exception:
                lit = 0
            # defer_on_full(启动轴, 用户 2026-09-15: R 完切坎特蕾拉慢了): 这一帧协奏已经读到满就不按重击, 等连读确认。
            # 实机 10:12 / 10:19 启动轴 HUD 回来 0.05s 就按了一发 0.75s 补协奏重击, 0.8s 后才判满切人; 09:59 没按这发 0.10s 就切了。
            # 两段重击后协奏 0.78~0.89 + R 的 20, 放完基本就满。真没满读数在满线下面, 照样马上按
            if lit >= self.BL_FILL_LIT_CONFIRM and not (defer_on_full and hits > 0):
                lit = 0
                nh += 1
                self.bl_hold(self.BL_FILL_HEAVY_HOLD, f'{tag}补协奏重击#{nh}')
                continue
            if lit == 0 and now >= next_click:
                self.click()
                na += 1
                next_click = now + self.BL_FILL_A_INTERVAL
            self.macro_wait(0.02)
        self.macro_mark(f'{tag}补协奏({why},A x{na},重击x{nh},{time.time() - start:.2f}s)')
        if why != 'full':
            self.logger.warning(f'{tag}: 卜灵协奏没打满就走({why}) — {" ".join(samples)}')
        return why == 'full'

    def switch_to_buling(self, bl, tag, read_con, click_during):
        """切给卜灵, 没切过去就再试一次。返回场上是不是她。

        【TO_BL_TIME_OUT 比平时长】: 从坎特蕾拉的过门切出来时, 她 QTE 第80F前游戏拒绝切人,
        这 1.3 秒全算在切人耗时里。
        """
        for attempt in (1, 2):
            if self.quick_switch(bl, read_con=read_con, click_during=click_during,
                                 time_out=self.TO_BL_TIME_OUT):
                return True
            if self.cur is bl:
                return True
            self.logger.warning(f'{tag}: 第 {attempt} 次切卜灵没切过去'
                                f'(场上 {self.cur.name if self.cur else "?"})')
        return self.cur is bl

    def seg_can_pass(self, can, bl):
        """循环轴中间那次坎特蕾拉: 变奏入场【只为吃弗洛洛的延奏】, 到场马上切卜灵。返回切过去没有。

        (用户 2026-09-16: "中间那次变奏只是单纯变奏吃能量, 变奏了就马上切卜, 不进行任何操作")
        【不自己数入场锁】: quick_switch 一直重发数字键到换人生效 —— QTE 第80F前游戏拒绝切人,
        锁一过下一发就生效; 自己掐时间只会更晚。
        【一下都不点】(click_during=False): 锁一过要是先吃到一下普攻, 她起手 A1,
        切人得等 A1 演到能被打断, 白白晚一截。
        【读协奏】(read_con=True): 她刚到场协奏几乎是空的, 卜灵正常不带变奏、能跳;
        万一是满的, seg_buling 要先等 QTE 锁, 所以这一格得记准。
        """
        if not can.has_intro:
            self.logger.warning('cantarella(过门): 没拿到变奏 —— 弗洛洛协奏没满, '
                                '这一次延奏没吃到')
        self.macro_mark('坎过门')
        return self.switch_to_buling(bl, tag='坎过门', read_con=True, click_during=False)

    def bl_zhen_score(self):
        """画面下方正中那一排卦象里有没有"震": 返回模板匹配最高分(0~1); 拿不到画面返回 -1。

        白色笔画二值化之后匹配, 所以不吃地面颜色和特效颜色; 模板和横带都按画面高换算, 正中对齐。
        """
        try:
            import cv2
            import numpy as np
            frame = self.task.frame
            h, w = frame.shape[:2]
            k = h / 1440.0
            x0 = max(0, int(w / 2 + self.BL_GLYPH_X0 * h))
            x1 = min(w, int(w / 2 + self.BL_GLYPH_X1 * h))
            y0 = max(0, int(self.BL_GLYPH_Y0 * h))
            y1 = min(h, int(self.BL_GLYPH_Y1 * h))
            hsv = cv2.cvtColor(frame[y0:y1, x0:x1], cv2.COLOR_BGR2HSV)
            strokes = (((hsv[..., 2] >= 200) & (hsv[..., 1] <= 80)) * 255).astype(np.uint8)
            cache = getattr(self, '_bl_zhen_tpl', None)
            if cache is None or cache[0] != round(k, 4):
                import base64
                n = self.BL_GLYPH_TPL_SIZE
                raw = np.frombuffer(base64.b64decode(self.BL_GLYPH_ZHEN_B64), dtype=np.uint8)
                tpl = (np.unpackbits(raw)[:n * n].reshape(n, n) * 255).astype(np.uint8)
                size = max(8, int(round(n * k)))
                if size != n:
                    tpl = cv2.resize(tpl, (size, size), interpolation=cv2.INTER_NEAREST)
                cache = (round(k, 4), tpl)
                self._bl_zhen_tpl = cache
            tpl = cache[1]
            if strokes.shape[0] < tpl.shape[0] or strokes.shape[1] < tpl.shape[1]:
                return -1.0
            res = cv2.matchTemplate(strokes, tpl, cv2.TM_CCOEFF_NORMED)
            return float(np.nan_to_num(res).max())
        except Exception:
            return -1.0

    def bl_jump_plunge(self, bl, tag, tries):
        """跳 -> 空中 A(补按一下) -> 等落地。返回确认打中的方式('震' / '协奏' / '空中' / ''); tries<=1 不判, 返回 None。

        tries>1: 每一次都是完整的一套, 【不连按空格】(理由见 BL_INTRO_JUMP_AT 上面那段)。
        【跳成了没有看卦象栏】: 落地命中给震, 画面下方正中冒出第一个卦象(见 BL_GLYPH_ZHEN_MIN 上面那段);
        连 BL_GLYPH_CONFIRM 帧读到就算打中, 不再跳。协奏涨 BL_JUMP_CON_RISE、装了悬浮器时 flying() 也算, 当兜底。
        【跳之前带里已经有震】: 分不出这一套, 只跳一套(多跳比少跳糟, 用户明说过"跳了两次")。
        """
        glyph0 = self.bl_zhen_score() if tries > 1 else -1.0
        if tries > 1 and glyph0 >= self.BL_GLYPH_ZHEN_MIN:
            self.macro_mark(f'{tag}卦象栏已有震({glyph0:.2f}),只跳一套')
            tries = 1
        use_glyph = 0 <= glyph0 < self.BL_GLYPH_ZHEN_MIN
        for n in range(1, max(1, tries) + 1):
            con0 = self.bl_con()
            self.task.jump(after_sleep=0)
            self.macro_mark(f'{tag}跳' if n == 1 else f'{tag}跳#{n}')
            self.macro_wait(self.BL_JUMP_TO_A)
            for i in range(self.BL_A_PRESSES):
                self.click()
                if i + 1 < self.BL_A_PRESSES:
                    self.macro_wait(self.BL_A_PRESS_GAP)
            self.macro_mark(f'{tag}跳A' if n == 1 else f'{tag}跳A#{n}')
            if tries <= 1:
                self.macro_wait(self.BL_PLUNGE_TO_A)
                return None
            start = time.time()
            cap = self.BL_PLUNGE_TO_A + self.BL_JUMP_GLYPH_READ
            got = ''
            seen_air = False
            con = con0
            ghits = 0
            gbest = -1.0
            while time.time() - start < cap:
                self.task.next_frame()
                if use_glyph:
                    g = self.bl_zhen_score()
                    gbest = max(gbest, g)
                    ghits = ghits + 1 if g >= self.BL_GLYPH_ZHEN_MIN else 0
                    if ghits >= self.BL_GLYPH_CONFIRM:
                        got = '震'
                        break
                con = self.bl_con()
                if con0 >= 0 and con >= 0 and con - con0 >= self.BL_JUMP_CON_RISE:
                    got = '协奏'
                    break
                if self.task.has_lavitator:
                    try:
                        seen_air = seen_air or bool(bl.flying())
                    except Exception:
                        pass
                # 读到过在空中: 等满下落时长(落地)再走, 别在空中就开始落地连点
                if seen_air and time.time() - start >= self.BL_PLUNGE_TO_A:
                    got = '空中'
                    break
                self.macro_wait(0.03)
            self.macro_mark(f'{tag}落地判(#{n},{got or "没打中"},震分{gbest:.2f},'
                            f'协奏{con0:.2f}->{con:.2f},{time.time() - start:.2f}s)')
            if got:
                return got
        self.logger.info(f'{tag}: 跳A {tries} 套都没确认下落攻击打中 —— 照样往下走'
                         f'(卦象栏一直没冒出震: 要么真没跳起来, 要么落地没打到怪)')
        return ''

    def seg_buling(self, bl, can, opener, tag):
        """卜灵一整格 -> 变奏坎特蕾拉。返回切过去没有。

        【启动轴、循环轴都走跳A 那套】(用户 2026-09-16: "卜灵的启动轴的代码也就是跳A+A+E...
        那段流程替换掉莫宁, 不管是启动轴还是循环轴"):
          跳 -> A(空中攻击下落, 落地命中给震) -> 落地连点到 A3 窗口(A2 命中给艮)
          -> E(+震) -> A4 等外圈转蓝(震震) -> 两段强化重击(蓝黄各一, 阴阳相生)
          -> Q -> R -> 打满协奏 -> 变奏坎特蕾拉。
        整段照搬露丽卜(Douling__Lucy__Rebecca/Lucy.py)启动轴卜灵的定稿, 数值都没动。
        循环轴专用的 L_BL_* 目前跟启动轴同值, 拆开只是为了以后单调一条轴时不连累另一条。

        【带变奏进来就先等 QTE 输入锁】(has_intro): 启动轴弗洛洛大招演完协奏基本是满的,
        卜灵多半带变奏进来 —— 露丽卜实机"变奏入场跳不起来", 所以先按到场时刻等满
        BL_INTRO_ANIM 再跳。【这一格没实机过】: 要是还跳不起来, timeline 里 跳A 之后
        落地连点出不了符, 两段重击会一直等不到蓝圈。
        循环轴卜灵是从坎特蕾拉的过门切过来的(她刚到场协奏是空的), 正常不带变奏。
        """
        self.poking = False
        marks = len(self.macro_marks)
        tries = self.BL_JUMP_TRIES if opener else self.L_BL_JUMP_TRIES
        if bl.has_intro:
            arrived = getattr(bl, 'last_switch_in_time', 0.0) or 0.0
            # 多试几次的那条(启动轴)等 QTE 演完再跳; 只跳一次的那条(循环轴)保持原来的 70F 输入锁 + settle
            lock = self.BL_INTRO_JUMP_AT if tries > 1 else self.BL_INTRO_ANIM
            left = arrived + lock - time.time()
            if 0 < left <= lock:
                self.macro_wait(left)
            self.macro_mark(f'{tag}变奏锁')
            if tries <= 1:
                self.macro_wait(self.BL_OPENER_SETTLE)
        else:
            self.macro_wait(self.BL_OPENER_SETTLE)
        # ---- 跳 -> A(空中攻击下落, 落地命中给震) -> 落地连点 ----
        self.bl_jump_plunge(bl, tag, tries)
        # 落地后连点: A2 命中出符(艮)
        self.macro_spam(self.BL_LAND_A_WINDOW, self.A_INTERVAL, tag=f'{tag}落地A到A3')
        # ---- E(+震) -> A4(由E派生, +震) ----
        if not self.press_res_until_cd(bl, self.BL_E_CAP, tag=f'{tag}E', poke=False):
            self.logger.info(f'{tag}: 卜灵 E 没判到进 CD —— 真没放出去的话少一个震')
        bl.record_resonance_use()
        self.macro_wait(self.BL_E_TO_A)
        # A4 打中外圈转蓝(最新两个是震震)就停手; E 刚出手那会儿的黄圈(艮震)不算。
        # 先看卦象栏: A4 的震一冒出来就停(见 BL1_A_EVERY 上面那段), 读不到才等外圈
        self.task.next_frame()
        gua0 = self.bl_gua()
        if opener:
            self.bl_a4_until_blue(tag, self.BL_A4_MAX_CLICKS, self.BL_BLUE_CAP, gua_before=gua0)
        else:
            self.bl_a4_until_blue(tag, self.L_BL_A4_MAX_CLICKS, self.L_BL_BLUE_CAP,
                                  self.L_BL_A4_MIN_BLUE, gua_before=gua0)
        # ---- 两段强化重击: 蓝(少阴)黄(少阳)各一段都出去才 QR, 阴阳相生凑齐大招才开阵 ----
        # 先按卦象栏走(按到卦象被吃掉两个就松); 读不到 / 走到一半不对, 看外圈那套接着补, 已出的带过去
        done, kinds = self.bl_heavies_gua(tag)
        if done is not True:
            got = ['blue' if k == '阴' else 'yellow' for k in kinds]
            if opener:
                self.bl_heavy_pair(tag, self.BL_HEAVY_CON_JUMP, self.BL_HEAVY_MIN_SETTLE, got=got)
            else:
                self.bl_heavy_pair(tag, self.L_BL_HEAVY_CON_JUMP, self.L_BL_HEAVY_MIN_SETTLE, got=got)
        # ---- Q -> R(阴阳相生 => 强化伤害 + 开阵) ----
        self.macro_wait(self.BL_HEAVY_TO_Q)
        q_sent = [0]

        def q_done():
            q_sent[0] += 1
            return q_sent[0] >= 2 and not bl.echo_available()

        self.spam_key(bl.send_echo_key, self.BL_Q_WINDOW, interval=self.BL_Q_INTERVAL,
                      tag=f'{tag}Q', poke=False, stop_when=q_done)
        bl.record_echo_use()
        self.macro_wait(self.BL_Q_TO_R)
        if self.bl_ensure_r(bl, tag):
            self.poke_until_hud_back(tag=f'{tag}R演出', tail=0.0)
        defer = self.BL_FILL_DEFER if opener else self.L_BL_FILL_DEFER
        full = self.bl_fill_con(bl, tag, defer_on_full=defer)
        self.warn_no_con(full, '卜', '坎')
        ok = self.quick_switch(can, assume_con=full, click_during=True)
        # 单独打一行: 整圈的时间轴要跑完一圈才打, 中途停掉就看不到卜灵这段
        self.logger.info(f'{tag} timeline: {self.macro_timeline(marks)}')
        return ok

    # ==================== 坎特蕾拉段(启动/循环共用) ====================

    def seg_cantarella(self, can):
        """变奏 -> E -> R 打断 -> 演出里预输入重击 -> 强化状态 e/aaa/强化e -> 声骸 -> 变奏弗。

        【这一段的核心是那个"预输入重击"】: 大招演出结束的第一帧接上重击·浮潜幻海,
        才能无缝进 8 秒强化状态(帧表 ID=6 第22F)。强化状态下平A 变成强化A1/A2/A3,
        每一下吃一格回路 —— 这一整段的伤害都靠它。做法见 hold_through_lib。

        【R 为什么要打断 E 的收招】: E1-翩跹1 第14F 就给核心(帧表 ID=15),
        后面那段收招没有伤害, R 打断它纯赚。文字轴写的"看到涨一格回路后开大"
        说的就是这个时刻 —— 固定 0.25 秒等于读那一格, 而且比读屏更稳
        (那条回路条是 4 段小格, 框架里没有现成的"涨了一格"判据)。
        """
        # 【变奏入场这一段不许出手】: QTE 第76F前不响应输入。
        # 【没拿到变奏就别等这一段】: 上一格协奏没满时 handoff 把 has_intro 记成 False,
        # 那这次进场就没有 QTE 的输入锁, 白站 1.1 秒还会把后面整段推歪
        if can.has_intro:
            self.poll_wait(self.CAN_INTRO_LOCK, tag='坎入场锁')
        else:
            self.logger.warning('cantarella: came in WITHOUT an intro — 上一格协奏没满, '
                                '跳过入场锁直接开打')
            self.macro_gap(self.O_ENTER_SETTLE, tag='坎A')
        # 【发到确认出手为止】: 见 CAN_E1_CAP。没确认的话下一段没法判断
        # 普通E 到底在不在 CD 上
        self.press_e_until_fired(can, cap=self.CAN_E1_CAP, tag='坎E')
        self.macro_wait(self.CAN_E_TO_LIB)
        # 【长窗口 + 重试】: 理由见 CAN_LIB_WINDOW。放出去就立刻返回, 长窗口不花钱
        fired = False
        for attempt in range(1, self.CAN_LIB_TRIES + 1):
            if self.fire_lib(can, tag='R坎大招' if attempt == 1 else f'R坎大招{attempt}',
                             window=self.CAN_LIB_WINDOW, poke=True,
                             click_interval=self.A_INTERVAL):
                fired = True
                break
            if attempt < self.CAN_LIB_TRIES:
                # 边打边读【能量占比】, 够了当场退出去再发一次。
                # 【日志能分清两种失败】: "不够0.05" = 真的没能量(往上游查这一圈丢了
                # 什么回能, 比如强化E 的 大招回收10.55); "满0.17" = 能量够, 是键被
                # 动画吞了(那就调 CAN_LIB_WINDOW)
                self.wait_lib_energy(can, self.CAN_LIB_READY_PCT,
                                     cap=self.CAN_LIB_RETRY_A,
                                     confirm=self.CAN_LIB_CONFIRM,
                                     tag=f'坎能量{attempt}')
        if fired:
            # 【大招演出期间只连点, 不按住】: 按住的话重击会在大招演完那一刻就出手,
            # 8 秒强化状态从那时候开始烧, 紧接着的处决演出把它吃掉一大截
            # (用户 2026-08-31: "处决后没变身, 应该在处决的时候开始预输入重击")
            self.poke_until_hud_back(tag='坎大招Anim',
                                     time_out=self.CAN_LIB_ANIM + 3, tail=0.0)
            # 【处决演出一开始才按住左键预输入重击】, 让重击落在处决【之后】。
            # 【CAN_TAIL_HOLD 打开时这里【不松手】】—— 一路按到切人, 见那个常量
            self.f_break_then_hold(tag='坎处决', keep_held=self.CAN_TAIL_HOLD)
            # 【重击就在这一刻出手, 8 秒从这里开始烧】: 下面等 E 的 CD 要拿它算账
            self.can_buff_at = time.time()
        else:
            # 【大招丢了也要把强化状态拿到】: 8 秒强化状态是【重击·浮潜幻海】给的
            # (帧表 ID=6 第22F), 跟大招无关 —— 平时它是靠"演出期间预输入"接上的,
            # 没有演出就自己长按一次。不补的话这一整段的强化A 全没了
            self.logger.warning('cantarella liberation never started after '
                                f'{self.CAN_LIB_TRIES} tries — 这一圈的大招丢了; '
                                '自己长按一次补上 8 秒强化状态')
            if self.CAN_TAIL_HOLD:
                # 【按住之后不松手】: 跟上面那条路径保持一致, 一路按到切人
                self.task.mouse_down()
                self.holding_attack = True
                self.macro_mark('坎补重击_down')
                self.macro_wait(self.CAN_FALLBACK_HOLD)
                self.can_buff_at = time.time()
            else:
                self.macro_hold_attack(self.CAN_FALLBACK_HOLD, tag='坎补重击')
                self.can_buff_at = time.time()

        # ---- 强化状态: 【CD 转好点普通E, 环亮点强化E】----: 见 can_ea_phase
        # 【这里换掉了原来那套"先赌普通E、再等强化E"】(用户 2026-09-01:
        # "应该靠检测来, 不是靠运气")。原来的零件都还在(wait_e_cd_or_ring /
        # spam_ae / ee_ring_probe), 只是不在这条路上了
        self.macro_wait(self.CAN_HEAVY_TO_E)
        # 【按住模式下全程不点普攻】: poking 关掉
        self.poking = not self.CAN_TAIL_HOLD
        a_step = 0 if self.CAN_TAIL_HOLD else self.CAN_AE_A_INTERVAL
        ee_done, e2_fired = self.can_ea_phase(can)
        if self.CAN_EE_RECHECK and self.can_ee_recheck(can):
            ee_done = True
        # ---- 声骸打断强化E 的后摇, 再闪避取消声骸 ----
        # 【她的声骸是变身型、动画很长】(用户 2026-08-31: "Q了最好再闪避一下取消一下Q"),
        # 不取消就要站着把变身演完
        # 【进门读几次 CD 取最大当基线】: 理由见 CAN_Q_CD_RISE / CAN_Q_CD_PROBES
        q_cd0 = self.cd_baseline('echo', probes=self.CAN_Q_CD_PROBES)
        # 还挂着 CD 的话, 窗口要覆盖到它转好之后
        q_cap = self.CAN_Q_SPAM
        if q_cd0 > 0:
            q_cap = min(self.CAN_Q_MAX_WAIT,
                        max(self.CAN_Q_SPAM, q_cd0 + self.CAN_Q_CD_EXTRA))

        q_hits = [0]

        def q_fired():
            self.task.next_frame()
            try:
                up = float(self.task.get_cd('echo')) > q_cd0 + self.CAN_Q_CD_RISE
            except Exception:
                up = False
            # 【连着读到才认】: 单帧 OCR 有把数字认到隔壁格的时候, 那会读出一个
            # 凭空的高值。清零而不是衰减, 是因为那种误读不会连着出现
            q_hits[0] = q_hits[0] + 1 if up else 0
            return q_hits[0] >= self.CAN_Q_FIRED_CONFIRM

        self.spam_key(can.send_echo_key, q_cap,
                      interval=self.CAN_Q_INTERVAL,
                      tag=f'Q坎声骸(基线{q_cd0:.1f})',
                      poke=not self.CAN_TAIL_HOLD, stop_when=q_fired)
        can.record_echo_use()
        # 【协奏确认满了就按"带变奏"交棒】: 见 CAN_LEAVE_TOPUP_CON
        con_full_known = False
        if self.CAN_LEAVE_ON_Q:
            # 【实验档: Q 一进 CD 就走】—— 闪避和等充能都跳过, 理由见 CAN_LEAVE_ON_Q
            con_now = self.can_con_now(can)
            if not self.CAN_LEAVE_TOPUP_CON:
                self.macro_mark(f'坎QCD即走(协奏{con_now:.2f})')
            elif con_now >= self.CON_ENOUGH:
                con_full_known = True
                self.macro_mark(f'坎QCD即走(协奏{con_now:.2f})')
            else:
                # 【协奏没满: 取消变身 -> 连点补满】, 理由见 CAN_LEAVE_TOPUP_CON
                self.macro_mark(f'坎QCD协奏{con_now:.2f}不满,补')
                self.macro_gap(self.CAN_Q_TO_DODGE, tag='坎A')
                self.spam_key(lambda: self.task.send_key(
                    self.task.key_config.get('Dodge Key'), after_sleep=0),
                    self.CAN_Q_DODGE_PRESSES * self.CAN_Q_DODGE_INTERVAL,
                    interval=self.CAN_Q_DODGE_INTERVAL,
                    presses=self.CAN_Q_DODGE_PRESSES, tag='坎闪避取消Q', poke=False)
                # 【松手再连点】: 连点是按下+抬起, 按住的那只手不松会被第一下点击松掉, 不如自己先松
                if self.holding_attack:
                    self.release_attack()
                    self.macro_mark('坎松手(补协奏)')
                con_full_known = self.wait_con_for_intro(can, 'Phrolova', poke=True,
                                                         time_out=self.CAN_TAIL_CON_CAP,
                                                         stall_give_up=self.CAN_TAIL_CON_STALL)
        else:
            self._can_tail_after_q(can, a_step)
        # ---- 变奏弗洛洛, 交回循环入口 ----
        # 【一路按住的那只手在这里松】(用户 2026-09-01: "一直持续到切人位置")。
        # 【松在切人之前】: 长按会跨过换人边界继续按在下一个角色身上, 而弗洛洛那一段
        # 开头是"变奏入场锁 + 连点攒乐声", 手一直按着的话她起手就变成蓄力重击
        if self.holding_attack:
            self.release_attack()
            self.macro_mark('坎松手')
        # 【交棒那一刻的充能读数】: 这一行是"Q就走够不够"的唯一依据
        try:
            self.macro_mark(f'坎充能({self.lib_ring_pct(can)*100:.0f}%,'
                            f'格{self.lib_ring_cell(self.RING_HALF_ANGLE):.2f})')
        except Exception:
            pass
        # 【协奏交给 quick_switch 顺带读】: 它是先发数字键再读协奏的, 那次读屏
        # 藏在切人耗时里。没满的话下面会打 warning, 而 seg_phrolova 有 has_intro 兜底
        # 【上面已经确认满了就按"带变奏"记, 不再重读】: 理由见 CAN_LEAVE_TOPUP_CON
        self.quick_switch(self, read_con=not con_full_known, assume_con=con_full_known,
                          click_during=not self.CAN_TAIL_HOLD)
        if not self.has_intro:
            self.logger.warning(
                'cantarella -> phrolova 没拿到变奏(交棒时协奏没满), 弗洛洛这一圈会走'
                '"手动切人"那一档。往上游查: 强化E 放出去没有(看 坎强化E 那一行)、'
                '强化A 有没有打空')
        self.poking = False

    def can_ee_lit(self, can):
        """坎特蕾拉强化E 的环亮没亮: 返回 (亮没亮, 洋红占比)。判据见 CAN_EE_MAGENTA; 框跟 ee_ring_pct 同一个。"""
        try:
            box = self.task.get_box_by_name('box_resonance').scale(
                self.CAN_EE_RING_W, self.CAN_EE_RING_H)
            flash = float(self.task.calculate_color_percentage(self.CAN_EE_RING_COLOR, box))
            ring = float(self.task.calculate_color_percentage(self.CAN_EE_MAGENTA, box))
        except Exception:
            return False, 0.0
        lo, hi = self.CAN_EE_MAGENTA_FILL
        return (flash >= self.CAN_EE_RING_FILL or lo <= ring <= hi), ring

    def can_press_ee(self, can, tag='坎强化E'):
        """连发 E 直到粉环灭(强化E 放出去了)。返回放出去没有; 没按掉记一笔。

        【判据是"亮过又灭了"】: 进来之前调用方已经连着读到亮; 这里连着 CAN_EE_GONE 次读到不亮才算出去。
        【方向是安全的】: 环亮着时 E 就是强化E, 多发几下落在 CD 上是空操作
        """
        ee = {'n': 0}

        def ee_gone():
            self.task.next_frame()
            if self.can_ee_lit(can)[0]:
                ee['n'] = 0
                return False
            ee['n'] += 1
            return ee['n'] >= self.CAN_EE_GONE

        self.spam_key(can.send_resonance_key, self.CAN_EE_PRESS_CAP,
                      interval=self.CAN_EE_PRESS_INTERVAL, tag=tag,
                      poke=not self.CAN_TAIL_HOLD, stop_when=ee_gone)
        done = ee['n'] >= self.CAN_EE_GONE
        if not done:
            self.macro_mark(f'{tag}(亮着没按掉)')
        return done

    def can_ee_recheck(self, can):
        """放 Q 之前: 环连着亮就补按强化E。见 CAN_EE_RECHECK。返回补按出去没有(没亮返回 False)。"""
        best = 0.0
        for _ in range(self.CAN_EA_LIT_CONFIRM):
            self.task.next_frame()
            lit, v = self.can_ee_lit(can)
            if not lit:
                return False
            best = max(best, v)
        self.macro_mark(f'坎环还亮着({best:.3f}),补按')
        return self.can_press_ee(can, tag='坎强化E补按')

    def can_ea_phase(self, can):
        """坎重击变身之后: 【CD 转好就点普通E, 环亮就点强化E】。

        返回 (强化E出了没, 普通E出了没)。

        【为什么合成一个循环】: 这两件事的到来顺序是【不确定的】—— 取决于段首那发
        普通E 有没有成功。分成两段顺序等的话, 先等错了那一个就把另一个的窗口耗掉了
        (实机塌过: 等 E 的 CD 等掉 4.3 秒, 强化E 的 8 秒窗口只剩 1.9 秒)。
        【环那一条优先】: 强化E 是这一段的产出, 普通E 只是顺手; 环的窗口又短
        (0.4~1.1 秒), 错过就得等下一次
        """
        start = time.time()
        deadline = start + self.CAN_EA_CAP
        if self.can_buff_at:
            # 【强化状态到头就没意义了】: 环只在这 8 秒里会亮
            deadline = min(deadline,
                           self.can_buff_at + self.CAN_BUFF_SECS)
        ee_done = False
        e_done = False
        which = 0
        nread = 0
        best = 0.0
        lit_n = 0
        while time.time() < deadline and not ee_done:
            self.task.next_frame()
            nread += 1
            which += 1
            # ---- 环亮了 -> 按到环灭 ----: 判据见 CAN_EE_MAGENTA; best 记的是洋红占比
            lit, v = self.can_ee_lit(can)
            if v > best:
                best = v
            # 【连着亮才认】: 见 CAN_EA_LIT_CONFIRM
            lit_n = lit_n + 1 if lit else 0
            if lit_n >= self.CAN_EA_LIT_CONFIRM:
                lit_n = 0
                ee_done = self.can_press_ee(can, tag='坎强化E')
                continue
            # ---- CD 转好了 -> 点普通E ----
            # 【隔一次读一次】: OCR 比取色贵得多, 每帧都读会把环的窗口错过
            if not e_done and which % 2 == 0:
                try:
                    cd = float(self.task.get_cd('resonance'))
                except Exception:
                    cd = 1.0
                if cd <= 0:
                    e_done = self.press_e_until_fired(
                        can, self.CAN_EA_E_CAP, tag='坎E')
                    if not e_done:
                        # 【没确认也别再试】: 再试一轮只会继续吃强化状态的时间
                        e_done = True
                        self.macro_mark('坎E(没确认,不再试)')
                    continue
            self.macro_wait(self.CAN_EA_READ)
        self.macro_mark(f'坎变身段(强化E{"出" if ee_done else "没出"},'
                        f'普通E{"出" if e_done else "没"},环最高{best:.3f},'
                        f'读x{nread},{time.time() - start:.2f}s)')
        if not ee_done:
            self.logger.warning(
                f'cantarella: 强化状态那 {self.CAN_BUFF_SECS:.0f} 秒里没把强化E 打出去 '
                f'(环最高 {best:.3f} / 门槛 {self.CAN_EE_RING_FILL:.3f})。'
                f'【环一直是 0.00x】= 回路根本没攒满, 往上游查处决/重击是不是空了; '
                f'【环亮过但没按掉】= 按键被吞, 看 坎强化E 那一行')
        return ee_done, e_done

    def can_con_now(self, can, reads=2):
        """坎特蕾拉此刻的协奏读数: 读几帧取最大, 读失败算 0。读到满就不再读。"""
        best = 0.0
        for _ in range(max(1, reads)):
            self.task.next_frame()
            try:
                best = max(best, float(can.get_current_con()))
            except Exception:
                pass
            if best >= self.CON_ENOUGH:
                break
        return best

    def _can_tail_after_q(self, can, a_step):
        """坎特蕾拉放完声骸之后的收尾: 闪避取消声骸 -> 打到 R 充能过半。

        【CAN_LEAVE_ON_Q 打开时整段跳过】(那一档是"Q 一进 CD 就交棒")。
        拆成单独一个方法, 是为了让 seg_cantarella 里那两档一眼看得出差别。
        """
        # 【进CD 了就立刻闪避, 不再等】: 见 CAN_Q_DODGE_PRESSES 上面那段
        self.macro_gap(self.CAN_Q_TO_DODGE, tag='坎A')
        self.spam_key(lambda: self.task.send_key(
            self.task.key_config.get('Dodge Key'), after_sleep=0),
            self.CAN_Q_DODGE_PRESSES * self.CAN_Q_DODGE_INTERVAL,
            interval=self.CAN_Q_DODGE_INTERVAL,
            presses=self.CAN_Q_DODGE_PRESSES, tag='坎闪避取消Q', poke=False)
        self.macro_gap(self.CAN_Q_TO_INTRO, tag='坎A')
        # ---- 继续 A/E 连发, 【只等 R 的充能过半】-> 交棒 ----
        # (用户 2026-08-31: "现在主要就看R的能量, 回路那里可以不看")
        #
        # 【回路那条判据撤了】。它本身很脆: 回路指示【打空之后还会重新长起来】
        # (录像 79.55 暗 -> 82.20 又亮了, 普攻在回充回路), 写成"此刻是暗的"就可能
        # 永远等不到 —— 于是卡死在回路这一格, 反而把"充能过半"这件事挡在后面
        # (用户实机: "R的能量已经过半但是没有马上切人")。
        # 【为什么充能这条更可靠】: 它是【单调上涨】的, 涨过就不会掉回去,
        # 不存在"错过窗口"这种事。
        # 【想把回路那条加回来】: 判据代码还在(wait_forte_spent), 但记得它要锁存,
        # 不能写成瞬时条件。
        # 【热路径只读一个方块】: 理由见 RING_HALF_ANGLE / lib_ring_half
        half = {'n': 0}

        def ring_ok():
            half['n'] = half['n'] + 1 if self.lib_ring_half(can) else 0
            return half['n'] >= self.RING_HALF_CONFIRM

        got = self.spam_ae(can, cap=self.CAN_RING_CAP, stop=ring_ok,
                           a_interval=a_step,
                           e_interval=self.CAN_AE_E_INTERVAL, tag='坎AE等充能')
        # 【百分比只在这里读一次】: 给日志用, 不进热路径
        try:
            pct = self.lib_ring_pct(can)
        except Exception:
            pct = 0.0
        if not got:
            self.logger.warning(
                f'cantarella: R 充能只到 {pct*100:.0f}% '
                f'(要 {self.CAN_RING_MIN*100:.0f}%), 到上限照样往下走 —— '
                f'下一圈她的大招可能开不出来。'
                f'【读数一直是 0 的话是配色对不上】, 拿 ring_probe.py.tool 重标 RING_COLOR')

    # ==================== 启动轴 ====================

    def perform_opener(self, entry_char=None):
        """启动轴: 弗洛洛段 -> 切卜灵 -> 卜灵段 -> 变奏坎特蕾拉 -> 坎段 -> 变奏弗洛洛(进循环)。

        (用户 2026-09-16: 砍掉莫宁开头那一套, 直接弗洛洛起手; 启动轴 弗 -> 卜 -> 坎)

        Args:
            entry_char: 调用方自己 —— 框架就是因为他在场才调的 do_perform,
                所以这是"现在场上是谁"最便宜也最可靠的答案。
                【不能让它去读屏判断】: in_team() 在战斗开局的头 0.8 秒会说谎
                (队伍 HUD 还在渐入, 三个槽位的文本不是同时出现的)。
        """
        can = self.teammate('Cantarella')
        bl = self.teammate('Douling')
        if can is None or bl is None:
            return False

        # 整段关掉脱战判定: 高频切人时 HUD 反复消失(大招演出), 战斗判定线程一误报
        # 就抛 NotInCombatException, 宏从中间断掉比打歪严重得多
        previous = getattr(self.task, 'skip_combat_check', False)
        self.task.skip_combat_check = True
        self.cur = entry_char or self.on_field_char() or self
        self.poking = False
        try:
            self.macro_start()
            # 【处决全程由宏自己按】: 留着框架的自动 F 会在切人时插一发,
            # 而击破动画带全局时停 + HUD 消失, 正好把切人循环判成脱战
            for c in (self, can, bl):
                c.check_f_on_switch = False

            # ===== 1. 弗洛洛 =====
            # 开局在场的不是她(框架先选了别人)就先切过来。刚开局谁的协奏都是空的,
            # 这一次不是变奏, seg_phrolova 走手动切人那一档
            if self.cur is not self:
                self.quick_switch(self, click_during=False)
            marks = len(self.macro_marks)
            self.seg_phrolova(opener=True)
            self.logger.info(f'opener 弗: {self.macro_timeline(marks)}')

            # ===== 2. 切卜灵 =====
            # 【读协奏】: 大招演完协奏基本是满的, 卜灵多半是带变奏进来的 ——
            # seg_buling 要据此先等 QTE 输入锁, 所以这一格得记准
            self.switch_to_buling(bl, tag='op', read_con=True, click_during=True)
            self.poking = False
            self.seg_buling(bl, can, opener=True, tag='op卜')

            # ===== 3. 坎特蕾拉(结尾变奏弗洛洛, 下一次 do_perform 就进循环轴) =====
            marks = len(self.macro_marks)
            self.seg_cantarella(can)
            self.logger.info(f'opener 坎: {self.macro_timeline(marks)}')
            self.logger.info(
                f'opener total {self.time_elapsed_accounting_for_freeze(self.macro_t0):.2f}s '
                f'(wall {time.time() - self.macro_t0:.2f}s)')
        except Exception as e:
            # 【中途挂掉也要把时间轴打出来】: 只在跑完才打印的话, 脱战抛异常时
            # 日志里什么都看不到, 分不清是没跑到还是跑了没生效
            self.logger.warning(f'opener aborted ({type(e).__name__}: {e}) at: '
                                f'{self.macro_timeline()}')
            raise
        finally:
            # 长按跨了好几个方法, 中途抛异常的话鼠标会一直按着, 下一个角色上场就是
            # 一直按住普攻。这里是唯一保证松手的地方
            self.release_attack()
            self.poking = False
            self.task.skip_combat_check = previous
        return True

    # ==================== 循环轴 ====================

    def perform_loop(self, entry_char=None):
        """循环轴: 弗洛洛段 -> 变奏坎(过门, 到场马上切) -> 卜灵段 -> 变奏坎 -> 坎段 -> 变奏弗洛洛。

        (用户 2026-09-16: 循环轴 弗 -> 坎 -> 卜 -> 坎, 坎特蕾拉一圈吃两次延奏;
         "中间那次变奏只是单纯变奏吃能量, 变奏了就马上切卜, 不进行任何操作")
        入口是弗洛洛(上一圈结尾把她变奏出来), 由她自己的 do_perform 调进来。
        """
        can = self.teammate('Cantarella')
        bl = self.teammate('Douling')
        if can is None or bl is None:
            return False

        previous = getattr(self.task, 'skip_combat_check', False)
        self.task.skip_combat_check = True
        self.cur = entry_char or self
        self.poking = False
        try:
            self.macro_start()
            for c in (self, can, bl):
                c.check_f_on_switch = False

            self.seg_phrolova(opener=False)
            self.logger.info(f'loop 弗: {self.macro_timeline()}')

            # ===== 变奏坎特蕾拉: 只吃延奏, 到场马上切卜灵 =====
            marks = len(self.macro_marks)
            # 【协奏交给 quick_switch 顺带读】: 先发数字键再读, 那次读屏藏在切人耗时里
            self.quick_switch(can, read_con=True, click_during=True)
            self.poking = False
            self.seg_can_pass(can, bl)
            self.logger.info(f'loop 坎过门: {self.macro_timeline(marks)}')

            self.seg_buling(bl, can, opener=False, tag='L卜')

            marks = len(self.macro_marks)
            self.seg_cantarella(can)
            self.logger.info(f'loop 坎: {self.macro_timeline(marks)}')
            self.logger.info(
                f'loop total {self.time_elapsed_accounting_for_freeze(self.macro_t0):.2f}s '
                f'(wall {time.time() - self.macro_t0:.2f}s)')
        except Exception as e:
            self.logger.warning(f'loop aborted ({type(e).__name__}: {e}) at: '
                                f'{self.macro_timeline()}')
            raise
        finally:
            self.release_attack()
            self.poking = False
            self.task.skip_combat_check = previous
        return True

    # ==================== 框架接口 ====================

    def do_perform(self):
        """弗洛洛在场时框架会调这里 —— 【启动轴和循环轴都由她起跑】。

        启动轴: 开局第一段就是她的强化普攻循环(用户 2026-09-16: 直接弗洛洛起手)。
        循环轴: 上一圈的结尾是"变奏弗洛洛", 所以框架下一次调 do_perform 就是她。
        """
        if not self.is_in_phro_cycle:
            return super().do_perform()
        # 处决全程由宏自己按, 理由见 perform_opener
        self.check_f_on_switch = False
        blocked = self.opener_blocked_by()
        if blocked is None:
            # 【标记要在跑之前落】: perform_opener 中途抛异常(脱战/任务被停)也不能
            # 让启动轴重跑 —— reset_state 会把 armed 重新置回来
            self.opener_armed = False
            self.last_opener = time.time()
            if self.perform_opener(self):
                return
            self.logger.warning('phrolova opener aborted, falling back to the native rotation')
            return super().do_perform()

        # 【把自己传进去】: 框架是因为弗洛洛在场才调的这个 do_perform, 所以这就是
        # "现在场上是谁"最可靠的答案
        if self.perform_loop(self):
            return
        self.logger.warning('phrolova loop aborted, falling back to the native rotation')
        return super().do_perform()

    def get_switch_priority(self, current_char=None, has_intro=False, target_low_con=False):
        """场子永远要回到弗洛洛手上 —— 启动轴和循环轴都只能从她起跑。

        【至少要留一个 MUST 候选】: 全队都是 NO 的话框架只会打一下普攻原地打转。
        启动轴待跑时坎特蕾拉和卜灵都返回 NO, 所以这个 MUST 是必需的。
        宏正常跑的时候这个函数根本不会被调到(宏直接按数字键切人, 绕开框架的选人),
        所以这里的 MUST 只在"开局选人 / 切人失败 / 脱战重进"时起作用。

        【这里别打 INFO 日志】: 框架会对每个候选反复调用, 会刷屏。
        """
        if self.is_in_phro_cycle:
            return SwitchPriority.MUST
        return super().get_switch_priority(current_char, has_intro, target_low_con)

    def on_combat_end(self, chars):
        self.release_attack()
        self.poking = False
        self.cur = None
        return super().on_combat_end(chars)
